INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P1','Nguyễn Minh (阮明)',22,'Du học sinh Việt Nam mới đến Trung Quốc, học Thương mại quốc tế','Lễ phép, hơi rón rén, tiếng Trung mức trung bình, cẩn thận');
INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P2','Lâm Vũ (林宇)',23,'Bạn cùng phòng người Trung Quốc','Nhiệt tình, thoải mái, hay giúp đỡ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM01','呀','Hỏi/đáp nhẹ nhàng, giảm cảm giác cứng nhắc');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM02','啦','Nhẹ nhõm, vui vẻ, hoặc dứt điểm một việc');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM03','哦','Chỉnh/bổ sung thông tin nhẹ nhàng, không phủ định gắt');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM04','呢','Bổ sung/giải thích, hoặc thể hiện hơi bối rối/băn khoăn');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM05','啊','Hỏi lịch sự hoặc biểu lộ ngạc nhiên nhẹ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM06','哈','Nhắc nhẹ, thân thiện, kéo gần khoảng cách hội thoại');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM07','吧','Đề nghị/xác nhận mang tính dò hỏi, không chắc chắn tuyệt đối');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM08','嘞','Đáp lời sảng khoái, đậm chất khẩu ngữ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM09','嘛','Giọng hiển nhiên, thân mật, xoa dịu');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM10','哎呀','Tự trách/ngại ngùng bất ngờ');
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM11','咯','Xác nhận nhẹ nhàng, coi như hiển nhiên/dứt khoát, giọng thân mật');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_A','Gọi lái xe taxi/xe công nghệ là ''thầy'' (师傅) bất kể tuổi','Cách gọi phổ biến, thể hiện sự tôn trọng, không phân biệt tuổi tác. Lặp lại ở các tình huống đi taxi/xe công nghệ.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_B','Ưu tiên thanh toán quét mã; mạng chậm thì chờ, không thúc ép; một số quán chỉ nhận quét mã','Thanh toán điện tử là chủ đạo ở Trung Quốc; tài xế/người bán thường kiên nhẫn chờ khách quét mã, và nhiều cửa hàng nhỏ không nhận tiền mặt.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_C','Ký túc xá quản lý theo quy định thống nhất, không có ngoại lệ','Giờ đóng cửa và quy định khách thăm áp dụng chung cho mọi sinh viên, kể cả sinh viên quốc tế.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_D','Thiết bị công cộng (đèn, máy giặt...) hỏng thì báo quản lý, không tự sửa','Trường/ký túc xá chịu trách nhiệm sửa chữa miễn phí; có thể đổi sang thiết bị khác dùng tạm trong lúc chờ.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_E','Thủ tục hành chính với sinh viên quốc tế cần thêm giấy xác nhận đang học','Chỉ hộ chiếu và visa thường chưa đủ để mở tài khoản ngân hàng hay làm một số thủ tục, cần bổ sung giấy xác nhận đang học.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_F','Thanh toán di động bắt buộc xác thực danh tính thật','Sinh viên nước ngoài dùng hộ chiếu để xác thực, không cần CMND Trung Quốc.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_G','Hồ sơ thiếu giấy tờ thường được cho nộp bổ sung có thời hạn','Chỉ cần thành thật xin lỗi và có kế hoạch bổ sung rõ ràng, không cần quá lo lắng.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_H','Biên phòng/hải quan làm việc theo nguyên tắc trung thực, ngắn gọn','Không cần giải thích dài dòng, chỉ cần trả lời đúng và đủ thông tin được hỏi.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_I','Đi nhầm chiều tàu điện ngầm có thể đổi chiều miễn phí ngay tại sân ga đối diện','Không cần ra cổng mua lại vé, chỉ cần sang sân ga đối diện, việc chuyển tuyến trong nhà ga là miễn phí.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_J','Có thể lịch sự đề nghị lái xe đổi lộ trình khi tắc đường mà không bị phụ thu thêm','Tài xế taxi/xe công nghệ thường chủ động hợp tác khi khách giải thích lý do gấp.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_K','Phí vận chuyển thực tế có thể cao hơn phí dự tính trên app nếu hàng quá cân','Đây là phụ thu hợp lệ theo cân nặng thật, không phải shipper tự ý tính thêm.');
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_M','Nên chủ động hỏi lại nhân viên nếu nghi ngờ thông tin vừa thay đổi (băng chuyền, cổng ra...)','Không nên tự đoán theo đám đông; thông tin sân bay có thể thay đổi tạm thời so với bảng hiển thị ban đầu.');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT201','S1','Điền tờ khai nhập cảnh trên máy bay','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V201','SIT201','P1','suon_se','ban_chinh_thuc','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','Tiếp viên trên máy bay giữ giọng mềm mỏng, hành khách hỏi thoải mái không cần quá rón rén.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_01','V201','Nguyễn Minh',1,'乘务员您好，我不太会填这个入境登记卡，能麻烦您教教我吗？','chéng wù yuán nín hǎo， wǒ bù tài huì tián zhè ge rù jìng dēng jì kǎ， néng má fán nín jiāo jiāo wǒ ma？','Chào chị tiếp viên, tôi không rành cách điền tờ khai nhập cảnh này lắm, phiền chị hướng dẫn giúp tôi được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_02','V201','Tiếp viên',2,'没问题呀，我来跟你说。你护照上的信息照着填就行啦。','méi wèn tí ya， wǒ lái gēn nǐ shuō。 nǐ hù zhào shàng de xìn xī zhào zhe tián jiù xíng la。','Không vấn đề gì đâu, để tôi chỉ cho bạn. Cứ theo thông tin trên hộ chiếu mà điền là được rồi.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_03','V201','Nguyễn Minh',3,'好的，请问“来华事由”这一栏，我填“留学”就可以了吧？','hǎo de， qǐng wèn “lái huá shì yóu” zhè yī lán， wǒ tián “liú xué” jiù kě yǐ le ba？','Dạ vâng, cho tôi hỏi mục "lý do đến Trung Quốc", tôi điền "du học" là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_04','V201','Tiếp viên',4,'对的，完全没问题。停留时间就写你签证上的时长哦。','duì de， wán quán méi wèn tí。 tíng liú shí jiān jiù xiě nǐ qiān zhèng shàng de shí cháng ó。','Đúng rồi, hoàn toàn ổn. Còn thời gian lưu trú thì ghi theo thời hạn trên visa của bạn nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_05','V201','Nguyễn Minh',5,'那籍贯和出生地，直接填越南可以吗？','nà jí guàn hé chū shēng dì， zhí jiē tián yuè nán kě yǐ ma？','Vậy còn nguyên quán với nơi sinh, tôi ghi luôn là Việt Nam được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_06','V201','Tiếp viên',6,'可以的，不用写太详细，简洁填写就好啦。','kě yǐ de， bù yòng xiě tài xiáng xì， jiǎn jié tián xiě jiù hǎo la。','Được chứ, không cần ghi chi tiết quá đâu, viết ngắn gọn là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_07','V201','Nguyễn Minh',7,'太谢谢您了，帮了我大忙！','tài xiè xiè nín le， bāng le wǒ dà máng！','Cảm ơn chị nhiều lắm, chị giúp tôi được một việc lớn đó!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_08','V201','Tiếp viên',8,'不客气哈，有不懂的随时再问我。','bú kè qì hā， yǒu bù dǒng de suí shí zài wèn wǒ。','Không có gì đâu, có gì chưa hiểu thì cứ hỏi tôi bất cứ lúc nào nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT202','S1','Hỏi lối ra sân bay','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V202','SIT202','P1','suon_se','ban_chinh_thuc','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','Nhân viên sân bay chỉ đường thường dùng cách nói dễ hiểu, không dùng thuật ngữ phức tạp.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_01','V202','Nguyễn Minh',1,'您好，麻烦问一下，机场出口是往这边走吗？','nín hǎo， má fán wèn yī xià， jī chǎng chū kǒu shì wǎng zhè biān zǒu ma？','Chào chị, phiền chị cho tôi hỏi, lối ra sân bay là đi hướng này ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_02','V202','Nhân viên',2,'不是哦，这边是转机通道，出口在你的左手边呢。','bú shì ó， zhè biān shì zhuǎn jī tōng dào， chū kǒu zài nǐ de zuǒ shǒu biān ne。','Không phải đâu, đây là lối nối chuyến, cửa ra ở phía bên tay trái của anh đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_03','V202','Nguyễn Minh',3,'左手边是吗？一直直走就到了吧？','zuǒ shǒu biān shì ma？ yì zhí zhí zǒu jiù dào le ba？','Bên tay trái à? Cứ đi thẳng là tới đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_04','V202','Nhân viên',4,'对的，直走到底左转，跟着“国内到达”的牌子走就行啦。','duì de， zhí zǒu dào dǐ zuǒ zhuǎn， gēn zhe “guó nèi dào dá” de pái zi zǒu jiù xíng la。','Đúng rồi, đi thẳng đến cuối rồi rẽ trái, cứ theo biển "Đến nội địa" mà đi là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_05','V202','Nguyễn Minh',5,'好的，我明白了，谢谢您！','hǎo de， wǒ míng bái le， xiè xiè nín！','Dạ vâng, tôi hiểu rồi, cảm ơn chị!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_06','V202','Nhân viên',6,'没事的，慢走哈！','méi shì de， màn zǒu hā！','Không có gì đâu, đi cẩn thận nhé!','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT203','S1','Hỏi băng chuyền nhận hành lý','Băng chuyền bị đổi tạm thời so với thông tin ban đầu','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V203','SIT203','P1','twist','chinh_thuc','Băng chuyền bị đổi tạm thời so với thông tin ban đầu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_01','V203','Nguyễn Minh',1,'您好，我想请问一下，国际航班的行李在哪里领取啊？','nín hǎo， wǒ xiǎng qǐng wèn yī xià， guó jì háng bān de xíng lǐ zài nǎ lǐ lǐng qǔ a？','Xin chào, tôi muốn hỏi hành lý của chuyến bay quốc tế được nhận ở đâu ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_02','V203','Nhân viên',2,'您好，请问你的航班号是多少呢？','nín hǎo， qǐng wèn nǐ de háng bān hào shì duō shǎo ne？','Xin chào, xin hỏi số hiệu chuyến bay của anh là gì ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_03','V203','Nguyễn Minh',3,'是VN520航班，麻烦您查一下。','shì VN520 háng bān， má fán nín chá yī xià。','Là chuyến bay VN520, phiền chị kiểm tra giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_04','V203','Nhân viên',4,'稍等，这班航班原本在3号转盘，刚刚临时调整到5号转盘了哦。','shāo děng， zhè bān háng bān yuán běn zài 3 hào zhuàn pán， gāng gāng lín shí diào zhěng dào 5 hào zhuàn pán le ó。','Xin chờ một chút, chuyến bay này ban đầu ở băng chuyền số 3, nhưng vừa mới được điều chỉnh tạm thời sang băng chuyền số 5 ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_05','V203','Nguyễn Minh',5,'原来是这样，还好我问了，不然就走错啦。','yuán lái shì zhè yàng， hái hǎo wǒ wèn le， bù rán jiù zǒu cuò la。','Ra là vậy, may mà tôi hỏi, không thì đã đi nhầm chỗ rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_06','V203','Nhân viên',6,'是的，近期偶尔会调整，你直接去5号转盘等候就行。','shì de， jìn qī ǒu ěr huì tiáo zhěng， nǐ zhí jiē qù 5 hào zhuàn pán děng hòu jiù xíng。','Vâng, gần đây thỉnh thoảng có điều chỉnh, anh cứ đến thẳng băng chuyền số 5 chờ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_07','V203','Nguyễn Minh',7,'好的，非常感谢您！','hǎo de， fēi cháng gǎn xiè nín！','Vâng, cảm ơn chị rất nhiều!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT204','S5','Mua SIM và tư vấn gói cước','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V204','SIT204','P1','twist','tuy_y','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_01','V204','Nguyễn Minh',1,'你好，我是留学生，想办一张流量多的电话卡，有合适的套餐吗？','nǐ hǎo， wǒ shì liú xué shēng， xiǎng bàn yī zhāng liú liàng duō de diàn huà kǎ， yǒu hé shì de tào cān ma？','Chào bạn, mình là du học sinh, muốn mua một cái sim data nhiều nhiều, có gói nào hợp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_02','V204','Nhân viên',2,'有的呀，这款学生套餐性价比超高，每月超多流量呢。','yǒu de ya， zhè kuǎn xué shēng tào cān xìng jià bǐ chāo gāo， měi yuè chāo duō liú liàng ne。','Có chứ, gói sinh viên này ngon bổ rẻ lắm, mỗi tháng data siêu nhiều luôn đó.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_03','V204','Nguyễn Minh',3,'那这个套餐可以直接当场激活吧？','nà zhè ge tào cān kě yǐ zhí jiē dāng chǎng jī huó ba？','Vậy gói này kích hoạt luôn tại chỗ được hả?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_04','V204','Nhân viên',4,'本来可以的，不过今天系统有点卡，需要等两分钟哦。','běn lái kě yǐ de， bù guò jīn tiān xì tǒng yǒu diǎn kǎ， xū yào děng liǎng fēn zhōng ó。','Bình thường thì được, nhưng hôm nay hệ thống hơi lag chút, phải chờ tầm hai phút nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_05','V204','Nguyễn Minh',5,'没事的，我可以等，麻烦你啦。','méi shì de， wǒ kě yǐ děng， má fán nǐ la。','Không sao đâu, mình đợi được, phiền bạn nha.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_06','V204','Nhân viên',6,'不麻烦！马上就好，激活后我帮你调好网络设置哈。','bù má fán！ mǎ shàng jiù hǎo， jī huó hòu wǒ bāng nǐ diào hǎo wǎng luò shè zhì hā。','Không phiền đâu! Xong ngay thôi, kích hoạt xong mình chỉnh luôn cài đặt mạng cho bạn nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_07','V204','Nguyễn Minh',7,'太好了，谢谢你！','tài hǎo le， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT205','S4','Trả lời biên phòng khi nhập cảnh','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V205','SIT205','P1','suon_se','chinh_thuc','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_01','V205','Biên phòng',1,'你好，出示一下护照和签证。来华目的是什么？','nǐ hǎo， chū shì yī xià hù zhào hé qiān zhèng。 lái huá mù dì shì shén me？','Xin chào, xin xuất trình hộ chiếu và visa. Mục đích đến Trung Quốc của anh là gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_02','V205','Nguyễn Minh',2,'您好，我来中国留学的。','nín hǎo， wǒ lái zhōng guó liú xué de。','Xin chào, tôi đến Trung Quốc để du học.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_03','V205','Biên phòng',3,'在哪所学校就读？什么专业？','zài nǎ suǒ xué xiào jiù dú？ shén me zhuān yè？','Anh học tại trường nào? Chuyên ngành gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_04','V205','Nguyễn Minh',4,'我在省城理工大学，就读国际贸易专业。','wǒ zài shěng chéng lǐ gōng dà xué， jiù dú guó jì mào yì zhuān yè。','Tôi học tại 省城理工大学, chuyên ngành Thương mại quốc tế.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_05','V205','Biên phòng',5,'学习时长多久？资金来源是哪里？','xué xí shí cháng duō jiǔ？ zī jīn lái yuán shì nǎ lǐ？','Thời gian học bao lâu? Nguồn kinh phí từ đâu?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_06','V205','Nguyễn Minh',6,'我学习四年，学费和生活费由家里提供。','wǒ xué xí sì nián， xué fèi hé shēng huó fèi yóu jiā lǐ tí gōng。','Tôi học bốn năm, học phí và sinh hoạt phí do gia đình chu cấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_07','V205','Biên phòng',7,'好的，信息核对无误，入境通过。','hǎo de， xìn xī hé duì wú wù， rù jìng tōng guò。','Được rồi, thông tin đối chiếu chính xác, cho phép nhập cảnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_08','V205','Nguyễn Minh',8,'谢谢工作人员！','xiè xiè gōng zuò rén yuán！','Cảm ơn cán bộ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT206','S4','Xin biên phòng nói chậm/lặp lại','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V206','SIT206','P1','suon_se','chinh_thuc','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_01','V206','Biên phòng',1,'你本次入境是否携带校外兼职相关材料？','nǐ běn cì rù jìng shì fǒu xié dài xiào wài jiān zhí xiāng guān cái liào？','Lần nhập cảnh này anh có mang theo giấy tờ liên quan đến việc làm thêm ngoài trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_02','V206','Nguyễn Minh',2,'不好意思，我没太听懂您的问题呢。','bù hǎo yì sī， wǒ méi tài tīng dǒng nín de wèn tí ne。','Xin lỗi, tôi chưa nghe rõ câu hỏi của ông/bà ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_03','V206','Biên phòng',3,'没关系，那我放慢语速，再说一遍。','méi guān xì， nà wǒ fàng màn yǔ sù， zài shuō yī biàn。','Không sao, để tôi nói chậm lại và nhắc lại một lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_04','V206','Nguyễn Minh',4,'麻烦您了，我的中文听力还不太好。','má fán nín le， wǒ de zhōng wén tīng lì hái bù tài hǎo。','Phiền ông/bà, khả năng nghe tiếng Trung của tôi vẫn chưa tốt lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_05','V206','Biên phòng',5,'没事，我问你有没有带校外工作、兼职的证明材料？','méi shì， wǒ wèn nǐ yǒu méi yǒu dài xiào wài gōng zuò、 jiān zhí de zhèng míng cái liào？','Không sao, tôi hỏi là anh có mang theo giấy tờ chứng minh việc làm, làm thêm bên ngoài trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_06','V206','Nguyễn Minh',6,'没有的，我目前只专注学业，没有准备兼职材料。','méi yǒu de， wǒ mù qián zhǐ zhuān zhù xué yè， méi yǒu zhǔn bèi jiān zhí cái liào。','Không có, hiện tại tôi chỉ tập trung học tập, không chuẩn bị giấy tờ làm thêm gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_07','V206','Biên phòng',7,'好的，了解了。','hǎo de， liǎo jiě le。','Được rồi, tôi hiểu rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT207','S4','Khai báo hải quan','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V207','SIT207','P1','suon_se','chinh_thuc','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_01','V207','Hải quan',1,'你好，请问你本次入境有没有需要申报的物品？','nǐ hǎo， qǐng wèn nǐ běn cì rù jìng yǒu méi yǒu xū yào shēn bào de wù pǐn？','Xin chào, xin hỏi lần nhập cảnh này anh có vật phẩm gì cần khai báo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_02','V207','Nguyễn Minh',2,'您好……没有贵重物品，也没有超额物品，不用申报。','nín hǎo…… méi yǒu guì zhòng wù pǐn， yě méi yǒu chāo é wù pǐn， bù yòng shēn bào。','Dạ... không có đồ giá trị cao, cũng không mang quá định mức, không cần khai báo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_03','V207','Hải quan',3,'有没有携带大量现金、电子产品或者管制物品？','yǒu méi yǒu xié dài dà liàng xiàn jīn、 diàn zi chǎn pǐn huò zhě guǎn zhì wù pǐn？','Anh có mang theo số lượng lớn tiền mặt, thiết bị điện tử hay vật phẩm bị kiểm soát không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_04','V207','Nguyễn Minh',4,'没有的，只带了个人生活用品和少量现金。','méi yǒu de， zhǐ dài le gè rén shēng huó yòng pǐn hé shǎo liàng xiàn jīn。','Không có, tôi chỉ mang đồ dùng cá nhân và một ít tiền mặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_05','V207','Hải quan',5,'好的，确认无申报物品，可以通行了。','hǎo de， què rèn wú shēn bào wù pǐn， kě yǐ tōng xíng le。','Được rồi, xác nhận không có vật phẩm cần khai báo, anh có thể đi qua.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_06','V207','Nguyễn Minh',6,'好的，谢谢您！','hǎo de， xiè xiè nín！','Vâng, cảm ơn ông/bà!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT208','S4','Khai báo thuốc mang theo','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V208','SIT208','P1','twist','chinh_thuc','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','Có thể mang theo thuốc tự dùng số lượng nhỏ; thuốc kê đơn nên có đơn thuốc dịch sang tiếng Trung và giữ lại vỏ hộp để thuận tiện khi kiểm tra.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_01','V208','Hải quan',1,'除了生活用品，还有其他需要申报的东西吗？','chú le shēng huó yòng pǐn， hái yǒu qí tā xū yào shēn bào de dōng xī ma？','Ngoài đồ dùng sinh hoạt ra, anh còn vật gì khác cần khai báo không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_02','V208','Nguyễn Minh',2,'有的，我随身带了一些常用感冒药和肠胃药，需要申报吧？','yǒu de， wǒ suí shēn dài le yī xiē cháng yòng gǎn mào yào hé cháng wèi yào， xū yào shēn bào ba？','Dạ có, tôi có mang theo một ít thuốc cảm và thuốc dạ dày thông thường, vậy có cần khai báo không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_03','V208','Hải quan',3,'是的，自用药品需要报备，带了多少数量呢？','shì de， zì yòng yào pǐn xū yào bào bèi， dài le duō shǎo shù liàng ne？','Đúng vậy, thuốc dùng cá nhân cần khai báo, anh mang theo số lượng bao nhiêu?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04','V208','Nguyễn Minh',4,'都是个人短期自用的，没有大批量携带哦。','dōu shì gè rén duǎn qī zì yòng de， méi yǒu dà pī liàng xié dài ó。','Đều là dùng cá nhân trong thời gian ngắn thôi, tôi không mang số lượng lớn đâu ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04B','V208','Hải quan',5,'有处方或者药品说明书吗？','yǒu chǔ fāng huò zhě yào pǐn shuō míng shū ma？','Có đơn thuốc hay tờ hướng dẫn sử dụng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04C','V208','Nguyễn Minh',6,'呃……处方忘记翻译成中文了，只带了药盒。','è…… chǔ fāng wàng jì fān yì chéng zhōng wén le， zhǐ dài le yào hé。','Ơ... đơn thuốc em quên dịch sang tiếng Trung rồi, chỉ mang theo hộp thuốc thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_05','V208','Hải quan',8,'我看一下，没问题，自用常规药品可以放行，无需登记。','wǒ kàn yī xià， méi wèn tí， zì yòng cháng guī yào pǐn kě yǐ fàng xíng， wú xū dēng jì。','Để tôi xem qua, không vấn đề gì, thuốc thông thường dùng cá nhân được phép thông qua, không cần đăng ký.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_06','V208','Nguyễn Minh',9,'太好了，谢谢您的耐心核对！','tài hǎo le， xiè xiè nín de nài xīn hé duì！','Tuyệt quá, cảm ơn ông/bà đã kiên nhẫn kiểm tra!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_07','V208','Hải quan',10,'不客气，下次尽量保留药品外包装哦。','bú kè qì， xià cì jǐn liàng bǎo liú yào pǐn wài bāo zhuāng ó。','Không có gì, lần sau anh cố gắng giữ lại bao bì ngoài của thuốc nhé.','AM03');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT209','S1','Báo hành lý hư hỏng','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V209','SIT209','P1','that_bai_nhe','ban_chinh_thuc','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','Hành lý hư hỏng ở sân bay được đăng ký bồi thường miễn phí; cần giữ thẻ hành lý và thẻ lên máy bay, không tự bỏ đi rồi mới báo sau.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_01','V209','Nguyễn Minh',1,'您好，麻烦您，我的行李箱好像被摔坏了。','nín hǎo， má fán nín， wǒ de xíng lǐ xiāng hǎo xiàng bèi shuāi huài le。','Chào chị, phiền chị xem giúp, vali của tôi hình như bị va đập hỏng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_02','V209','Nhân viên',2,'别着急，我看一下，是箱体破损还是轮子损坏呀？','bié zháo jí， wǒ kàn yī xià， shì xiāng tǐ pò sǔn hái shì lún zi sǔn huài ya？','Anh đừng lo, để tôi xem, là thân vali bị hỏng hay bánh xe bị hỏng vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_03','V209','Nguyễn Minh',3,'箱体侧面裂开了，里面的东西没坏，但是箱子没法用了。','xiāng tǐ cè miàn liè kāi le， lǐ miàn de dōng xī méi huài， dàn shì xiāng zi méi fǎ yòng le。','Mặt bên của vali bị nứt rồi, đồ bên trong không sao, nhưng cái vali thì không dùng được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04','V209','Nhân viên',4,'我明白了，需要登记你的航班信息和行李牌，后续走理赔流程呢。','wǒ míng bái le， xū yào dēng jì nǐ de háng bān xìn xī hé xíng lǐ pái， hòu xù zǒu lǐ péi liú chéng ne。','Tôi hiểu rồi, cần đăng ký thông tin chuyến bay và thẻ hành lý của anh, sau đó sẽ tiến hành thủ tục bồi thường.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04B','V209','Nguyễn Minh',5,'啊……那现场没办法直接换一个新的吗？','a…… nà xiàn chǎng méi bàn fǎ zhí jiē huàn yí gè xīn de ma？','À... vậy ở đây không có cách nào đổi ngay cái mới được sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04C','V209','Nhân viên',6,'现场没有更换服务，只能走理赔流程呢。','xiàn chǎng méi yǒu gēng huàn fú wù， zhǐ néng zǒu lǐ péi liú chéng ne。','Ở đây không có dịch vụ đổi ngay, chỉ có thể theo quy trình bồi thường thôi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_05','V209','Nguyễn Minh',7,'好的，我马上提供，大概多久能处理好呀？','hǎo de， wǒ mǎ shàng tí gōng， dà gài duō jiǔ néng chǔ lǐ hǎo ya？','Vâng, tôi cung cấp ngay đây, khoảng bao lâu thì xử lý xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_06','V209','Nhân viên',8,'三个工作日内会有结果，你耐心等待通知就行。','sān gè gōng zuò rì nèi huì yǒu jié guǒ， nǐ nài xīn děng dài tōng zhī jiù xíng。','Trong vòng ba ngày làm việc sẽ có kết quả, anh cứ kiên nhẫn chờ thông báo là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_07','V209','Nguyễn Minh',9,'辛苦您了，谢谢！','xīn kǔ nín le， xiè xiè！','Chị vất vả rồi, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT210','S6','Đổi tiền và hỏi tỷ giá','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V210','SIT210','P1','twist','ban_chinh_thuc','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_01','V210','Nguyễn Minh',1,'您好，我想把越南盾兑换成人民币，请问今天的汇率是多少啊？','nín hǎo， wǒ xiǎng bǎ yuè nán dùn duì huàn chéng rén mín bì， qǐng wèn jīn tiān de huì lǜ shì duō shǎo a？','Chào chị, tôi muốn đổi tiền Đồng Việt Nam sang Nhân dân tệ, cho tôi hỏi tỷ giá hôm nay là bao nhiêu ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_02','V210','Nhân viên',2,'您好，今日实时汇率在这里，机场汇率会比市区银行稍低一点哦。','nín hǎo， jīn rì shí shí huì lǜ zài zhè lǐ， jī chǎng huì lǜ huì bǐ shì qū yín háng shāo dī yì diǎn ó。','Chào anh, tỷ giá thực tế hôm nay ở đây, tỷ giá ở sân bay sẽ thấp hơn ngân hàng trong thành phố một chút đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_03','V210','Nguyễn Minh',3,'这样啊，那我先兑换一千元人民币可以吗？','zhè yàng a， nà wǒ xiān duì huàn yī qiān yuán rén mín bì kě yǐ ma？','Vậy à, vậy tôi đổi trước một nghìn Nhân dân tệ được không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_04','V210','Nhân viên',4,'可以的，需要出示你的护照登记信息哈。','kě yǐ de， xū yào chū shì nǐ de hù zhào dēng jì xìn xī hā。','Được chứ, anh cần xuất trình hộ chiếu để đăng ký thông tin nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_05','V210','Nguyễn Minh',5,'没问题，护照给您。那手续费是单独收取的吗？','méi wèn tí， hù zhào gěi nín。 nà shǒu xù fèi shì dān dú shōu qǔ de ma？','Không vấn đề gì, hộ chiếu của tôi đây. Vậy phí dịch vụ có tính riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_06','V210','Nhân viên',6,'小额兑换免手续费，已经帮你核算好了。','xiǎo é duì huàn miǎn shǒu xù fèi， yǐ jīng bāng nǐ hé suàn hǎo le。','Đổi số lượng nhỏ thì miễn phí dịch vụ, tôi đã tính toán xong cho anh rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_07','V210','Nguyễn Minh',7,'好的，那就兑换吧，谢谢您！','hǎo de， nà jiù duì huàn ba， xiè xiè nín！','Vâng, vậy thì đổi luôn nhé, cảm ơn chị!','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT211','S5','Kết nối WiFi sân bay','Xin mật khẩu wifi, phải xác thực qua số điện thoại','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V211','SIT211','P1','suon_se','tuy_y','Xin mật khẩu wifi, phải xác thực qua số điện thoại',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_01','V211','Nguyễn Minh',1,'你好，请问机场的免费WiFi密码是多少呀？','nǐ hǎo， qǐng wèn jī chǎng de miǎn fèi WiFi mì mǎ shì duō shǎo ya？','Chào bạn, cho mình hỏi mật khẩu WiFi miễn phí của sân bay là gì vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_02','V211','Nhân viên',2,'很简单的，密码是机场全称的首字母加八个八哦。','hěn jiǎn dān de， mì mǎ shì jī chǎng quán chēng de shǒu zì mǔ jiā bā gè bā ó。','Đơn giản lắm, mật khẩu là chữ cái đầu tên đầy đủ của sân bay cộng thêm tám số 8 nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_03','V211','Nguyễn Minh',3,'我试了一下，怎么连不上呢？','wǒ shì le yī xià， zěn me lián bù shàng ne？','Mình thử rồi mà sao không kết nối được nhỉ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_04','V211','Nhân viên',4,'需要先打开浏览器验证一下，登录之后就能用啦。','xū yào xiān dǎ kāi liú lǎn qì yàn zhèng yī xià， dēng lù zhī hòu jiù néng yòng la。','Bạn phải mở trình duyệt xác thực trước đã, đăng nhập xong là dùng được liền á.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_05','V211','Nguyễn Minh',5,'原来是这样，太感谢你啦！','yuán lái shì zhè yàng， tài gǎn xiè nǐ la！','Thì ra là vậy, cảm ơn bạn nhiều nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_06','V211','Nhân viên',6,'没事哒，有问题再问哈！','méi shì dá， yǒu wèn tí zài wèn hā！','Có gì đâu, có gì cứ hỏi lại nha!','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT212','S1','Gọi người đón, báo vị trí','Báo cho bạn đến đón biết mình đã tới và đang ở đâu','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V212','SIT212','P1','suon_se','tuy_y','Báo cho bạn đến đón biết mình đã tới và đang ở đâu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_01','V212','Nguyễn Minh',1,'宇哥，我已经到机场啦，顺利入境了！','yǔ gē， wǒ yǐ jīng dào jī chǎng la， shùn lì rù jìng le！','Anh Vũ ơi, em tới sân bay rồi nè, nhập cảnh suôn sẻ luôn!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_02','V212','Đón (Trần Vũ)',2,'太好了！你现在在哪个位置呀？','tài hǎo le！ nǐ xiàn zài zài nǎ ge wèi zhì ya？','Tốt quá! Giờ em đang ở chỗ nào vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_03','V212','Nguyễn Minh',3,'我在国内到达出口的问询台旁边呢。','wǒ zài guó nèi dào dá chū kǒu de wèn xún tái páng biān ne。','Em đang đứng cạnh quầy hỏi thông tin ở cửa ra đến nội địa nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_04','V212','Đón (Trần Vũ)',4,'好的，我马上就到，你就在原地等我别乱跑哈。','hǎo de， wǒ mǎ shàng jiù dào， nǐ jiù zài yuán dì děng wǒ bié luàn pǎo hā。','Được rồi, anh tới ngay đây, em cứ đứng yên đó đừng chạy lung tung nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_05','V212','Nguyễn Minh',5,'没问题，我就在这里等你，不着急的。','méi wèn tí， wǒ jiù zài zhè lǐ děng nǐ， bù zháo jí de。','Không sao đâu, em đứng đây đợi anh, không vội gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_06','V212','Đón (Trần Vũ)',6,'五分钟就到，一会儿见！','wǔ fēn zhōng jiù dào， yī huì er jiàn！','Năm phút nữa là tới, lát gặp nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT213','S1','Không thấy người đón, gọi xác nhận','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V213','SIT213','P1','twist','tuy_y','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_01','V213','Nguyễn Minh',1,'宇哥，我已经在出口等了十分钟了，没看到你呀。','yǔ gē， wǒ yǐ jīng zài chū kǒu děng le shí fēn zhōng le， méi kàn dào nǐ ya。','Anh Vũ ơi, em đợi ở cửa ra mười phút rồi mà chẳng thấy anh đâu.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_02','V213','Đón (Trần Vũ)',2,'哎呀抱歉！我走错出口了，我在二号出口，你在几号呀？','āi yā bào qiàn！ wǒ zǒu cuò chū kǒu le， wǒ zài èr hào chū kǒu， nǐ zài jǐ hào ya？','Ôi xin lỗi em! Anh đi lộn cửa ra rồi, anh đang ở cửa số 2, em ở cửa số mấy vậy?','AM10');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03','V213','Nguyễn Minh',3,'我在一号出口，难怪看不到呢。','wǒ zài yī hào chū kǒu， nán guài kàn bú dào ne。','Em ở cửa số 1, thảo nào không thấy anh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03B','V213','Đón (Trần Vũ)',4,'一号？','yī hào？','Số 1 á?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_04','V213','Đón (Trần Vũ)',5,'太不好意思了！我马上走通道过来，两分钟就到你那边。','tài bù hǎo yì sī le！ wǒ mǎ shàng zǒu tōng dào guò lái， liǎng fēn zhōng jiù dào nǐ nà biān。','Ngại quá đi! Anh chạy qua lối đi ngay đây, hai phút nữa là tới chỗ em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_05','V213','Nguyễn Minh',6,'没事没事，不着急，我慢慢等你就好啦。','méi shì méi shì， bù zháo jí， wǒ màn màn děng nǐ jiù hǎo la。','Không sao không sao, không vội đâu, em từ từ đợi anh là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_06','V213','Đón (Trần Vũ)',7,'辛苦你啦，马上汇合！','xīn kǔ nǐ la， mǎ shàng huì hé！','Em vất vả rồi, anh tới liền đây!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT214','S2','Đặt xe công nghệ, xác nhận tài xế','Xác nhận đúng tài xế và biển số trước khi lên xe','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V214','SIT214','P1','suon_se','tuy_y','Xác nhận đúng tài xế và biển số trước khi lên xe',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_01','V214','Tài xế',1,'你好，是尾号3621的乘客吧？我到机场上车点了。','nǐ hǎo， shì wěi hào 3621 de chéng kè ba？ wǒ dào jī chǎng shàng chē diǎn le。','Chào bạn, có phải khách hàng số đuôi 3621 không? Tôi đến điểm đón ở sân bay rồi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_02','V214','Nguyễn Minh',2,'对的是我！麻烦问一下，您的车牌号是多少呀？','duì de shì wǒ！ má fán wèn yī xià， nín de chē pái hào shì duō shǎo ya？','Đúng em đây ạ! Cho em hỏi biển số xe của anh là gì vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_03','V214','Tài xế',3,'车牌是浙A8523K，黑色轿车，很好认的。','chē pái shì zhè A8523K， hēi sè jiào chē， hěn hǎo rèn de。','Biển số xe là Chiết A8523K, xe con màu đen, dễ nhận ra lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_04','V214','Nguyễn Minh',4,'好的，我看到您的车了，马上走过去哈。','hǎo de， wǒ kàn dào nín de chē le， mǎ shàng zǒu guò qù hā。','Dạ, em thấy xe anh rồi, em đi qua liền nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_05','V214','Tài xế',5,'不急，慢慢走，注意身边行李就行。','bù jí， màn màn zǒu， zhù yì shēn biān xíng lǐ jiù xíng。','Không vội đâu, cứ từ từ đi, chú ý hành lý bên người là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_06','V214','Nguyễn Minh',6,'好嘞，辛苦您等我一下！','hǎo lei， xīn kǔ nín děng wǒ yī xià！','Dạ được, anh chờ em chút xíu nha, cảm ơn anh!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT215','S2','Báo địa chỉ đến cho tài xế','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V215','SIT215','P1','suon_se','tuy_y','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_01','V215','Tài xế',1,'同学，我们现在出发，你去哪里呀？','tóng xué， wǒ men xiàn zài chū fā， nǐ qù nǎ lǐ ya？','Bạn ơi, giờ mình xuất phát nhé, bạn đi đâu vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_02','V215','Nguyễn Minh',2,'师傅您好，麻烦去省城理工大学留学生公寓。','shī fù nín hǎo， má fán qù shěng chéng lǐ gōng dà xué liú xué shēng gōng yù。','Chào bác tài, phiền bác cho cháu đến ký túc xá lưu học sinh trường Đại học Bách khoa tỉnh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_03','V215','Tài xế',3,'是新校区那个留学生宿舍吧？','shì xīn xiào qū nà ge liú xué shēng sù shè ba？','Là ký túc xá lưu học sinh ở khu trường mới đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_04','V215','Nguyễn Minh',4,'对的！我第一次去，辛苦您多留意路线呢。','duì de！ wǒ dì yī cì qù， xīn kǔ nín duō liú yì lù xiàn ne。','Dạ đúng rồi! Cháu đi lần đầu, phiền bác để ý đường giúp cháu nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_05','V215','Tài xế',5,'放心吧，这条路我常跑，不会走错的。','fàng xīn ba， zhè tiáo lù wǒ cháng pǎo， bú huì zǒu cuò de。','Yên tâm đi, con đường này bác chạy suốt à, không đi lạc đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_06','V215','Nguyễn Minh',6,'那就太好了，谢谢您！','nà jiù tài hǎo le， xiè xiè nín！','Vậy thì tốt quá, cảm ơn bác nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT216','S2','Thanh toán quét mã sau khi đi taxi','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V216','SIT216','P1','twist','tuy_y','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_01','V216','Tài xế',1,'同学，我们到学校门口啦，车程结束了。','tóng xué， wǒ men dào xué xiào mén kǒu la， chē chéng jié shù le。','Bạn ơi, mình tới cổng trường rồi nè, chuyến xe kết thúc rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_02','V216','Nguyễn Minh',2,'好的！我想扫码支付，可是手机网络有点慢怎么办？','hǎo de！ wǒ xiǎng sǎo mǎ zhī fù， kě shì shǒu jī wǎng luò yǒu diǎn màn zěn me bàn？','Dạ vâng! Cháu muốn quét mã thanh toán mà mạng điện thoại hơi chậm, làm sao đây ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_03','V216','Tài xế',3,'没关系呀，不急，你慢慢加载就行。','méi guān xì ya， bù jí， nǐ màn màn jiā zài jiù xíng。','Không sao đâu, không gấp, cứ từ từ chờ mạng tải là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_04','V216','Nguyễn Minh',4,'终于好了，已经支付成功啦，您看一下！','zhōng yú hǎo le， yǐ jīng zhī fù chéng gōng la， nín kàn yī xià！','Cuối cùng cũng được rồi, thanh toán thành công rồi ạ, bác xem giúp cháu nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_05','V216','Tài xế',5,'收到了，没问题。路上辛苦了，欢迎下次坐车哈！','shōu dào le， méi wèn tí。 lù shàng xīn kǔ le， huān yíng xià cì zuò chē hā！','Nhận được rồi, ổn rồi. Đi đường vất vả rồi, lần sau lại đón nhé!','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_06','V216','Nguyễn Minh',6,'谢谢师傅，再见！','xiè xiè shī fù， zài jiàn！','Cảm ơn bác tài, cháu chào bác!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT217','S7','Nhận phòng ký túc xá','Xuất trình giấy tờ, nhận phòng và chìa khóa','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V217','SIT217','P1','suon_se','ban_chinh_thuc','Xuất trình giấy tờ, nhận phòng và chìa khóa',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_01','V217','Nguyễn Minh',1,'老师您好，我是新来的留学生，今天来办理宿舍入住。','lǎo shī nín hǎo， wǒ shì xīn lái de liú xué shēng， jīn tiān lái bàn lǐ sù shè rù zhù。','Chào cô/thầy, em là lưu học sinh mới, hôm nay em đến làm thủ tục nhận phòng ký túc xá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_02','V217','Tiền sảnh',2,'好的，请出示你的护照和入学通知书哦。','hǎo de， qǐng chū shì nǐ de hù zhào hé rù xué tōng zhī shū ó。','Được, em cho tôi xem hộ chiếu và giấy báo nhập học nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_03','V217','Nguyễn Minh',3,'好的，这是我的证件和录取文件，您看一下。','hǎo de， zhè shì wǒ de zhèng jiàn hé lù qǔ wén jiàn， nín kàn yī xià。','Dạ vâng, đây là giấy tờ và giấy báo trúng tuyển của em, mời thầy/cô xem ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_04','V217','Tiền sảnh',4,'信息核对无误，这是你的宿舍钥匙和门禁卡。','xìn xī hé duì wú wù， zhè shì nǐ de sù shè yào shi hé mén jìn kǎ。','Thông tin đối chiếu không có vấn đề gì, đây là chìa khóa phòng và thẻ ra vào của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_05','V217','Nguyễn Minh',5,'请问我的宿舍是几楼几号呀？','qǐng wèn wǒ de sù shè shì jǐ lóu jǐ hào ya？','Cho em hỏi phòng của em ở tầng mấy, phòng số bao nhiêu ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_06','V217','Tiền sảnh',6,'四楼408室，单人留学生宿舍，条件还不错呢。','sì lóu 408 shì， dān rén liú xué shēng sù shè， tiáo jiàn hái bú cuò ne。','Tầng bốn, phòng 408, phòng đơn dành cho lưu học sinh, điều kiện cũng khá tốt đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_07','V217','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn thầy/cô rất nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT218','S7','Ký hợp đồng ở ký túc xá','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V218','SIT218','P1','suon_se','ban_chinh_thuc','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_01','V218','Tiền sảnh',1,'这是留学生住宿合同，你仔细看一下条款哦。','zhè shì liú xué shēng zhù sù hé tóng， nǐ zǐ xì kàn yī xià tiáo kuǎn ó。','Đây là hợp đồng ở ký túc xá dành cho lưu học sinh, em xem kỹ các điều khoản nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_02','V218','Nguyễn Minh',2,'好的，请问主要是住宿规定和缴费事项吧？','hǎo de， qǐng wèn zhǔ yào shì zhù sù guī dìng hé jiǎo fèi shì xiàng ba？','Dạ vâng, cho em hỏi chủ yếu là quy định về ở trọ và các khoản phí phải nộp đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_03','V218','Tiền sảnh',3,'对的，还有作息时间、宿舍安全的相关要求呢。','duì de， hái yǒu zuò xī shí jiān、 sù shè ān quán de xiāng guān yāo qiú ne。','Đúng vậy, còn có quy định về giờ giấc sinh hoạt và an toàn ký túc xá nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_04','V218','Nguyễn Minh',4,'我看完了，没有疑问，可以签字了吗？','wǒ kàn wán le， méi yǒu yí wèn， kě yǐ qiān zì le ma？','Em xem xong rồi, không có thắc mắc gì, giờ em ký được chưa ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_05','V218','Tiền sảnh',5,'可以的，在这里签上你的中文或英文姓名就行。','kě yǐ de， zài zhè lǐ qiān shàng nǐ de zhōng wén huò yīng wén xìng míng jiù xíng。','Được rồi, em ký tên tiếng Trung hoặc tiếng Anh vào đây là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_06','V218','Nguyễn Minh',6,'好的，我签好了，交给您。','hǎo de， wǒ qiān hǎo le， jiāo gěi nín。','Dạ, em ký xong rồi, gửi lại thầy/cô ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_07','V218','Tiền sảnh',7,'手续办完，祝你入住愉快！','shǒu xù bàn wán， zhù nǐ rù zhù yú kuài！','Xong thủ tục rồi, chúc em ở đây vui vẻ nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT219','S7','Hỏi WiFi, phòng giặt, giờ đóng cửa ký túc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V219','SIT219','P1','suon_se','ban_chinh_thuc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_01','V219','Nguyễn Minh',1,'老师您好，我想咨询几个宿舍的相关问题可以吗？','lǎo shī nín hǎo， wǒ xiǎng zī xún jǐ gè sù shè de xiāng guān wèn tí kě yǐ ma？','Chào thầy/cô, em muốn hỏi vài vấn đề liên quan đến ký túc xá được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_02','V219','Tiền sảnh',2,'当然可以，你尽管问哈。','dāng rán kě yǐ， nǐ jǐn guǎn wèn hā。','Được chứ, em cứ hỏi thoải mái nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_03','V219','Nguyễn Minh',3,'请问宿舍WiFi密码是多少？洗衣房在哪个位置啊？','qǐng wèn sù shè WiFi mì mǎ shì duō shǎo？ xǐ yī fáng zài nǎ ge wèi zhì a？','Cho em hỏi mật khẩu WiFi ký túc xá là gì ạ? Phòng giặt đồ ở đâu vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_04','V219','Tiền sảnh',4,'WiFi密码贴在房门背后，洗衣房在二楼楼梯口呢。','WiFi mì mǎ tiē zài fáng mén bèi hòu， xǐ yī fáng zài èr lóu lóu tī kǒu ne。','Mật khẩu WiFi dán ở sau cửa phòng, phòng giặt đồ ở đầu cầu thang tầng hai nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_05','V219','Nguyễn Minh',5,'那宿舍门禁的开关时间是几点呀？','nà sù shè mén jìn de kāi guān shí jiān shì jǐ diǎn ya？','Vậy giờ mở đóng cửa ra vào ký túc xá là mấy giờ ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_06','V219','Tiền sảnh',6,'早上六点开门，晚上十一点关门，记得按时回寝哦。','zǎo shàng liù diǎn kāi mén， wǎn shàng shí yì diǎn guān mén， jì de àn shí huí qǐn ó。','Sáu giờ sáng mở cửa, mười một giờ tối đóng cửa, nhớ về phòng đúng giờ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_07','V219','Nguyễn Minh',7,'好的，我都记住了，谢谢您！','hǎo de， wǒ dōu jì zhù le， xiè xiè nín！','Dạ, em nhớ hết rồi ạ, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT220','S7','Báo hỏng đèn phòng','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V220','SIT220','P1','that_bai_nhe','tuy_y','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_01','V220','Nguyễn Minh',1,'阿姨您好，我是408宿舍的同学，房间的顶灯不亮了。','ā yí nín hǎo， wǒ shì 408 sù shè de tóng xué， fáng jiān de dǐng dēng bù liàng le。','Cô ơi, em là sinh viên phòng 408, đèn trần trong phòng em bị hỏng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_02','V220','Quản lý',2,'是完全不亮，还是一闪一闪的呀？','shì wán quán bù liàng， hái shì yī shǎn yī shǎn de ya？','Là hoàn toàn không sáng, hay là nhấp nháy vậy em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_03','V220','Nguyễn Minh',3,'完全打不开，应该是坏掉了呢。','wán quán dǎ bù kāi， yīng gāi shì huài diào le ne。','Hoàn toàn không bật được luôn, chắc là hỏng rồi cô ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_04','V220','Quản lý',4,'好的，我帮你登记报修，维修师傅明天上午过来修哈。','hǎo de， wǒ bāng nǐ dēng jì bào xiū， wéi xiū shī fù míng tiān shàng wǔ guò lái xiū hā。','Được rồi, cô đăng ký báo sửa giúp em, thợ sửa sẽ đến sửa vào sáng mai nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_05','V220','Nguyễn Minh',5,'好的，今晚只能先开台灯了，麻烦阿姨啦！','hǎo de， jīn wǎn zhǐ néng xiān kāi tái dēng le， má fán ā yí la！','Dạ vâng, tối nay em đành phải dùng đèn bàn tạm vậy, phiền cô quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_06','V220','Quản lý',6,'没事的，小事而已，明天肯定修好。','méi shì de， xiǎo shì ér yǐ， míng tiān kěn dìng xiū hǎo。','Không sao đâu, chuyện nhỏ thôi mà, mai chắc chắn sửa xong.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT221','S6','Mở tài khoản ngân hàng, lấy số','Lấy số thứ tự và điền đơn mở tài khoản','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V221','SIT221','P1','suon_se','chinh_thuc','Lấy số thứ tự và điền đơn mở tài khoản',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_01','V221','Nguyễn Minh',1,'您好，我想办理银行卡开户业务，请问怎么操作？','nín hǎo， wǒ xiǎng bàn lǐ yín háng kǎ kāi hù yè wù， qǐng wèn zěn me cāo zuò？','Chào anh/chị, tôi muốn làm thủ tục mở thẻ ngân hàng, cho tôi hỏi cần làm như thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_02','V221','Quản lý sảnh',2,'您好，先在取号机取个排队号，再填写这份开户申请表哦。','nín hǎo， xiān zài qǔ hào jī qǔ gè pái duì hào， zài tián xiě zhè fèn kāi hù shēn qǐng biǎo ó。','Chào anh, trước tiên anh lấy số thứ tự ở máy lấy số, rồi điền vào đơn mở tài khoản này nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_03','V221','Nguyễn Minh',3,'好的，表格上的信息我都如实填写就可以吧？','hǎo de， biǎo gé shàng de xìn xī wǒ dōu rú shí tián xiě jiù kě yǐ ba？','Vâng, tôi chỉ cần điền đúng theo thông tin thực tế vào đơn là được phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_04','V221','Quản lý sảnh',4,'对的，姓名、证件信息、住址全部填完整就行。','duì de， xìng míng、 zhèng jiàn xìn xī、 zhù zhǐ quán bù tián wán zhěng jiù xíng。','Đúng vậy, anh điền đầy đủ họ tên, thông tin giấy tờ và địa chỉ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_05','V221','Nguyễn Minh',5,'表格填好了，号也取到了，接下来等待叫号吗？','biǎo gé tián hǎo le， hào yě qǔ dào le， jiē xià lái děng dài jiào hào ma？','Tôi điền xong đơn rồi, cũng đã lấy số rồi, tiếp theo là chờ gọi số phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_06','V221','Quản lý sảnh',6,'是的，轮到你的时候直接去柜台办理即可。','shì de， lún dào nǐ de shí hòu zhí jiē qù guì tái bàn lǐ jí kě。','Vâng, đến lượt anh thì anh ra quầy làm thủ tục là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_07','V221','Nguyễn Minh',7,'好的，谢谢您的指导！','hǎo de， xiè xiè nín de zhǐ dǎo！','Vâng, cảm ơn anh/chị đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT222','S6','Xuất trình giấy tờ mở thẻ ngân hàng','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V222','SIT222','P1','twist','chinh_thuc','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_01','V222','Nhân viên',1,'您好，请问办理什么业务？','nín hǎo， qǐng wèn bàn lǐ shén me yè wù？','Chào anh, anh muốn làm thủ tục gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_02','V222','Nguyễn Minh',2,'您好，我是留学生，想办理储蓄卡开户。','nín hǎo， wǒ shì liú xué shēng， xiǎng bàn lǐ chǔ xù kǎ kāi hù。','Chào chị, tôi là du học sinh, muốn làm thủ tục mở thẻ tiết kiệm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_03','V222','Nhân viên',3,'麻烦出示你的护照、签证和学校在读证明哦。','má fán chū shì nǐ de hù zhào、 qiān zhèng hé xué xiào zài dú zhèng míng ó。','Phiền anh xuất trình hộ chiếu, visa và giấy xác nhận đang học tại trường giúp tôi nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_04','V222','Nguyễn Minh',4,'证件都在这里，在读证明我打印的黑白版可以吗？','zhèng jiàn dōu zài zhè lǐ， zài dú zhèng míng wǒ dǎ yìn de hēi bái bǎn kě yǐ ma？','Giấy tờ đều ở đây cả, giấy xác nhận đang học tôi in bản đen trắng có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_05','V222','Nhân viên',5,'可以的，黑白有效，我帮你录入系统信息。','kě yǐ de， hēi bái yǒu xiào， wǒ bāng nǐ lù rù xì tǒng xìn xī。','Được ạ, bản đen trắng vẫn có giá trị, để tôi nhập thông tin vào hệ thống cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_06','V222','Nguyễn Minh',6,'好的，辛苦您了！大概多久能办好呀？','hǎo de， xīn kǔ nín le！ dà gài duō jiǔ néng bàn hǎo ya？','Vâng, cảm ơn chị đã giúp đỡ! Khoảng bao lâu thì xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_07','V222','Nhân viên',7,'很快的，三分钟就能完成开卡流程。','hěn kuài de， sān fēn zhōng jiù néng wán chéng kāi kǎ liú chéng。','Nhanh thôi, chỉ ba phút là làm xong thẻ ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT223','S6','Kích hoạt thẻ ngân hàng mới','Đổi mật khẩu ban đầu để kích hoạt thẻ','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V223','SIT223','P1','suon_se','chinh_thuc','Đổi mật khẩu ban đầu để kích hoạt thẻ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_01','V223','Nhân viên',1,'银行卡已经办好了，需要现场激活修改初始密码哦。','yín háng kǎ yǐ jīng bàn hǎo le， xū yào xiàn chǎng jī huó xiū gǎi chū shǐ mì mǎ ó。','Thẻ ngân hàng đã làm xong rồi, anh cần kích hoạt và đổi mật khẩu ban đầu ngay tại đây nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_02','V223','Nguyễn Minh',2,'好的，请问我怎么操作呢？我不太会用机器。','hǎo de， qǐng wèn wǒ zěn me cāo zuò ne？ wǒ bù tài huì yòng jī qì。','Vâng, cho tôi hỏi phải làm như thế nào ạ? Tôi không rành dùng máy lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_03','V223','Nhân viên',3,'没关系，我一步步教你，先输入初始密码，再设置新密码。','méi guān xì， wǒ yí bù bù jiāo nǐ， xiān shū rù chū shǐ mì mǎ， zài shè zhì xīn mì mǎ。','Không sao đâu, tôi sẽ hướng dẫn anh từng bước, trước tiên nhập mật khẩu ban đầu, sau đó đặt mật khẩu mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_04','V223','Nguyễn Minh',4,'好，我设置好了，这样就激活成功了吧？','hǎo， wǒ shè zhì hǎo le， zhè yàng jiù jī huó chéng gōng le ba？','Vâng, tôi đặt xong rồi, vậy là kích hoạt thành công rồi phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_05','V223','Nhân viên',5,'对的，现在可以正常存取款、扫码支付了。','duì de， xiàn zài kě yǐ zhèng cháng cún qǔ kuǎn、 sǎo mǎ zhī fù le。','Đúng vậy, giờ anh có thể gửi rút tiền và quét mã thanh toán bình thường rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn chị rất nhiều đã giúp đỡ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương ơi, mình muốn đăng ký WeChat Pay, còn phải xác thực danh tính thật nữa đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi đó, không xác thực thì không quét mã trả tiền hay chuyển khoản được đâu.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy du học sinh dùng hộ chiếu cũng xác thực được à? Mình không có CMND/CCCD.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, rồi làm theo hướng dẫn tải ảnh lên là xong thôi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi, mình thử luôn đây!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Không hiểu chỗ nào cứ gọi mình, mình chỉ cho.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ, anh quét mã thanh toán là được nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Vâng, tôi mở mã QR WeChat, chị quét cho tôi nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được ạ, hoặc anh quét mã ở quầy thu ngân cũng được.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Tôi quét xong rồi, thanh toán thành công rồi, chị xem giúp tôi nhé!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi, không vấn đề gì! Anh cầm đồ cẩn thận, đi cẩn thận nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào thầy/cô, em là sinh viên mới Nguyễn Minh, hôm nay em đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp hộ chiếu, visa và giấy báo nhập học giúp cô nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Vâng ạ, đây là toàn bộ giấy tờ của em, mời cô kiểm tra giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ và hợp lệ, cô sẽ giúp em hoàn tất đăng ký sinh viên mới nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Cho em hỏi tiếp theo còn thủ tục báo danh nào khác không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Cơ bản là xong rồi, thông báo chọn môn và khám sức khỏe sau này sẽ đăng chung trong nhóm nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Vâng ạ, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','Cán bộ',1,'还差一份疫苗接种证明，你带过来了吗？','hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Còn thiếu một tờ giấy chứng nhận tiêm vắc-xin, em mang theo chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','Nguyễn Minh',2,'不好意思老师，我今天忘记带这份材料了，非常抱歉。','bù hǎo yì sī lǎo shī， wǒ jīn tiān wàng jì dài zhè fèn cái liào le， fēi cháng bào qiàn。','Em xin lỗi thầy/cô, hôm nay em quên mang giấy này ạ, em thật sự xin lỗi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','Cán bộ',3,'没事的，不用紧张。','méi shì de， bù yòng jǐn zhāng。','Không sao đâu, em đừng lo lắng quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','Nguyễn Minh',4,'那请问我明天补交可以吗？不会影响报到吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ bú huì yǐng xiǎng bào dào ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Có ảnh hưởng đến việc báo danh không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','Cán bộ',5,'不影响的，明天下午之前交过来就行啦。','bù yǐng xiǎng de， míng tiān xià wǔ zhī qián jiāo guò lái jiù xíng la。','Không ảnh hưởng đâu, trước chiều mai nộp lên là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','Nguyễn Minh',6,'太感谢您通融了，我明天一定准时送来！','tài gǎn xiè nín tōng róng le， wǒ míng tiān yí dìng zhǔn shí sòng lái！','Em cảm ơn thầy/cô đã thông cảm, ngày mai em nhất định sẽ mang đến đúng giờ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào thầy/cô, môn tiếng Trung em muốn chọn hiện đã báo đầy chỗ rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp hot này đã hết chỗ rồi đó em.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể đổi sang lớp ở khung giờ khác được không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học giống hệt nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em cứ đổi sang lớp này luôn được không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác trực tiếp trên hệ thống là được, không cần xin phép thêm gì cả.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, em rất vui được làm học sinh của cô.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường mình, em thích nghi với cuộc sống ở đây chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang dần thích nghi ạ, em muốn hỏi cô một chút, việc chọn môn của chuyên ngành em nên chú trọng điều gì ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì em có thể chọn các môn liên quan đến thương mại quốc tế nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Vâng ạ, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải là được, không cần chọn quá nhiều môn, để tránh áp lực quá lớn nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã chỉ dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Em ơi, qua đây chụp ảnh làm thẻ sinh viên nào.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Vâng ạ, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em không rõ lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, em chỉnh lại một chút, thế này được chưa ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Cười tươi lên, nhìn vào ống kính, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ được nhập vào hệ thống, một tuần sau là em có thể lấy thẻ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào cô/thầy ạ, em là sinh viên mới, em muốn làm thẻ thư viện để mượn sách ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được rồi, em xuất trình thẻ sinh viên là làm miễn phí nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Đây ạ, làm xong rồi thì mỗi lần em được mượn mấy cuốn vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Sinh viên quốc tế mỗi lần được mượn mười cuốn, thời hạn mượn là ba mươi ngày đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Trung này được không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô quét mã đăng ký cho em, mượn thành công rồi nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em không đăng nhập được email trường, mật khẩu ban đầu bị sai rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy à? Chắc mày gõ nhầm chữ hoa chữ thường rồi đúng không?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Có thể lắm! Em cứ không để ý phân biệt hoa thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, để anh chỉ cho, gõ lại phân biệt hoa thường là đăng nhập được ngay.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Vào được rồi! Giờ đổi mật khẩu như thế nào vậy anh?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào mục cá nhân để đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Được rồi, em đổi ngay đây, cảm ơn anh nhiều nha!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào thầy/cô trợ giảng ạ, em nộp bài trên nền tảng học tập nhưng cứ nộp không được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là do file không tải lên được, hay là trang bị lag vậy em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ load mãi, em bấm nộp mà không có phản hồi gì cả ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống nền tảng bị lag vào buổi tối, hôm nay nhiều bạn cũng gặp tình trạng này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị trừ điểm vì trễ hạn không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, do lỗi hệ thống nên sẽ gia hạn nộp bài chung, mai sáng nộp lại là được.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','May quá, cảm ơn thầy/cô đã báo cho em biết!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào cô ạ, em muốn hỏi về phạm vi chi trả của bảo hiểm y tế dành cho sinh viên quốc tế ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Được, bảo hiểm y tế của trường chủ yếu chi trả chi phí khám ngoại trú và nội trú tại bệnh viện công nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh thông thường như cảm cúm, viêm dạ dày ruột cũng được chi trả đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi chi trả, tai nạn thương tích cũng được bồi thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Cho em hỏi có những khoản nào không được chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn cô đã giải thích chi tiết!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào anh/chị ạ, em là sinh viên mới đến khám sức khỏe nhập học, cho em hỏi làm thủ tục như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Trước tiên em lấy số khám ở máy tự phục vụ, rồi điền vào tờ thông tin cá nhân này nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Dạ, phần quốc tịch và loại giấy tờ trong biểu mẫu em điền đúng sự thật là được ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng vậy, em điền chính xác hết thông tin để tránh phiếu khám bị sai sót.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền biểu mẫu xong rồi, số cũng lấy rồi, tiếp theo làm gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Em cầm phiếu đi khám lần lượt các mục là được, quy trình đơn giản lắm.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi ạ, cảm ơn anh/chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','Tài xế',1,'这条路早高峰有点堵车，车速比较慢哦。','zhè tiáo lù zǎo gāo fēng yǒu diǎn dǔ chē， chē sù bǐ jiào màn ó。','Con đường này giờ cao điểm sáng hơi kẹt xe, chạy chậm lắm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','Nguyễn Minh',2,'我马上要上课了，快要迟到了呢！能不能换一条近路呀？','wǒ mǎ shàng yào shàng kè le， kuài yào chí dào le ne！ néng bù néng huàn yī tiáo jìn lù ya？','Em sắp vào học rồi, sắp trễ đến nơi rồi! Anh đổi đường gần hơn được không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','Tài xế',3,'我看看，主干道全堵了，小路可以绕一下，就是稍微远一点。','wǒ kàn kàn， zhǔ gàn dào quán dǔ le， xiǎo lù kě yǐ rào yī xià， jiù shì shāo wēi yuǎn yì diǎn。','Để anh xem, đường chính kẹt hết rồi, đi đường nhỏ vòng qua cũng được, chỉ là hơi xa một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','Nguyễn Minh',4,'没关系的，不迟到就行，麻烦您绕路啦！','méi guān xì de， bù chí dào jiù xíng， má fán nín rào lù la！','Không sao đâu, miễn không trễ là được, phiền anh đi đường vòng giúp em nhé!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','Tài xế',5,'没问题，我马上变道绕路，几分钟就能到学校。','méi wèn tí， wǒ mǎ shàng biàn dào rào lù， jǐ fēn zhōng jiù néng dào xué xiào。','Không vấn đề gì, anh chuyển làn đi vòng ngay đây, mấy phút là tới trường thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','Nguyễn Minh',6,'太好了，辛苦您了！','tài hǎo le， xīn kǔ nín le！','Tuyệt quá, cảm ơn anh vất vả rồi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng ba mươi tám tệ, phiền anh/chị thanh toán nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Dạ, em trả tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi anh/chị nha, cửa hàng hiện không nhận tiền mặt, chỉ nhận thanh toán quét mã qua WeChat hoặc Alipay thôi.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Vậy à, để em mở điện thoại quét mã ngay đây.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, anh/chị cứ từ từ thao tác, thanh toán xong em xuất hoá đơn ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Trả xong rồi, cảm ơn chị đã nhắc nhở!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào không có phản ứng gì.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt hả cháu? Để cô qua xem thử nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Dạ đúng rồi, cháu thử hai lần rồi mà không được, đồ bỏ vào không giặt được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này bị hỏng tạm thời rồi, cháu qua dùng cái máy bên cạnh là được.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Dạ được ạ, vậy máy hỏng bao giờ sửa xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai thợ đến kiểm tra sửa chữa, tối nay cứ dùng máy khác trước đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi, cháu cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào anh/chị, xin lỗi đã làm phiền ạ! Hình như em đi nhầm chuyến tàu điện ngầm rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo lắng, em muốn đi đâu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đến khu Đại học thành, vừa nãy lên tàu ngồi ngược chiều rồi, giờ không biết đổi tuyến thế nào ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ở trạm tiếp theo, sang sân ga đối diện đi tuyến số 2 là đến thẳng nơi cần đến luôn.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Dạ, vậy em không cần mua vé lại đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi tuyến trong ga đều miễn phí, em cứ yên tâm đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Em cảm ơn anh/chị nhiều lắm, thật sự giúp em rất nhiều!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì đâu, lần sau xem kỹ chiều tàu rồi hẵng lên nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào anh, anh là Nguyễn Minh đúng không? Hàng thu hộ (COD) của anh tới rồi, là chăn ga gối và đồ dùng nhà bếp đúng không?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền bạn kiểm tra lại thông tin giúp mình nhé! Số điện thoại đuôi 3621 đúng không?','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng rồi đó! Địa chỉ cũng là ký túc xá sinh viên quốc tế của trường. Tổng cước phí là 28 tệ nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Mình thấy trên app dự tính là 22 tệ mà, sao lại dư ra 6 tệ vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của anh bị quá cân rồi, phần vượt cân phải trả thêm cước, app dự tính không chính xác đâu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, thế thì không sao, để mình quét mã trả tiền nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được đó! Trả xong mình ký nhận giúp anh, đồ vẫn còn nguyên vẹn, anh có thể kiểm tra thử.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu, cảm ơn bạn đã vất vả chạy một chuyến!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Chào em, hôm nay muốn ăn gì nào? Cơm hay là mì?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Cô ơi, cho con một suất cơm trứng xào cà chua ạ, cảm ơn cô!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi! Có muốn thêm món ăn kèm không? Rau xanh với khoai tây đều mới cả đấy.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Dạ thôi cô ơi! Phiền cô đừng cho cay nhé, con không ăn cay được đâu.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, để cô làm cho vị thanh đạm.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, con cảm ơn cô nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi mà! Xong ngay đây, em đợi một chút nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Anh Vũ ơi, mấy hôm nay em thấy hơi khó chịu, muốn nói với anh chuyện này.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Anh thấy sắc mặt em không được tốt lắm, khó chịu trong người à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là do chưa quen thủy thổ, tối cứ ngủ không ngon, ban ngày học lại buồn ngủ kinh khủng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay em ít nói hẳn! Vậy em định tính sao?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em định chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Đương nhiên là được! Em cứ nghỉ ngơi cho khỏe, tối anh sẽ nhẹ nhàng hơn, không làm phiền em đâu.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự làm phiền anh rồi!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì, bạn cùng phòng vốn dĩ phải quan tâm nhau mà.','AM09');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Cô Vương ơi, làm phiền cô rồi! Con muốn hỏi thăm quy định khách đến thăm trong trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có phải bạn em muốn đến ký túc tìm em không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng ạ, bạn con mai muốn đến ký túc tìm con, cần đăng ký như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang theo chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy buổi tối có đến thăm được không ạ? Con định hẹn gặp buổi tối cơ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Buổi tối không được đâu, ký túc khóa cửa lúc mười giờ, buổi tối cấm người ngoài vào trường.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Ra là vậy, vậy con đổi sang ban ngày ạ, cảm ơn cô đã cho con biết!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được, nhớ bảo bạn em mang theo giấy tờ nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','Nguyễn Minh',1,'刘哥您好，不好意思打扰您了！','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín le！','Chào anh Lưu, xin lỗi vì đã làm phiền anh!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','Chủ nhà',2,'你好同学，是今天要过来入住的对吧？','nǐ hǎo tóng xué， shì jīn tiān yào guò lái rù zhù de duì ba？','Chào em, hôm nay em đến nhận phòng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','Nguyễn Minh',3,'非常抱歉！我这边行程耽误了，今天赶不过来了呢。','fēi cháng bào qiàn！ wǒ zhè biān xíng chéng dān wù le， jīn tiān gǎn bù guò lái le ne。','Em thật sự xin lỗi! Lịch trình của em bị trục trặc, hôm nay không kịp đến được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','Chủ nhà',4,'这样啊？那你大概要推迟到什么时候呀？','zhè yàng a？ nà nǐ dà gài yào tuī chí dào shén me shí hòu ya？','Vậy à? Vậy em định dời đến khoảng thời gian nào?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','Nguyễn Minh',5,'我明天下午才能到，能不能麻烦您帮我改一下入住时间？','wǒ míng tiān xià wǔ cái néng dào， néng bù néng má fán nín bāng wǒ gǎi yī xià rù zhù shí jiān？','Ngày mai chiều em mới đến được, phiền anh giúp em đổi lại giờ nhận phòng được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','Chủ nhà',6,'没事没事，小事而已！今天我就先不预留房间了，明天你提前跟我说一声。','méi shì méi shì， xiǎo shì ér yǐ！ jīn tiān wǒ jiù xiān bù yù liú fáng jiān le， míng tiān nǐ tí qián gēn wǒ shuō yī shēng。','Không sao không sao, chuyện nhỏ thôi! Hôm nay anh sẽ không giữ phòng trước nữa, mai em nhớ báo trước cho anh một tiếng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','Nguyễn Minh',7,'太感谢您的理解了，真的不好意思！','tài gǎn xiè nín de lǐ jiě le， zhēn de bù hǎo yì sī！','Em cảm ơn anh đã thông cảm nhiều lắm, thật sự xin lỗi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','Chủ nhà',8,'不用客气，出门在外难免有变动嘛，明天见！','bù yòng kè qì， chū mén zài wài nán miǎn yǒu biàn dòng ma， míng tiān jiàn！','Không cần khách sáo đâu, đi xa khó tránh khỏi có thay đổi mà, hẹn gặp em ngày mai!','AM09');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này bao nhiêu tiền một thùng ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 một thùng, mấy hôm nay bên chị đang có chương trình khuyến mãi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy là ưu đãi gì thế chị, có lời không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng thì giảm thẳng 20 tệ, lời lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế em mua hai thùng luôn, ngày thường em uống nhiều mà.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được, để chị quét mã cho em, thanh toán tự động trừ luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ được, cảm ơn chị nha!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, cho con hỏi rau củ quả là cân ở đây phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi đó, con để đồ lên rồi chọn đúng tên rau là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem gì hết vậy cô?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem, con chọn là bắp cải nhưng con cầm là rau cải xanh, chọn sai loại rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Ra là vậy, thảo nào cứ không được, để con làm lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, cứ từ từ, dán tem xong là ra máy tự thanh toán được rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Con cảm ơn cô nhiều lắm, không thì con phải loay hoay lâu lắm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我昨天在这边买的面包，今天打开发现发霉了。','nǐ hǎo， wǒ zuó tiān zài zhè biān mǎi de miàn bāo， jīn tiān dǎ kāi fā xiàn fā méi le。','Chào chị, hôm qua em có mua ổ bánh mì ở đây, hôm nay mở ra thì thấy bị mốc rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦出示一下购物小票可以吗？','nín hǎo， má fán chū shì yī xià gòu wù xiǎo piào kě yǐ ma？','Chào em, phiền em cho xem hóa đơn mua hàng được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'有的，我一直常温存放，根本没放多久呀。','yǒu de， wǒ yì zhí cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Dạ có ạ, em luôn để ở nhiệt độ phòng, cũng đâu để lâu gì đâu.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'我核对一下，确实是商品质量问题，非常抱歉哈。','wǒ hé duì yī xià， què shí shì shāng pǐn zhì liàng wèn tí， fēi cháng bào qiàn hā。','Để em kiểm tra lại, đúng là lỗi chất lượng sản phẩm rồi, thành thật xin lỗi anh/chị nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'没关系，那我可以直接换新或者退款吗？','méi guān xì， nà wǒ kě yǐ zhí jiē huàn xīn huò zhě tuì kuǎn ma？','Không sao đâu, vậy em có thể đổi mới hoặc hoàn tiền luôn được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'都可以，我这边直接给你全额退款处理。','dōu kě yǐ， wǒ zhè biān zhí jiē gěi nǐ quán é tuì kuǎn chǔ lǐ。','Đều được cả ạ, bên em hoàn tiền toàn bộ cho anh/chị luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Được, phiền bạn nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Chú ơi, con là sinh viên mới, muốn mua bộ chăn ga gối ký túc với cả nồi nấu nhỏ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có nè, mấy món này đều dành riêng cho sinh viên, độ dày và công suất đều hợp với ký túc hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không chú? Con sợ lạnh lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ ấm qua đông luôn, chỉ có nồi nấu nhỏ ký túc hôm nay vừa mới bán hết hàng thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy chừng nào có hàng lại vậy chú? Con cần gấp lắm.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai là có hàng, mai con qua lấy là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Dạ, vậy hôm nay con mua trước chăn, gối với ly nước ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào tốt vậy chị? Em lần đầu giặt đồ ở ký túc.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại đóng chai này là được, mùi nhẹ nhàng, tẩy sạch cũng tốt lắm đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Dạ được, vậy máy giặt tự động ở tầng dưới có khó dùng không chị?','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó chút nào, quét mã thanh toán rồi bỏ quần áo với nước giặt vào là xong.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Vậy em có cần tự chỉnh thời gian với chế độ không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần đâu, mặc định chế độ chuẩn, giặt sạch lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Em hiểu rồi, cảm ơn chị nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚用洗衣机洗衣服，洗到一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng yòng xǐ yī jī xǐ yī fú， xǐ dào yí bàn tū rán tíng jī le。','Cô ơi, con vừa dùng máy giặt để giặt đồ, giặt được nửa chừng thì tự nhiên dừng máy luôn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'是余额不够自动停掉了吗？','shì yú é bù gòu zì dòng tíng diào le ma？','Có phải hết số dư nên nó tự động dừng không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'对的，我以为余额充足，没想到中途欠费了。','duì de， wǒ yǐ wéi yú é chōng zú， méi xiǎng dào zhōng tú qiàn fèi le。','Dạ đúng ạ, con cứ tưởng còn đủ tiền, ai ngờ giữa chừng bị thiếu tiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'这种情况很常见，可以申请部分退款的。','zhè zhǒng qíng kuàng hěn cháng jiàn， kě yǐ shēn qǐng bù fèn tuì kuǎn de。','Trường hợp này thường gặp lắm, con có thể xin hoàn lại một phần tiền được đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'那我需要准备什么材料吗？','nà wǒ xū yào zhǔn bèi shén me cái liào ma？','Vậy con cần chuẩn bị giấy tờ gì không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'不用，把付款截图发给我，我帮你登记上报就行。','bù yòng， bǎ fù kuǎn jié tú fā gěi wǒ， wǒ bāng nǐ dēng jì shàng bào jiù xíng。','Không cần đâu, con gửi ảnh chụp màn hình thanh toán cho cô, cô sẽ giúp con đăng ký báo lên trên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ được, cảm ơn cô đã vất vả giúp con nhé!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, cho em một cái bánh kếp ngũ cốc, gói mang đi nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được rồi, em có muốn thêm xúc xích nướng, rau sống mấy thứ đó không?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Cho một cây xúc xích nướng thôi, ít ớt lại giúp em nha, em không ăn cay được lắm.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không thành vấn đề, vị cay nhẹ nha, hai phút là xong ngay.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Phiền chị gói kín lại giúp em một chút, em mang về ký túc xá ăn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói kín mít cho em luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nhiều nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn xong, có một mục kiêng cữ quan trọng cần ghi chú lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào anh/chị, xin anh/chị nói rõ yêu cầu cụ thể, chúng tôi sẽ chuyển ngay xuống bếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng nặng với đậu phộng, món ăn tuyệt đối không được cho bất kỳ chế phẩm nào từ đậu phộng vào nhé.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Vâng, chúng tôi đã ghi chú đặc biệt về việc kiêng đậu phộng cho anh/chị rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây có quán bỏ qua ghi chú, suýt nữa thì xảy ra chuyện đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng tôi thành thật xin lỗi vì đã khiến anh/chị lo lắng, chúng tôi sẽ dặn dò riêng cho bếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy thì phiền các bạn để ý kỹ giúp mình nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, em muốn hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Loại sữa chua để ở nhiệt độ thường này hạn sử dụng ba tháng, không cần bỏ tủ lạnh đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở nắp thì để được bao lâu ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, để ở nhiệt độ thường là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, chỉ cần tránh ánh nắng trực tiếp là được, tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em hiểu rồi, cảm ơn chị nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn một chút nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, bạn có chuyện gì cứ nói thẳng ra nhé.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Tối nay mình cần ôn bài chuẩn bị thi, phòng các bạn hơi ồn một chút.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn, tụi mình không để ý âm lượng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau mười giờ tối có thể yên tĩnh một chút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, tụi mình nhỏ tiếng lại ngay, sau này chắc chắn sẽ chú ý!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều lắm nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thưa thầy/cô, em xin lỗi vì đã đến lớp muộn, em thật sự rất xin lỗi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại đến muộn vậy? Nguyên nhân là gì?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Sáng nay em ra khỏi nhà muộn, lại gặp kẹt xe nên bị trễ giờ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải canh giờ cho tốt, đừng để đi trễ nữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Em ghi nhớ rồi ạ, sau này em chắc chắn sẽ ra khỏi nhà sớm hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, mau vào chỗ ngồi nghe giảng đi, đừng để ảnh hưởng việc học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Em cảm ơn thầy/cô đã thông cảm ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Thưa thầy/cô chủ nhiệm, em muốn xin nghỉ phép chiều nay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được, em nói ngắn gọn lý do xin nghỉ xem sao.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể dời lại được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Được rồi, tôi sẽ ghi nhận điểm danh cho em, đồng ý cho em nghỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn thầy/cô, phần bài học bị lỡ em sẽ bù lại kịp thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhất định phải theo kịp tiến độ, đừng để thiếu sót nội dung học.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi ạ, thầy/cô vất vả rồi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，我想跟您申请作业延期提交。','lǎo shī nín hǎo， wǒ xiǎng gēn nín shēn qǐng zuò yè yán qī tí jiāo。','Thưa thầy/cô, em muốn xin gia hạn nộp bài tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'说说原因，无故延期是不允许的哦。','shuō shuō yuán yīn， wú gù yán qī shì bù yǔn xǔ de ó。','Nói lý do xem, không có lý do chính đáng thì không được gia hạn đâu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'我昨天身体不舒服，休息了一天，作业没能按时完成。','wǒ zuó tiān shēn tǐ bù shū fú， xiū xī le yī tiān， zuò yè méi néng àn shí wán chéng。','Hôm qua em không được khỏe, phải nghỉ ngơi cả ngày nên bài chưa làm xong đúng hạn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'情况可以理解，但是最多只能延期一天。','qíng kuàng kě yǐ lǐ jiě， dàn shì zuì duō zhǐ néng yán qī yī tiān。','Tình huống này có thể thông cảm được, nhưng tối đa chỉ được gia hạn một ngày thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'一天完全够了，我今晚一定认真做完。','yī tiān wán quán gòu le， wǒ jīn wǎn yí dìng rèn zhēn zuò wán。','Một ngày là đủ rồi ạ, tối nay em nhất định sẽ làm xong nghiêm túc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'这次特殊通融，下次必须按时交作业。','zhè cì tè shū tōng róng， xià cì bì xū àn shí jiāo zuò yè。','Lần này châm chước đặc biệt, lần sau nhất định phải nộp bài đúng hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Bài tập nhóm mình còn chưa phân công, hôm nay chốt gấp đi nhỉ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được, mình phân công theo sở trường của mỗi người, làm vậy hiệu quả hơn.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Mình giỏi tìm tài liệu với viết nội dung, phần làm PPT bạn lo được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không vấn đề gì, mình khá giỏi làm PPT, phần này cứ để mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy phần thuyết trình cuối cùng trên lớp, hai đứa mình cùng phối hợp nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được, làm xong tụi mình kiểm tra chéo cho nhau, tránh sai sót.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy mỗi người bắt tay vào làm phần mình thôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa thầy/cô và các bạn, em thật sự xin lỗi vì bài thuyết trình lần này của em chuẩn bị chưa kỹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao, cứ trình bày bình thường đi, nói xem vấn đề nằm ở đâu?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Em chuẩn bị tài liệu trước đó chưa kỹ càng, nội dung còn thiếu sót nhiều chi tiết ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em đã không chuẩn bị và trau chuốt nội dung đầy đủ từ trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn nhận vấn đề như vậy là tốt rồi, lần sau chuẩn bị đầy đủ trước là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, em cảm ơn thầy/cô và các bạn đã thông cảm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Thưa thầy/cô, phần kiến thức vừa giảng em nghe chưa hiểu lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em chưa hiểu? Để tôi giảng lại cho em một lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là logic áp dụng công thức đó ạ, em vẫn còn hơi mơ hồ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, tôi tóm tắt lại đơn giản một lượt, em chú ý nghe nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Dạ vâng, phiền thầy/cô mất công giảng lại cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, đừng ngại ngùng gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hết rồi ạ, em cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Chào cô ạ, em muốn hỏi về quy định phòng thi cho kỳ thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Nếu có chỗ nào chưa rõ thì em cứ hỏi trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Cho em hỏi trong lúc thi có được mang giấy nháp và dụng cụ học tập riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát đồng loạt tất cả vật dụng cần thiết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử thì có cần tháo ra để cất riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải được thu gom lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Em đã nắm rõ hết các quy định rồi, em cảm ơn cô ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Chào thầy/cô ạ, em muốn xác nhận lại điểm cuối kỳ môn học của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể là vấn đề gì vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Bài tập, điểm danh, thi cử em đều hoàn thành đầy đủ, nhưng hệ thống lại hiển thị chưa có điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là do hệ thống giáo vụ nhập liệu bị trục trặc nên dữ liệu mới bị lỗi vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo là do mình nộp thiếu bài tập, trong lòng bất an lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em yên tâm, để thầy/cô kiểm tra lại hồ sơ thủ công rồi nhập điểm lại cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn thầy/cô đã giúp đỡ xử lý ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，我正式申请本次期末试卷成绩复核。','lǎo shī nín hǎo， wǒ zhèng shì shēn qǐng běn cì qī mò shì juàn chéng jì fù hé。','Chào thầy/cô ạ, em xin chính thức nộp đơn xin phúc khảo điểm bài thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'可以的，请说明你的申请原因。','kě yǐ de， qǐng shuō míng nǐ de shēn qǐng yuán yīn。','Được, em trình bày lý do xin phúc khảo đi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'我的自我估分和最终成绩差距较大，想核对卷面分数。','wǒ de zì wǒ gū fēn hé zuì zhōng chéng jì chā jù jiào dà， xiǎng hé duì juàn miàn fēn shù。','Điểm em tự chấm và điểm cuối cùng chênh lệch khá nhiều, em muốn kiểm tra lại điểm trên bài thi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'我理解了，我帮你提交官方复核申请。','wǒ lǐ jiě le， wǒ bāng nǐ tí jiāo guān fāng fù hé shēn qǐng。','Thầy/cô hiểu rồi, để thầy/cô giúp em nộp đơn phúc khảo chính thức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'请问多久可以出复核结果呢？','qǐng wèn duō jiǔ kě yǐ chū fù hé jié guǒ ne？','Cho em hỏi bao lâu thì có kết quả phúc khảo ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'三个工作日内会公示最终成绩。','sān gè gōng zuò rì nèi huì gōng shì zuì zhōng chéng jì。','Trong vòng ba ngày làm việc sẽ công bố điểm chính thức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'辛苦老师了，谢谢！','xīn kǔ lǎo shī le， xiè xiè！','Cảm ơn thầy/cô đã vất vả vì em ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ ơi, hôm qua tớ xin nghỉ nên bị lỡ buổi học, cậu cho tớ mượn vở ghi chép trên lớp được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Đương nhiên là được, tớ ghi khá chi tiết đấy, chỗ nào quan trọng khó hiểu tớ đều đánh dấu hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Hay quá, đúng lúc tớ bỏ lỡ đúng phần kiến thức quan trọng nhất luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ từ từ xem, xem xong trả lại tớ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều nha, chỗ nào không hiểu tớ hỏi lại cậu nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không vấn đề gì, bạn học với nhau vốn dĩ nên giúp đỡ nhau mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng quá đi mất!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào bạn, tôi muốn đặt lịch khám nội khoa hôm nay qua ứng dụng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Chào anh/chị, anh/chị cần đặt số khám thường hay số khám chuyên gia ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Số khám thường là được rồi, tôi chỉ bị hơi chóng mặt và mệt mỏi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Rất xin lỗi, hôm nay số khám thường nội khoa đã kín hết rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn suất trống không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn nhiều suất lắm, để tôi hướng dẫn anh/chị đặt lịch nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Được, phiền bạn chỉ tôi cách thao tác với!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào bạn, gần đây tôi hay bị chóng mặt, ngủ không ngon, vậy nên đăng ký khám khoa nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Với triệu chứng của anh/chị thì khám khoa thần kinh nội là hợp lý nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy bạn đăng ký giúp tôi khám thường vào chiều nay nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được ạ, anh/chị thanh toán bằng bảo hiểm y tế hay tự chi trả ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Tôi dùng bảo hiểm y tế sinh viên để thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Đã đăng ký thành công cho anh/chị rồi, mời anh/chị lên phòng khám tầng hai chờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Được, cảm ơn bạn nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Chào bác sĩ, mấy ngày nay em cứ bị chóng mặt, người mệt mỏi rã rời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Em bị chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng thôi ạ, nhất là vào buổi tối, với lại em hay mất ngủ, ngủ không được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Em có bị sốt, buồn nôn hay khó chịu chỗ nào khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Dạ không có, em chỉ bị hai triệu chứng chóng mặt với mệt mỏi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Bác sĩ hiểu sơ bộ rồi, để bác sĩ khám qua cho em một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Vâng ạ, phiền bác sĩ giúp em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Bác sĩ ơi, em cần báo trước cho bác sĩ biết tiền sử dị ứng thuốc của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Được, cụ thể em bị dị ứng với loại thuốc nào?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Em bị dị ứng với các loại thuốc nhóm penicillin, tuyệt đối không được dùng nhóm thuốc này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Bác sĩ ghi nhận rồi, khi kê đơn sẽ tránh hoàn toàn loại thuốc gây dị ứng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây em từng bị phản ứng dị ứng rất nặng nên em đặc biệt cẩn thận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Bác sĩ hiểu, an toàn dùng thuốc là ưu tiên hàng đầu, em cứ yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Em cảm ơn bác sĩ đã tận tâm và cẩn thận ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào chị, đây là đơn thuốc của em, phiền chị lấy thuốc giúp em với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Được, em chờ chút, chị kiểm tra lại thông tin thuốc đã.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Dạ được ạ, mấy loại thuốc này thì uống như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều là ngày ba lần, uống sau bữa ăn với nước ấm, trên hướng dẫn sử dụng cũng có ghi rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Có cần bảo quản lạnh không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần đâu, cứ để nơi nhiệt độ thường, tránh ánh sáng là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Em hiểu rồi, em cảm ơn chị nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào chị, em muốn hỏi mấy loại thuốc em được kê đơn này có được bảo hiểm y tế chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để chị tra giúp em danh mục thuốc bảo hiểm y tế nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi, trong đó có hai loại thuốc cơ bản được thanh toán, còn một loại thuốc nhập khẩu thì không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, vậy thuốc nhập khẩu là phải tự chi trả toàn bộ đúng không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng vậy, thuốc đặc trị nhập khẩu không nằm trong phạm vi chi trả của bảo hiểm y tế.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_06','V326','阮明',6,'我了解了，那麻烦你分开结算吧。','wǒ liǎo jiě le， nà má fán nǐ fēn kāi jié suàn ba。','Em hiểu rồi, vậy phiền chị tính tiền tách riêng ra giúp em nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_07','V326','工作人员',7,'没问题，我帮你区分清楚。','méi wèn tí， wǒ bāng nǐ qū fēn qīng chǔ。','Không vấn đề gì, chị sẽ phân chia rõ ràng giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT327','S109','Đặt lịch tái khám',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V327','SIT327','P1','suon_se','ban_chinh_thuc',NULL,'慢性病、短期病症恢复都需要复诊，携带既往病历是医院常规要求。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_01','V327','阮明',1,'你好，我想预约下周的复诊门诊。','nǐ hǎo， wǒ xiǎng yù yuē xià zhōu de fù zhěn mén zhěn。','Chào bạn, tôi muốn đặt lịch tái khám vào tuần sau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_02','V327','工作人员',2,'可以的，你想预约周几的时间段？','kě yǐ de， nǐ xiǎng yù yuē zhōu jǐ de shí jiān duàn？','Được ạ, anh/chị muốn đặt vào khung giờ ngày nào trong tuần?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_03','V327','阮明',3,'下周二下午吧，我下午没有课程安排。','xià zhōu èr xià wǔ ba， wǒ xià wǔ méi yǒu kè chéng ān pái。','Chiều thứ Ba tuần sau nhé, chiều đó tôi không có lịch học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_04','V327','工作人员',4,'好的，已经为你预约成功。','hǎo de， yǐ jīng wèi nǐ yù yuē chéng gōng。','Vâng, tôi đã đặt lịch thành công cho anh/chị rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_05','V327','阮明',5,'复诊的时候需要带这次的病历本吗？','fù zhěn de shí hòu xū yào dài zhè cì de bìng lì běn ma？','Khi tái khám tôi có cần mang theo sổ bệnh án lần này không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_06','V327','工作人员',6,'需要的，务必携带方便医生对比恢复情况。','xū yào de， wù bì xié dài fāng biàn yī shēng duì bǐ huī fù qíng kuàng。','Có ạ, nhất định phải mang theo để bác sĩ tiện so sánh tình trạng hồi phục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_07','V327','阮明',7,'好的，我会妥善保管，谢谢你！','hǎo de， wǒ huì tuǒ shàn bǎo guǎn， xiè xiè nǐ！','Vâng, tôi sẽ giữ gìn cẩn thận, cảm ơn bạn nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT328','S109','Xin giấy chứng nhận nghỉ bệnh cho trường',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V328','SIT328','P1','suon_se','chinh_thuc',NULL,'国内高校只认可医院机打正规病假证明，手写证明无效，是统一考勤制度。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_01','V328','阮明',1,'医生您好，我身体不适需要请假，麻烦您开具一张病假证明。','yī shēng nín hǎo， wǒ shēn tǐ bù shì xū yào qǐng jià， má fán nín kāi jù yī zhāng bìng jià zhèng míng。','Chào bác sĩ, tôi thấy trong người không khỏe nên cần xin nghỉ, phiền bác sĩ viết giúp tôi giấy chứng nhận nghỉ bệnh ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_02','V328','医生',2,'没问题，你需要请假休养几天？','méi wèn tí， nǐ xū yào qǐng jià xiū yǎng jǐ tiān？','Không vấn đề gì, em cần nghỉ dưỡng bao nhiêu ngày?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_03','V328','阮明',3,'我身体比较虚弱，想请假两天调整状态。','wǒ shēn tǐ bǐ jiào xū ruò， xiǎng qǐng jià liǎng tiān tiáo zhěng zhuàng tài。','Cơ thể tôi khá yếu, tôi muốn xin nghỉ hai ngày để điều chỉnh lại sức khỏe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_04','V328','医生',4,'可以，我给你开具正规机打病假证明。','kě yǐ， wǒ gěi nǐ kāi jù zhèng guī jī dǎ bìng jià zhèng míng。','Được, tôi sẽ viết cho em giấy chứng nhận nghỉ bệnh in chính thức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_05','V328','阮明',5,'证明上会标注就诊时间和请假时长对吧？','zhèng míng shàng huì biāo zhù jiù zhěn shí jiān hé qǐng jià shí cháng duì ba？','Trên giấy sẽ ghi rõ thời gian khám và thời gian nghỉ đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_06','V328','医生',6,'是的，信息齐全，学校可以直接认可。','shì de， xìn xī qí quán， xué xiào kě yǐ zhí jiē rèn kě。','Đúng vậy, thông tin đầy đủ, nhà trường có thể công nhận trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_07','V328','阮明',7,'太感谢医生了！','tài gǎn xiè yī shēng le！','Cảm ơn bác sĩ rất nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT329','S111','Tự giới thiệu trong buổi sinh hoạt đầu năm',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V329','SIT329','P1','suon_se','ban_chinh_thuc',NULL,'新生自我介绍简洁谦逊即可，"多多指教"是国内年轻人社交最常用的礼貌用语。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_01','V329','阮明',1,'大家好，我是阮明，一名来自越南的留学生，今年22岁。','dà jiā hǎo， wǒ shì ruǎn míng， yī míng lái zì yuè nán de liú xué shēng， jīn nián 22 suì。','Xin chào mọi người, tôi là Nguyễn Minh, một du học sinh đến từ Việt Nam, năm nay 22 tuổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_02','V329','阮明',2,'目前就读于汉语言文学专业，非常开心加入这个集体。','mù qián jiù dú yú hàn yǔ yán wén xué zhuān yè， fēi cháng kāi xīn jiā rù zhè ge jí tǐ。','Hiện tại tôi đang theo học chuyên ngành Ngôn ngữ và Văn học Trung Quốc, tôi rất vui khi được gia nhập tập thể này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_03','V329','阮明',3,'平时我喜欢读书和慢跑，性格比较随和开朗。','píng shí wǒ xǐ huān dú shū hé màn pǎo， xìng gé bǐ jiào suí hé kāi lǎng。','Bình thường tôi thích đọc sách và chạy bộ, tính cách khá dễ gần và cởi mở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_04','V329','阮明',4,'我刚来中国，对这边的学习和生活还在适应中。','wǒ gāng lái zhōng guó， duì zhè biān de xué xí hé shēng huó hái zài shì yìng zhōng。','Tôi mới sang Trung Quốc, vẫn đang trong quá trình thích nghi với việc học và cuộc sống ở đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_05','V329','阮明',5,'往后希望可以和各位同学友好相处，互相学习、多多指教。','wǎng hòu xī wàng kě yǐ hé gè wèi tóng xué yǒu hǎo xiāng chǔ， hù xiāng xué xí、 duō duō zhǐ jiào。','Sau này tôi mong có thể hòa đồng với các bạn, cùng nhau học hỏi, mong mọi người chỉ bảo thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_06','V329','辅导员',6,'欢迎阮明加入我们的大家庭！','huān yíng ruǎn míng jiā rù wǒ men de dà jiā tíng！','Chào mừng Nguyễn Minh gia nhập đại gia đình của chúng ta!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_07','V329','阮明',7,'谢谢大家！','xiè xiè dà jiā！','Cảm ơn mọi người!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT330','S111','Hỏi thông tin liên hệ để giữ kết nối',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V330','SIT330','P1','suon_se','tuy_y',NULL,'微信是国内学生唯一主流沟通工具，学习通知、日常交友、小组协作均依托微信完成。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_01','V330','阮明',1,'今天认识你真的太开心了！我们可以加个微信吗？','jīn tiān rèn shí nǐ zhēn de tài kāi xīn le！ wǒ men kě yǐ jiā gè wēi xìn ma？','Hôm nay quen được bạn thật sự rất vui! Chúng ta kết bạn Wechat được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_02','V330','林溪',2,'当然可以呀，以后我们就是同班同学了。','dāng rán kě yǐ ya， yǐ hòu wǒ men jiù shì tóng bān tóng xué le。','Đương nhiên được chứ, sau này chúng ta là bạn cùng lớp rồi mà.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_03','V330','阮明',3,'太好了，我刚来这边，以后还要多向你请教呢。','tài hǎo le， wǒ gāng lái zhè biān， yǐ hòu hái yào duō xiàng nǐ qǐng jiào ne。','Tuyệt quá, mình mới đến đây, sau này còn phải nhờ bạn chỉ bảo nhiều đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_04','V330','林溪',4,'不用客气，我们互相帮忙、共同进步。','bù yòng kè qì， wǒ men hù xiāng bāng máng、 gòng tóng jìn bù。','Không cần khách sáo đâu, chúng ta giúp đỡ nhau cùng tiến bộ mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_05','V330','阮明',5,'那我扫你的二维码加好友哈。','nà wǒ sǎo nǐ de èr wéi mǎ jiā hǎo yǒu hā。','Vậy để mình quét mã QR kết bạn với bạn nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_06','V330','林溪',6,'好嘞，以后常联系，有空一起学习！','hǎo lei， yǐ hòu cháng lián xì， yǒu kòng yì qǐ xué xí！','Được đó, sau này liên lạc thường xuyên nha, rảnh thì cùng học nhé!','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_07','V330','阮明',7,'太好啦，谢谢你！','tài hǎo la， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT331','S112','Mời bạn cùng lớp đi ăn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V331','SIT331','P1','suon_se','tuy_y',NULL,'中国大学生下课常结伴去食堂就餐，主动邀约同学吃饭是很常见的社交方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_01','V331','阮明',1,'下课啦，等下要不要一起去食堂吃饭啊？','xià kè la， děng xià yào bù yào yì qǐ qù shí táng chī fàn a？','Tan học rồi, lát nữa có muốn cùng đi ăn ở căng tin không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_02','V331','王浩',2,'可以呀，我正愁一个人吃饭没意思呢。','kě yǐ ya， wǒ zhèng chóu yí gè rén chī fàn méi yì si ne。','Được chứ, mình đang buồn vì phải ăn một mình chán lắm luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_03','V331','阮明',3,'食堂今天有米线，听说味道很不错的。','shí táng jīn tiān yǒu mǐ xiàn， tīng shuō wèi dào hěn bú cuò de。','Căng tin hôm nay có bán bún, nghe nói ngon lắm đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_04','V331','王浩',4,'刚好我也想吃米线，咱们现在就走吧。','gāng hǎo wǒ yě xiǎng chī mǐ xiàn， zán men xiàn zài jiù zǒu ba。','Đúng lúc mình cũng đang thèm ăn bún, đi luôn bây giờ nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_05','V331','阮明',5,'行，那我收拾一下书本，马上就好。','xíng， nà wǒ shōu shí yī xià shū běn， mǎ shàng jiù hǎo。','Được, để mình thu dọn sách vở một chút, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_06','V331','王浩',6,'没事，我在教室门口等你就行啦。','méi shì， wǒ zài jiào shì mén kǒu děng nǐ jiù xíng la。','Không sao, mình đợi bạn ở cửa lớp học là được rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_07','V331','阮明',7,'太感谢啦，有同学一起吃饭热闹多了。','tài gǎn xiè la， yǒu tóng xué yì qǐ chī fàn rè nào duō le。','Cảm ơn nhiều nha, có bạn cùng ăn thì vui hơn hẳn.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT332','S112','Từ chối lời mời một cách lịch sự',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V332','SIT332','P1','suon_se','tuy_y',NULL,'拒绝他人邀约时，中国人习惯说明合理理由并主动提出下次赴约，显得有礼貌不扫兴。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_01','V332','林晓',1,'晚上我们宿舍一起去校外吃火锅，你也来吧？','wǎn shàng wǒ men sù shè yì qǐ qù xiào wài chī huǒ guō， nǐ yě lái ba？','Tối nay ký túc xá tụi mình rủ nhau ra ngoài ăn lẩu, bạn đi cùng nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_02','V332','阮明',2,'真的很谢谢你邀请我，不过我今晚不行呢。','zhēn de hěn xiè xiè nǐ yāo qǐng wǒ， bù guò wǒ jīn wǎn bù xíng ne。','Thật sự rất cảm ơn bạn đã mời, nhưng tối nay mình không đi được rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_03','V332','林晓',3,'怎么啦，是有别的安排吗？','zěn me la， shì yǒu bié de ān pái ma？','Sao vậy, có việc gì khác à?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_04','V332','阮明',4,'我要完成一篇汉语作文，明天就得提交的。','wǒ yào wán chéng yī piān hàn yǔ zuò wén， míng tiān jiù dé tí jiāo de。','Mình phải hoàn thành một bài văn tiếng Trung, mai phải nộp rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_05','V332','林晓',5,'原来是这样，学习要紧，那下次再约吧。','yuán lái shì zhè yàng， xué xí yào jǐn， nà xià cì zài yuē ba。','Thì ra là vậy, học hành quan trọng hơn, vậy lần sau hẹn nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_06','V332','阮明',6,'好，下次我一定主动找你们，实在抱歉啦。','hǎo， xià cì wǒ yí dìng zhǔ dòng zhǎo nǐ men， shí zài bào qiàn la。','Ừ, lần sau mình nhất định sẽ chủ động rủ mọi người, thật ngại quá.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_07','V332','林晓',7,'没关系，学习完早点休息。','méi guān xì， xué xí wán zǎo diǎn xiū xī。','Không sao đâu, học xong thì nghỉ ngơi sớm nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT333','S112','Xin lỗi vì đến muộn buổi hẹn',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V333','SIT333','P1','twist','ban_chinh_thuc',NULL,'与人线下见面迟到，中国人会主动诚恳道歉，还会主动提出买单、请客作为补偿。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_01','V333','阮明',1,'实在对不起，我路上堵车，迟到二十分钟了。','shí zài duì bù qǐ， wǒ lù shàng dǔ chē， chí dào èr shí fēn zhōng le。','Thật sự xin lỗi, mình bị kẹt xe nên đến trễ hai mươi phút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_02','V333','陈悦',2,'没事，我也刚到一会儿，不用这么愧疚。','méi shì， wǒ yě gāng dào yī huì er， bù yòng zhè me kuì jiù。','Không sao đâu, mình cũng vừa đến một lúc thôi, không cần áy náy vậy đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_03','V333','阮明',3,'都怪我没提前出门，让你在这里干等啊。','dōu guài wǒ méi tí qián chū mén， ràng nǐ zài zhè lǐ gàn děng a。','Tại mình không ra khỏi nhà sớm hơn, để bạn phải ngồi đợi không vậy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_04','V333','陈悦',4,'还好，这家咖啡店座位挺多，我先点了两杯饮品。','hái hǎo， zhè jiā kā fēi diàn zuò wèi tǐng duō， wǒ xiān diǎn le liǎng bēi yǐn pǐn。','May mà quán cà phê này khá nhiều chỗ ngồi, mình gọi trước hai ly đồ uống rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_05','V333','阮明',5,'太不好意思了，这杯饮品我来付钱吧。','tài bù hǎo yì sī le， zhè bēi yǐn pǐn wǒ lái fù qián ba。','Ngại quá đi, ly đồ uống này để mình trả tiền nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_06','V333','陈悦',6,'不用啦，下次见面你请我就可以咯。','bù yòng la， xià cì jiàn miàn nǐ qǐng wǒ jiù kě yǐ gē。','Thôi khỏi, lần sau gặp lại bạn mời mình là được rồi.','AM11');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_07','V333','阮明',7,'好，下次我一定提前半小时出门，绝不迟到。','hǎo， xià cì wǒ yí dìng tí qián bàn xiǎo shí chū mén， jué bù chí dào。','Được, lần sau mình nhất định sẽ ra khỏi nhà sớm nửa tiếng, không trễ nữa đâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT334','S112','Cảm ơn khi được giúp đỡ đặc biệt',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V334','SIT334','P1','suon_se','ban_chinh_thuc',NULL,'得到他人较大帮助后，中国人常会赠送小零食、小礼物表达谢意，不会只口头道谢。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_01','V334','阮明',1,'班长，这次真的太谢谢你帮我补办签证材料了。','bān zhǎng， zhè cì zhēn de tài xiè xiè nǐ bāng wǒ bǔ bàn qiān zhèng cái liào le。','Lớp trưởng ơi, lần này thật sự cảm ơn bạn rất nhiều vì đã giúp mình làm lại giấy tờ visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_02','V334','周宇',2,'小事而已，留学生办理手续本来就麻烦嘛。','xiǎo shì ér yǐ， liú xué shēng bàn lǐ shǒu xù běn lái jiù má fán ma。','Chuyện nhỏ thôi mà, du học sinh làm thủ tục vốn dĩ đã rắc rối rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_03','V334','阮明',3,'要是没有你带路讲解，我肯定跑好多趟。','yào shì méi yǒu nǐ dài lù jiǎng jiě， wǒ kěn dìng pǎo hǎo duō tàng。','Nếu không có bạn dẫn đường và giải thích, chắc mình phải chạy đi chạy lại bao nhiêu lần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_04','V334','周宇',4,'不用放在心上，班里同学互相帮忙是应该的。','bù yòng fàng zài xīn shàng， bān lǐ tóng xué hù xiāng bāng máng shì yīng gāi de。','Đừng để trong lòng làm gì, các bạn trong lớp giúp đỡ nhau là chuyện nên làm mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_05','V334','阮明',5,'下周我买了家乡小零食，带给你尝尝吧。','xià zhōu wǒ mǎi le jiā xiāng xiǎo líng shí， dài gěi nǐ cháng cháng ba。','Tuần sau mình mua ít đồ ăn vặt quê nhà, mang cho bạn nếm thử nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_06','V334','周宇',6,'不用这么客气，能帮上忙我也很高兴。','bù yòng zhè me kè qì， néng bāng shàng máng wǒ yě hěn gāo xìng。','Không cần khách sáo vậy đâu, giúp được bạn mình cũng vui lắm rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_07','V334','阮明',7,'一定要收下，不然我心里过意不去呢。','yí dìng yào shōu xià， bù rán wǒ xīn lǐ guò yì bù qù ne。','Nhất định phải nhận đó, không thì mình áy náy trong lòng lắm.','AM04');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT335','S113','Hỏi sở thích để tìm điểm chung với bạn mới',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V335','SIT335','P1','suon_se','tuy_y',NULL,'初次认识的年轻人会通过爱好聊天，找到共同兴趣能快速拉近彼此距离。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_01','V335','阮明',1,'课余时间你平时都喜欢做什么呀？','kè yú shí jiān nǐ píng shí dōu xǐ huān zuò shén me ya？','Ngoài giờ học bạn thường thích làm gì thế?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_02','V335','苏雯',2,'我有空就会追剧、出门爬山，你呢？','wǒ yǒu kòng jiù huì zhuī jù、 chū mén pá shān， nǐ ne？','Rảnh thì mình hay xem phim, đi leo núi, còn bạn thì sao?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_03','V335','阮明',3,'我也很喜欢爬山，只是刚来还不熟悉周边路线。','wǒ yě hěn xǐ huān pá shān， zhǐ shì gāng lái hái bù shú xī zhōu biān lù xiàn。','Mình cũng rất thích leo núi, chỉ là mới đến đây nên chưa quen đường xá xung quanh thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_04','V335','苏雯',4,'学校附近有一座小山，周末可以一起去的。','xué xiào fù jìn yǒu yī zuò xiǎo shān， zhōu mò kě yǐ yì qǐ qù de。','Gần trường có một ngọn núi nhỏ, cuối tuần có thể đi cùng nhau đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_05','V335','阮明',5,'太棒了，我还担心找不到同好呢。','tài bàng le， wǒ hái dān xīn zhǎo bú dào tóng hào ne。','Tuyệt quá, mình còn đang lo không tìm được ai hợp gu nữa chứ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_06','V335','苏雯',6,'那我们加个微信，周末约着一起出发吧。','nà wǒ men jiā gè wēi xìn， zhōu mò yuē zhe yì qǐ chū fā ba。','Vậy tụi mình kết bạn Wechat đi, cuối tuần hẹn nhau cùng xuất phát nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_07','V335','阮明',7,'好呀，终于找到一样爱好的朋友啦。','hǎo ya， zhōng yú zhǎo dào yī yàng ài hào de péng yǒu la。','Được đó, cuối cùng cũng tìm được người bạn có cùng sở thích rồi.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT336','S114','Đăng ký tham gia câu lạc bộ sinh viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V336','SIT336','P1','twist','ban_chinh_thuc',NULL,'国内高校社团统一在开学招新，多数社团有活动人数限制，需要提前登记报名。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_01','V336','阮明',1,'学姐你好，我想报名加入咱们汉服社团可以吗？','xué jiě nǐ hǎo， wǒ xiǎng bào míng jiā rù zán men hàn fú shè tuán kě yǐ ma？','Chào chị, em muốn đăng ký tham gia câu lạc bộ Hán phục của mình có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_02','V336','学姐',2,'当然可以，先填一张信息登记表哦。','dāng rán kě yǐ， xiān tián yī zhāng xìn xī dēng jì biǎo ó。','Đương nhiên được rồi, em điền vào một tờ đăng ký thông tin trước nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_03','V336','阮明',3,'好的，我平时很喜欢中国传统服饰和文化。','hǎo de， wǒ píng shí hěn xǐ huān zhōng guó chuán tǒng fú shì hé wén huà。','Vâng ạ, em vốn rất thích trang phục và văn hóa truyền thống Trung Quốc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_04','V336','学姐',4,'咱们每周有线下活动，不过本周活动名额满了。','zán men měi zhōu yǒu xiàn xià huó dòng， bù guò běn zhōu huó dòng míng é mǎn le。','Tụi mình có hoạt động offline hàng tuần, nhưng tuần này số lượng tham gia đã đủ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_05','V336','阮明',5,'啊？那我下周能正常参与活动吗？','a？ nà wǒ xià zhōu néng zhèng cháng cān yù huó dòng ma？','Ơ? Vậy tuần sau em có thể tham gia hoạt động bình thường được không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_06','V336','学姐',6,'没问题，下周名额会重新开放，记得准时来。','méi wèn tí， xià zhōu míng é huì chóng xīn kāi fàng， jì de zhǔn shí lái。','Không vấn đề gì, tuần sau sẽ mở lại suất tham gia, nhớ đến đúng giờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_07','V336','阮明',7,'好，我会记好时间，麻烦学姐啦。','hǎo， wǒ huì jì hǎo shí jiān， má fán xué jiě la。','Vâng, em sẽ ghi nhớ thời gian, phiền chị nhiều ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT337','S112','Giải thích khi hiểu nhầm ý của bạn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V337','SIT337','P1','suon_se','ban_chinh_thuc',NULL,'朋友产生隔阂后，中国人会主动沟通解释，厘清误会后不会一直记在心里。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_01','V337','阮明',1,'昨天那件事你是不是误会我了，我跟你解释一下吧。','zuó tiān nà jiàn shì nǐ shì bú shì wù huì wǒ le， wǒ gēn nǐ jiě shì yī xià ba。','Chuyện hôm qua chắc là cậu hiểu lầm mình rồi, để mình giải thích cho cậu nghe nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_02','V337','李然',2,'我昨天确实有点生气，你说说是什么情况。','wǒ zuó tiān què shí yǒu diǎn shēng qì， nǐ shuō shuō shì shén me qíng kuàng。','Hôm qua mình đúng là có hơi giận, cậu nói xem rốt cuộc là chuyện gì.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_03','V337','阮明',3,'我不是故意放你鸽子，是老师临时留我补作业呢。','wǒ bú shì gù yì fàng nǐ gē zi， shì lǎo shī lín shí liú wǒ bǔ zuò yè ne。','Mình không phải cố tình cho cậu leo cây đâu, là do thầy giữ lại để bù bài tập đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_04','V337','李然',4,'原来是这样，我还以为你不想跟我出门。','yuán lái shì zhè yàng， wǒ hái yǐ wéi nǐ bù xiǎng gēn wǒ chū mén。','Thì ra là vậy, mình còn tưởng cậu không muốn đi chơi với mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_05','V337','阮明',5,'怎么会，我一直很期待和你逛街的。','zěn me huì， wǒ yì zhí hěn qī dài hé nǐ guàng jiē de。','Sao có thể như vậy được, mình lúc nào cũng mong được đi dạo phố cùng cậu mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_06','V337','李然',6,'行，我明白啦，这件事就翻篇不提了。','xíng， wǒ míng bái la， zhè jiàn shì jiù fān piān bù tí le。','Được rồi, mình hiểu rồi, chuyện này coi như bỏ qua, không nhắc lại nữa nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_07','V337','阮明',7,'太好了，下次出门我提前跟你确认时间。','tài hǎo le， xià cì chū mén wǒ tí qián gēn nǐ què rèn shí jiān。','Tuyệt quá, lần sau đi đâu mình sẽ báo trước giờ giấc với cậu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT338','S112','Chúc mừng sinh nhật bạn cùng phòng',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V338','SIT338','P1','suon_se','tuy_y',NULL,'大学生宿舍室友常会合伙买蛋糕、礼物一起过生日，是宿舍常见暖心活动。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_01','V338','阮明',1,'张明，生日快乐！快拆开我们准备的蛋糕吧。','zhāng míng， shēng rì kuài lè！ kuài chāi kāi wǒ men zhǔn bèi de dàn gāo ba。','Trương Minh, chúc mừng sinh nhật cậu! Mau mở bánh kem tụi mình chuẩn bị đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_02','V338','张明',2,'哇，你们居然还记得我的生日，太惊喜了。','wa， nǐ men jū rán hái jì de wǒ de shēng rì， tài jīng xǐ le。','Wow, không ngờ các cậu còn nhớ sinh nhật mình, bất ngờ quá đi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_03','V338','阮明',3,'我们悄悄凑钱买的，还有小礼物送给你呢。','wǒ men qiāo qiāo còu qián mǎi de， hái yǒu xiǎo lǐ wù sòng gěi nǐ ne。','Tụi mình lén góp tiền mua đó, còn có quà nhỏ tặng cậu nữa nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_04','V338','张明',4,'真的不用这么破费，有你们陪伴就足够啦。','zhēn de bù yòng zhè me pò fèi， yǒu nǐ men péi bàn jiù zú gòu la。','Thật sự không cần tốn kém vậy đâu, có các cậu ở bên là đủ rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_05','V338','阮明',5,'室友之间不用客气，赶紧许愿吹蜡烛哦。','shì yǒu zhī jiān bù yòng kè qì， gǎn jǐn xǔ yuàn chuī là zhú ó。','Bạn cùng phòng với nhau khỏi cần khách sáo, mau ước nguyện rồi thổi nến đi nào.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_06','V338','张明',6,'好，我许个愿，希望我们宿舍一直和睦。','hǎo， wǒ xǔ gè yuàn， xī wàng wǒ men sù shè yì zhí hé mù。','Được, mình ước một điều, mong phòng mình mãi hòa thuận vui vẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_07','V338','阮明',7,'一定会的，咱们切蛋糕一起分享！','yí dìng huì de， zán men qiè dàn gāo yì qǐ fēn xiǎng！','Chắc chắn sẽ vậy mà, giờ cắt bánh cùng ăn thôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT339','S112','Hỏi mượn đồ dùng cá nhân từ bạn cùng lớp',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V339','SIT339','P1','twist','tuy_y',NULL,'向他人借私人物品需要主动询问，用完及时归还，很多人会用小饮品、零食答谢对方。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_01','V339','阮明',1,'菲菲，能不能借你的笔记本电脑用半小时啊？','fēi fēi， néng bù néng jiè nǐ de bǐ jì běn diàn nǎo yòng bàn xiǎo shí a？','Phi Phi ơi, cho mình mượn laptop dùng nửa tiếng được không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_02','V339','刘菲',2,'不好意思，我电脑拿去图书馆充电了嘛。','bù hǎo yì sī， wǒ diàn nǎo ná qù tú shū guǎn chōng diàn le ma。','Ngại quá, máy tính mình đem ra thư viện sạc pin rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_03','V339','阮明',3,'这样啊，那你有多余的U盘借我拷贝文件吗？','zhè yàng a， nà nǐ yǒu duō yú de U pán jiè wǒ kǎo bèi wén jiàn ma？','Vậy à, thế cậu có USB dư cho mình mượn để copy tài liệu không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_04','V339','刘菲',4,'这个可以，我包里刚好有一个全新的。','zhè ge kě yǐ， wǒ bāo lǐ gāng hǎo yǒu yí gè quán xīn de。','Cái này thì được, trong túi mình vừa hay có một cái còn mới tinh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_05','V339','阮明',5,'太感谢了，用完我马上还给你，绝不弄丢。','tài gǎn xiè le， yòng wán wǒ mǎ shàng huán gěi nǐ， jué bù nòng diū。','Cảm ơn cậu nhiều lắm, dùng xong mình trả ngay, tuyệt đối không làm mất đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_06','V339','刘菲',6,'没关系，你慢慢用，不用着急归还。','méi guān xì， nǐ màn màn yòng， bù yòng zháo jí guī huán。','Không sao đâu, cậu cứ từ từ dùng, không cần vội trả lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_07','V339','阮明',7,'好嘞，等下请你喝奶茶作为答谢。','hǎo lei， děng xià qǐng nǐ hē nǎi chá zuò wéi dá xiè。','Được rồi, lát nữa mình mời cậu uống trà sữa để cảm ơn nhé.','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT340','S112','Đề nghị đổi lịch hẹn vì bận đột xuất',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V340','SIT340','P1','suon_se','ban_chinh_thuc',NULL,'临时无法赴约，中国人会第一时间告知对方，主动协商新时间，避免对方空等。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_01','V340','阮明',1,'实在抱歉，我们下午约好逛书店得改时间了。','shí zài bào qiàn， wǒ men xià wǔ yuē hǎo guàng shū diàn dé gǎi shí jiān le。','Thật sự xin lỗi, buổi chiều hẹn nhau đi nhà sách phải đổi giờ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_02','V340','吴桐',2,'怎么了，是临时有突发事情吗？','zěn me le， shì lín shí yǒu tū fā shì qíng ma？','Sao vậy, có chuyện gì đột xuất à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_03','V340','阮明',3,'辅导员通知我去办公室提交留学材料呢。','fǔ dǎo yuán tōng zhī wǒ qù bàn gōng shì tí jiāo liú xué cái liào ne。','Cố vấn học tập kêu mình lên văn phòng nộp hồ sơ du học đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_04','V340','吴桐',4,'没事，正事要紧，我们改到明天下午行吗？','méi shì， zhèng shì yào jǐn， wǒ men gǎi dào míng tiān xià wǔ xíng ma？','Không sao, việc chính quan trọng hơn, hay tụi mình đổi sang chiều mai nhé?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_05','V340','阮明',5,'明天下午我全天有空，完全没问题的。','míng tiān xià wǔ wǒ quán tiān yǒu kòng， wán quán méi wèn tí de。','Chiều mai mình rảnh cả ngày, hoàn toàn không vấn đề gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_06','V340','吴桐',6,'那就定明天三点，咱们校门口碰面吧。','nà jiù dìng míng tiān sān diǎn， zán men xiào mén kǒu pèng miàn ba。','Vậy chốt ba giờ chiều mai, mình gặp nhau ở cổng trường nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_07','V340','阮明',7,'好，明天我提前十分钟在门口等你啦。','hǎo， míng tiān wǒ tí qián shí fēn zhōng zài mén kǒu děng nǐ la。','Được, mai mình sẽ đến trước mười phút đợi cậu ở cổng.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT341','S114','Xin nghỉ một buổi sinh hoạt câu lạc bộ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V341','SIT341','P1','suon_se','ban_chinh_thuc',NULL,'学生社团有事无法参与活动，需要提前向负责人报备请假，不能无故缺席。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_01','V341','阮明',1,'学姐，我想跟你请假，本周的社团活动没法参加了。','xué jiě， wǒ xiǎng gēn nǐ qǐng jià， běn zhōu de shè tuán huó dòng méi fǎ cān jiā le。','Chị ơi, em muốn xin phép nghỉ, tuần này em không tham gia sinh hoạt câu lạc bộ được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_02','V341','学姐',2,'可以，你是有什么重要的事情耽误了吗？','kě yǐ， nǐ shì yǒu shén me zhòng yào de shì qíng dān wù le ma？','Được thôi, em có việc gì quan trọng nên phải nghỉ à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_03','V341','阮明',3,'下周有汉语考试，我需要全天在家复习嘛。','xià zhōu yǒu hàn yǔ kǎo shì， wǒ xū yào quán tiān zài jiā fù xí ma。','Tuần sau em có kỳ thi tiếng Trung, em cần ở nhà ôn bài cả ngày ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_04','V341','学姐',4,'原来是备考，学习优先，我帮你登记请假。','yuán lái shì bèi kǎo， xué xí yōu xiān， wǒ bāng nǐ dēng jì qǐng jià。','Thì ra là ôn thi, học hành quan trọng hơn, để chị đăng ký nghỉ phép giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_05','V341','阮明',5,'活动的任务我下周会主动补上，不会落下进度。','huó dòng de rèn wù wǒ xià zhōu huì zhǔ dòng bǔ shàng， bú huì là xià jìn dù。','Nhiệm vụ của hoạt động tuần sau em sẽ chủ động bù lại, không để chậm tiến độ đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_06','V341','学姐',6,'不用着急，等你考完试再来参与就行。','bù yòng zháo jí， děng nǐ kǎo wán shì zài lái cān yù jiù xíng。','Không cần vội đâu, đợi em thi xong rồi tham gia lại cũng được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_07','V341','阮明',7,'辛苦学姐体谅我啦，非常感谢。','xīn kǔ xué jiě tǐ liàng wǒ la， fēi cháng gǎn xiè。','Cảm ơn chị đã thông cảm cho em nhiều lắm ạ.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT342','S112','Khen món ăn bạn Trung Quốc nấu, đáp lại khi được khen',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V342','SIT342','P1','suon_se','tuy_y',NULL,'品尝他人亲手做的饭菜，中国人会真诚夸赞，还会互相邀约交换拿手菜。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_01','V342','阮明',1,'你做的番茄炒蛋也太好吃了吧，味道超正宗！','nǐ zuò de fān qié chǎo dàn yě tài hǎo chī le ba， wèi dào chāo zhèng zōng！','Món trứng chiên cà chua cậu làm ngon quá đi, vị đúng chuẩn luôn!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_02','V342','小雅',2,'没有啦，就是简单家常菜，你喜欢就多吃点。','méi yǒu la， jiù shì jiǎn dān jiā cháng cài， nǐ xǐ huān jiù duō chī diǎn。','Có gì đâu, chỉ là món ăn nhà đơn giản thôi, cậu thích thì ăn thêm nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_03','V342','阮明',3,'比校外餐馆做得还香，你厨艺也太好了啊。','bǐ xiào wài cān guǎn zuò dé hái xiāng， nǐ chú yì yě tài hǎo le a。','Ngon hơn cả quán ăn bên ngoài trường nữa, tay nghề nấu ăn của cậu giỏi quá.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_04','V342','小雅',4,'谢谢你夸奖，下次我教你一起做呢。','xiè xiè nǐ kuā jiǎng， xià cì wǒ jiāo nǐ yì qǐ zuò ne。','Cảm ơn cậu khen, lần sau mình chỉ cho cậu làm cùng luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_05','V342','阮明',5,'那太好了，我还怕自己学不会。','nà tài hǎo le， wǒ hái pà zì jǐ xué bú huì。','Vậy thì tốt quá, mình còn sợ mình học không nổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_06','V342','小雅',6,'不难的，下次你做家乡菜给我尝尝吧。','bù nán de， xià cì nǐ zuò jiā xiāng cài gěi wǒ cháng cháng ba。','Không khó đâu, lần sau cậu làm món quê hương cho mình nếm thử nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_07','V342','阮明',7,'没问题，下次我带食材过来，一定露一手！','méi wèn tí， xià cì wǒ dài shí cái guò lái， yí dìng lòu yī shǒu！','Không vấn đề gì, lần sau mình mang nguyên liệu qua, thế nào cũng trổ tài cho xem!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT343','S115','Mua điện thoại mới, hỏi thông số',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V343','SIT343','P1','suon_se','tuy_y',NULL,'线下买电子产品，顾客可以自由询问全部参数，对比多款机型，店家不会催促下单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_01','V343','阮明',1,'你好，这款新款手机内存和电池容量是多少啊？','nǐ hǎo， zhè kuǎn xīn kuǎn shǒu jī nèi cún hé diàn chí róng liàng shì duō shǎo a？','Chào bạn, mẫu điện thoại mới này bộ nhớ với dung lượng pin bao nhiêu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_02','V343','销售员',2,'这款手机256G内存，电池续航一整天没问题。','zhè kuǎn shǒu jī 256G nèi cún， diàn chí xù háng yī zhěng tiān méi wèn tí。','Mẫu này bộ nhớ 256G, pin dùng cả ngày không thành vấn đề.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_03','V343','阮明',3,'拍照像素高吗？我平时很喜欢出门拍照呢。','pāi zhào xiàng sù gāo ma？ wǒ píng shí hěn xǐ huān chū mén pāi zhào ne。','Chụp ảnh có nét không? Mình bình thường thích ra ngoài chụp hình lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_04','V343','销售员',4,'后置五千万像素，夜景拍摄效果特别清晰。','hòu zhì wǔ qiān wàn xiàng sù， yè jǐng pāi shè xiào guǒ tè bié qīng xī。','Camera sau năm mươi triệu điểm ảnh, chụp cảnh đêm cực kỳ nét.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_05','V343','阮明',5,'那处理器运行会不会卡顿，适合学习软件吗？','nà chǔ lǐ qì yùn xíng huì bú huì kǎ dùn， shì hé xué xí ruǎn jiàn ma？','Vậy con chip chạy có bị giật lag không, dùng phần mềm học tập có ổn không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_06','V343','销售员',6,'配置足够流畅运行各类软件，学生用很合适。','pèi zhì zú gòu liú chàng yùn xíng gè lèi ruǎn jiàn， xué shēng yòng hěn hé shì。','Cấu hình đủ mượt để chạy các loại phần mềm, sinh viên dùng rất hợp đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_07','V343','阮明',7,'行，那我再对比一下另一款，等下再来找你。','xíng， nà wǒ zài duì bǐ yī xià lìng yī kuǎn， děng xià zài lái zhǎo nǐ。','Được, vậy mình so sánh thêm với mẫu kia nữa, lát nữa quay lại tìm bạn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT344','S115','Mang điện thoại đi sửa màn hình vỡ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V344','SIT344','P1','twist','ban_chinh_thuc',NULL,'手机维修更换配件分原装和平价配件，店家会主动区分报价，配件缺货会告知顾客取机时间。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_01','V344','阮明',1,'师傅，我的手机屏幕摔碎了，能帮忙更换吗？','shī fù， wǒ de shǒu jī píng mù shuāi suì le， néng bāng máng gēng huàn ma？','Anh ơi, màn hình điện thoại em bị rớt vỡ rồi, anh giúp em thay được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_02','V344','维修师傅',2,'可以，先看看型号，原装屏幕价格贵一点哈。','kě yǐ， xiān kàn kàn xíng hào， yuán zhuāng píng mù jià gé guì yì diǎn hā。','Được, để xem model trước đã, màn hình chính hãng giá sẽ hơi cao đó.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_03','V344','阮明',3,'原装的大概多少钱，维修需要等多久呢？','yuán zhuāng de dà gài duō shǎo qián， wéi xiū xū yào děng duō jiǔ ne？','Hàng chính hãng khoảng bao nhiêu tiền vậy anh, sửa phải đợi lâu không?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_04','V344','维修师傅',4,'三百五十元，可惜现在店里没有现货屏幕。','sān bǎi wǔ shí yuán， kě xī xiàn zài diàn lǐ méi yǒu xiàn huò píng mù。','Ba trăm năm mươi tệ, tiếc là cửa hàng hiện không có sẵn màn hình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_05','V344','阮明',5,'啊？那什么时候能到货，我手机每天都要用。','a？ nà shén me shí hòu néng dào huò， wǒ shǒu jī měi tiān dōu yào yòng。','Hả? Vậy khi nào có hàng vậy anh, điện thoại em ngày nào cũng phải dùng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_06','V344','维修师傅',6,'明天中午到货，你明天下午过来取就行。','míng tiān zhōng wǔ dào huò， nǐ míng tiān xià wǔ guò lái qǔ jiù xíng。','Trưa mai hàng về, em chiều mai đến lấy là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_07','V344','阮明',7,'好，我明天准时过来，麻烦师傅预留屏幕。','hǎo， wǒ míng tiān zhǔn shí guò lái， má fán shī fù yù liú píng mù。','Dạ, mai em sẽ đến đúng giờ, phiền anh giữ màn hình giúp em nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT345','S116','Mua laptop, hỏi bảo hành',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V345','SIT345','P1','suon_se','ban_chinh_thuc',NULL,'国内数码产品均提供全国联保服务，门店会清晰告知保修时长、售后范围。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_01','V345','阮明',1,'这款笔记本适合留学生写论文、做PPT吗？','zhè kuǎn bǐ jì běn shì hé liú xué shēng xiě lùn wén、 zuò PPT ma？','Mẫu laptop này có phù hợp cho du học sinh viết luận văn, làm PPT không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_02','V345','导购',2,'完全适配，轻薄便携，性能足够日常学习的。','wán quán shì pèi， qīng bó biàn xié， xìng néng zú gòu rì cháng xué xí de。','Hoàn toàn phù hợp, mỏng nhẹ dễ mang theo, hiệu năng đủ dùng cho học tập hàng ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_03','V345','阮明',3,'那整机官方保修时长是多久呀？','nà zhěng jī guān fāng bǎo xiū shí cháng shì duō jiǔ ya？','Vậy thời hạn bảo hành chính hãng của cả máy là bao lâu ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, đóng thêm tiền có thể nâng lên ba năm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành nếu hệ thống bị lỗi có được sửa tận nơi miễn phí không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong phạm vi nội thành thì được sửa tận nơi miễn phí, ngoài phạm vi thì phải mang ra cửa hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Em hiểu rồi, để em suy nghĩ thêm, lát nữa quay lại thanh toán nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào bạn, phòng trọ mình thuê muốn đăng ký lắp mạng internet.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào anh/chị, xin cho em địa chỉ chi tiết, em kiểm tra tình trạng phủ sóng đường truyền ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là tòa 3 phòng 502, khu dân cư gần trường đại học, phiền bạn kiểm tra giúp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Xin lỗi anh/chị, cổng mạng tuần này ở khu của mình đã hết sạch rồi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy à, thế đợt cổng mạng tiếp theo khi nào mở vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở lại, đến lúc đó em có thể nhắc anh/chị đặt lịch trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Được, vậy phiền bạn ba ngày nữa liên hệ mình nhé, cảm ơn bạn nhiều.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tớ vừa đổi điện thoại mới, chẳng biết chuyển dữ liệu từ máy cũ sang thế nào cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản mà, máy có sẵn phần mềm chuyển dữ liệu, cứ làm theo hướng dẫn là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn chat, ảnh với file có copy nguyên vẹn sang được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Được hết luôn, chỉ cần hai máy kết nối chung một mạng WiFi thôi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_05','V347','阮明',5,'我还担心会丢失重要的学习资料。','wǒ hái dān xīn huì diū shī zhòng yào de xué xí zī liào。','Tớ còn lo bị mất mấy tài liệu học quan trọng nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_06','V347','小杨',6,'放心，我上次换机一点资料都没漏掉。','fàng xīn， wǒ shàng cì huàn jī yì diǎn zī liào dōu méi lòu diào。','Yên tâm đi, lần trước tớ đổi máy chẳng thiếu tí dữ liệu nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_07','V347','阮明',7,'太谢谢你了，等下我操作有问题再来问你吧。','tài xiè xiè nǐ le， děng xià wǒ cāo zuò yǒu wèn tí zài lái wèn nǐ ba。','Cảm ơn cậu nhiều nha, lát nữa thao tác có gì tớ lại hỏi cậu tiếp.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT348','S118','Cài đặt và đăng ký app dịch tiếng Trung',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V348','SIT348','P1','suon_se','tuy_y',NULL,'留学生常用翻译APP辅助学习中文，国内软件支持微信、QQ快捷登录，注册流程简单。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_01','V348','阮明',1,'有没有好用的翻译软件推荐我下载一下啊？','yǒu méi yǒu hǎo yòng de fān yì ruǎn jiàn tuī jiàn wǒ xià zài yī xià a？','Có app dịch nào dùng ngon giới thiệu tớ tải về không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_02','V348','小林',2,'这款翻译APP特别适合留学生，离线也能用呢。','zhè kuǎn fān yì APP tè bié shì hé liú xué shēng， lí xiàn yě néng yòng ne。','App dịch này hợp với du học sinh lắm, không có mạng vẫn dùng được nè.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_03','V348','阮明',3,'下载之后注册需要绑定手机号吗？','xià zài zhī hòu zhù cè xū yào bǎng dìng shǒu jī hào ma？','Tải xong đăng ký có cần gắn số điện thoại không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_04','V348','小林',4,'只用微信一键登录就可以，不用额外注册啦。','zhǐ yòng wēi xìn yī jiàn dēng lù jiù kě yǐ， bù yòng é wài zhù cè la。','Chỉ cần đăng nhập bằng WeChat một chạm là xong, khỏi cần đăng ký thêm.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_05','V348','阮明',5,'还能拍照翻译课本上的汉字，对吗？','hái néng pāi zhào fān yì kè běn shàng de hàn zì， duì ma？','Nó còn chụp ảnh dịch chữ Hán trong sách được nữa đúng không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_06','V348','小林',6,'没错，拍照翻译准确度很高，日常学习够用。','méi cuò， pāi zhào fān yì zhǔn què dù hěn gāo， rì cháng xué xí gòu yòng。','Đúng rồi, chụp ảnh dịch chuẩn lắm, dùng học hàng ngày là đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_07','V348','阮明',7,'太好了，我现在就下载安装试试吧。','tài hǎo le， wǒ xiàn zài jiù xià zài ān zhuāng shì shì ba。','Tuyệt quá, để tớ tải về cài thử luôn bây giờ.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào chị, gói cước data của em hết hạn hôm nay rồi, em muốn gia hạn luôn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được, em cho xem số thuê bao, chị kiểm tra các gói cước giúp em nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Em dùng data nhiều lắm, có gói dành cho sinh viên không giới hạn dung lượng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho sinh viên tháng này ngừng bán rồi, chỉ còn gói thường thôi à.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','Vậy ạ, thế gói thường mỗi tháng bao nhiêu data, cước bao nhiêu tiền vậy chị?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G, cước ba mươi chín tệ, tính ra khá hời đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Được ạ, vậy chị làm gia hạn gói thường này giúp em nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Anh thợ ơi, WiFi phòng em tự nhiên mất kết nối, phiền anh đến kiểm tra giúp em ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, để anh kiểm tra bộ chuyển quang với router trước, khả năng cao là dây bị lỏng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng còn chạy êm ru mà, sáng nay tự dưng mất mạng luôn.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Anh cắm lại dây cho chặt, rồi reset lại router là mạng sẽ ổn lại thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa vậy có phải trả thêm phí dịch vụ gì không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Còn trong thời hạn bảo hành mạng thì đến sửa hoàn toàn miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, cảm ơn anh vất vả xử lý giúp em nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào bạn, mình muốn chuyển tiền cho bạn học qua app ngân hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào bạn, bạn cần nhập số tài khoản và tên người nhận để đối chiếu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển tiền có giới hạn không, mình chuyển một lần ba nghìn tệ được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại dành cho sinh viên hạn mức chuyển một ngày là năm mươi nghìn tệ, hoàn toàn thoải mái.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi có tin nhắn báo cho cả hai bên không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều nhận được thông báo, để tiện đối chiếu giao dịch đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Mình hiểu rõ quy trình rồi, cảm ơn bạn đã giải thích nhé.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào chị, người nhà em ở nước ngoài gửi cho em một khoản tiền sinh hoạt, em muốn làm thủ tục kết hối ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Em cho chị xem hộ chiếu và thẻ ngân hàng, chị kiểm tra tình trạng tiền về trước đã.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Vâng, giấy tờ em mang đủ hết rồi ạ, hình như chuyển từ chiều tối hôm qua.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi em, khoản tiền này chưa được thanh toán bù trừ, hôm nay tạm thời chưa rút được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ? Vậy phải đợi đến khi nào mới đổi được sang nhân dân tệ ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống xử lý xong là được, em quay lại quầy làm thủ tục là ổn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Vâng, mai sáng em qua sớm, phiền chị ghi chú giúp em với ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì vậy, em không rành lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ vào trước, nhập mật khẩu, rồi chọn số tiền cần rút là xong ngay.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Một ngày rút tối đa được bao nhiêu tiền mặt vậy, có bị giới hạn không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','ATM giới hạn một ngày hai chục nghìn tệ, dùng cho chi tiêu hàng ngày là quá đủ rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhớ rút thẻ ra ngay đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng vậy, để quá lâu không rút thẻ máy sẽ tự động nuốt thẻ đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nha, không thì em dễ quên lắm.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Chào chị, thẻ ngân hàng của em bị mất rồi, em muốn báo mất khẩn cấp và khóa thẻ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Bạn vui lòng cho biết họ tên, bốn số cuối thẻ và số căn cước công dân nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Em nhớ hết thông tin rồi ạ, để em đọc cho chị đối chiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm thời phong tỏa thẻ cho bạn, tiền trong tài khoản sẽ không bị mất đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau này làm lại thẻ mới có cần ra quầy trực tiếp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng đúng vậy, bạn mang hộ chiếu đến chi nhánh gần nhất là làm lại được ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn chị nhiều ạ, may mà em gọi điện báo mất kịp thời.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào bạn, tôi cần in sao kê giao dịch thẻ ngân hàng trong khoảng nửa năm gần đây.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được, bạn cho xem thẻ ngân hàng và hộ chiếu, tôi tra lịch sử giao dịch giúp bạn nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê như vậy có mất phí gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh làm sao kê phục vụ mục đích du học thì được miễn phí đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Tuyệt quá, tôi cần nộp cho trường làm giấy chứng minh tài chính.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Tôi sẽ đóng dấu chính thức của ngân hàng lên, trường có thể công nhận trực tiếp luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn bạn nhiều, lát tôi lấy sao kê xong là ra về.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào bạn, tôi muốn đổi mật khẩu rút tiền của thẻ ngân hàng tại máy tự phục vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Bạn cắm thẻ, nhập mật khẩu cũ trước, rồi đặt mật khẩu mới gồm sáu chữ số nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Tôi vừa nhập một lần rồi, nó báo hai lần mật khẩu không khớp nhau kìa.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Tôi nhìn màn hình không rõ, hai lần gõ số không giống nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao đâu, bạn làm lại một lần nữa, chú ý đối chiếu kỹ số là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Được, tôi sẽ làm từ từ, lần này chắc chắn để ý kỹ thông báo trên màn hình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công rồi, cảm ơn bạn đã đứng bên hướng dẫn tôi nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Chào chị, nếu tôi chuyển khoản sang tài khoản ở Việt Nam thì phí giao dịch được tính như thế nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí giao dịch gồm hai phần: phí xử lý cố định và phí điện tín quốc tế ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì phí có thay đổi theo không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Mức phí là cố định, không tăng giảm theo số tiền chuyển đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền vào được tài khoản ngân hàng nước ngoài của người nhận ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, vào dịp lễ thì thời gian đối soát sẽ bị lùi lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi đã hiểu rõ hết rồi, cảm ơn chị đã giải thích tận tình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我上周下单付款扣款成功，至今没收到包裹。','nǐ hǎo， wǒ shàng zhōu xià dān fù kuǎn kòu kuǎn chéng gōng， zhì jīn mò shōu dào bāo guǒ。','Chào anh/chị, tuần trước tôi đặt hàng và thanh toán thành công nhưng đến giờ vẫn chưa nhận được hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'麻烦提供订单编号，我查询物流配送记录哈。','má fán tí gōng dìng dān biān hào， wǒ chá xún wù liú pèi sòng jì lù hā。','Phiền anh/chị cung cấp mã đơn hàng, để tôi kiểm tra thông tin vận chuyển nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单号在这里，物流一直显示待揽收状态呢。','dìng dān hào zài zhè lǐ， wù liú yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng đây, phần vận chuyển cứ hiện trạng thái chờ lấy hàng mãi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'查到了，仓库漏发商品，实在非常抱歉。','chá dào le， cāng kù lòu fā shāng pǐn， shí zài fēi cháng bào qiàn。','Tôi kiểm tra thấy rồi, kho hàng đã sót không gửi hàng, thật sự rất xin lỗi anh/chị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'那现在是补发商品还是直接全额退款？','nà xiàn zài shì bǔ fā shāng pǐn hái shì zhí jiē quán é tuì kuǎn？','Vậy bây giờ là gửi lại hàng hay hoàn tiền toàn bộ luôn ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'两种方案都可以，补发需要再等三天发货。','liǎng zhǒng fāng àn dōu kě yǐ， bǔ fā xū yào zài děng sān tiān fā huò。','Cả hai phương án đều được, nếu gửi lại thì phải đợi thêm ba ngày mới xuất hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'我选择全额退款吧，不想继续等待了。','wǒ xuǎn zé quán é tuì kuǎn ba， bù xiǎng jì xù děng dài le。','Tôi chọn hoàn tiền toàn bộ thôi, không muốn chờ thêm nữa.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chú ơi, cháu muốn ra phố đi bộ trung tâm thành phố thì đón xe buýt tuyến nào vậy chú?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra khỏi cửa rẽ phải, ra trạm đón tuyến 12 nhé, điểm cuối chính là trung tâm thành phố đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Đi một chuyến khoảng bao lâu vậy chú, có hay bị kẹt xe không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt thì tầm bốn mươi phút, giờ tan tầm thì chậm hơn một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt cho quét mã trên điện thoại để lên xe luôn chứ không cần làm thẻ cứng đúng không chú?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi đó, mở mã lên xe ra rồi quét là lên xe được ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cảm ơn chú chỉ đường nhiều lắm, giờ cháu ra trạm đợi xe luôn đây.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự động này nạp tiền cho thẻ tàu điện ngầm như thế nào vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Bạn đặt thẻ lên khu vực cảm ứng trước, rồi chọn số tiền cần nạp và quét mã thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Mình quét mã thanh toán xong rồi mà máy lại báo nạp tiền thất bại.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại đã bị trừ tiền rồi, nhưng số dư trong thẻ lại không tăng lên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Bạn đừng lo, hệ thống bị chậm thôi, đợi năm phút rồi kiểm tra lại số dư là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Thì ra là hệ thống bị lag, mình đợi một lát rồi xem lại số dư vậy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, không thì mình chẳng biết phải làm sao luôn á.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, mình quét mã xe đạp chia sẻ mà cứ mở khóa thất bại hoài vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Bạn xem thử bluetooth điện thoại đã bật chưa, đi xe là phải bật bluetooth đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth mình bật rồi mà, trên màn hình cứ báo xe bị lỗi hoài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là chiếc xe đó bị hỏng rồi, bạn bấm nút đổi xe là xong ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Thì ra là vậy, mình còn tưởng tài khoản của mình bị lỗi chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Ven đường còn nhiều xe dự phòng lắm, đổi qua xe khác là mở khóa được liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn bạn nhắc mình nhiều lắm, không thì mình phải đứng đây lâu lắm luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào anh, tôi muốn thuê một chiếc xe điện, chỉ thuê nửa ngày thôi có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Được chứ, nửa ngày ba mươi tệ, cần giữ hộ chiếu của bạn để đăng ký nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Đi xe ra điểm tham quan ngoại ô, lượng pin đi về có đủ không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy chạy được năm mươi cây số, đi quãng đường ngắn thì thoải mái đủ dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ trên đường hết pin, cửa hàng có thiết bị sạc khẩn cấp không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có bộ sạc di động, bạn có thể mang theo bên người để dự phòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Được rồi, vậy giờ tôi đăng ký thuê xe, phiền anh giúp nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào anh, tôi muốn dùng máy tự động mua một vé tàu cao tốc cuối tuần đi thành phố lân cận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Anh đặt hộ chiếu vào khu vực đọc thẻ trước, rồi nhập điểm đến là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn xong chuyến tàu rồi mà hệ thống báo giấy tờ người nước ngoài không xác thực trực tuyến được.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này thì phải ra quầy giao dịch trực tiếp, nhân viên sẽ nhập thông tin thủ công cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy giao dịch trực tiếp có đông người xếp hàng không, chắc phải đợi bao lâu vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Giờ không đông lắm đâu, khoảng mười phút là mua vé xong thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Được rồi, tôi ra quầy giao dịch trực tiếp ngay đây, cảm ơn anh đã hướng dẫn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi có mua vé tàu cao tốc sáng mai, muốn đổi sang chuyến buổi chiều.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Anh cho xem hộ chiếu dùng để mua vé, để tôi kiểm tra giúp tình trạng vé còn nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé như vậy có bị tính thêm phí không chị?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ khởi hành thì được đổi vé miễn phí một lần, đổi lần thứ hai mới tính phí đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều còn chỗ trống đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Vẫn còn ghế hạng hai, để tôi đổi luôn thông tin chuyến tàu cho anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị nhiều, lịch trình thay đổi đột xuất thật ngại quá.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Bác tài ơi làm ơn nhanh giúp em một chút, em thấy khó chịu trong người phải đi bệnh viện gấp.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Yên tâm đi, tôi sẽ tránh mấy đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Cho em xuống ở cổng chính bệnh viện thôi, không cần chạy vào bãi xe ngầm được không bác?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Được chứ, khu vực đón trả khách tạm thời ở cổng chính có thể dừng một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Em chóng mặt lắm, bác chạy êm êm giúp em với nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, có gì khó chịu thì cứ nói với tôi bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn bác tài đã thông cảm cho em nhiều lắm, đến nơi em thanh toán ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào anh, cho em hỏi tuyến buýt 18 chuyến cuối tối nay mấy giờ chạy vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín rưỡi, nhưng hôm nay tuyến điều chỉnh đột xuất nên chín giờ đã hết chuyến rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào khác để chuyển xe không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể chuyển sang tàu điện ngầm, chuyến cuối của tàu điện ngầm mười một giờ mới ngừng chạy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ đến ga tàu điện ngầm mất khoảng mấy phút vậy anh?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Khoảng bảy tám phút thôi, cứ đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_07','V366','阮明',7,'好，那我提前出发去坐地铁，多谢告知。','hǎo， nà wǒ tí qián chū fā qù zuò dì tiě， duō xiè gào zhī。','Dạ được, vậy em đi sớm ra bắt tàu điện ngầm, cảm ơn anh đã cho biết.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT367','S121','Hỏi lối ra gần nhất tới địa điểm cần đến',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V367','SIT367','P1','suon_se','tuy_y',NULL,'大型商场划分专门网约车上下客出口，普通主干道禁止车辆临时停靠，避免拥堵。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_01','V367','阮明',1,'师傅，我想打车，最近的商场出口往哪边走呢？','shī fù， wǒ xiǎng dǎ chē， zuì jìn de shāng chǎng chū kǒu wǎng nǎ biān zǒu ne？','Anh ơi, em muốn bắt taxi, lối ra gần nhất của trung tâm thương mại đi hướng nào vậy ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_02','V367','安保人员',2,'直走到中庭右转，一号门就是打车专用出口哦。','zhí zǒu dào zhōng tíng yòu zhuǎn， yī hào mén jiù shì dǎ chē zhuān yòng chū kǒu ó。','Đi thẳng đến sảnh giữa rồi rẽ phải, cửa số 1 chính là lối ra dành riêng cho taxi đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_03','V367','阮明',3,'一号门外面有专门的等候区域吧？','yī hào mén wài miàn yǒu zhuān mén de děng hòu qū yù ba？','Bên ngoài cửa số 1 có khu vực chờ riêng đúng không anh?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_04','V367','安保人员',4,'有的，路边不能随便停车，只能在指定区域等车。','yǒu de， lù biān bù néng suí biàn tíng chē， zhǐ néng zài zhǐ dìng qū yù děng chē。','Có chứ, ven đường không được đỗ xe tùy tiện đâu, chỉ được chờ xe ở khu quy định thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_05','V367','阮明',5,'我拎了不少东西，这条路线没有台阶对吗？','wǒ līn le bù shǎo dōng xī， zhè tiáo lù xiàn méi yǒu tái jiē duì ma？','Em xách khá nhiều đồ, đoạn đường này không có bậc thang chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_06','V367','安保人员',6,'全程平坦通道，推行李箱、拎重物都方便。','quán chéng píng tǎn tōng dào， tuī xíng lǐ xiāng、 līn zhòng wù dōu fāng biàn。','Cả đoạn đường đều bằng phẳng, kéo vali hay xách đồ nặng đều thoải mái.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_07','V367','阮明',7,'清楚了，麻烦你指路啦。','qīng chǔ le， má fán nǐ zhǐ lù la。','Em hiểu rồi, phiền anh chỉ đường giúp em nha.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT368','S123','Trả xe thuê trễ giờ, hỏi phụ phí',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V368','SIT368','P1','twist','ban_chinh_thuc',NULL,'共享电单车设置固定免费时长，超时产生溢价费用，平台优惠券一般仅抵扣基础租赁费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_01','V368','阮明',1,'你好，我租的共享电车超时半小时，要补多少钱？','nǐ hǎo， wǒ zū de gòng xiǎng diàn chē chāo shí bàn xiǎo shí， yào bǔ duō shǎo qián？','Chào anh, em thuê xe điện chung mà trễ giờ mất nửa tiếng, phải trả thêm bao nhiêu tiền ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_02','V368','运维员',2,'基础时长两小时，超出后每半小时加收五元哈。','jī chǔ shí cháng liǎng xiǎo shí， chāo chū hòu měi bàn xiǎo shí jiā shōu wǔ yuán hā。','Thời gian cơ bản là hai tiếng, quá giờ thì mỗi nửa tiếng tính thêm năm đồng nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_03','V368','阮明',3,'页面提示有超时罚款，不能直接抵扣优惠券嘛？','yè miàn tí shì yǒu chāo shí fá kuǎn， bù néng zhí jiē dǐ kòu yōu huì quàn ma？','Trên màn hình báo có phí phạt trễ giờ, không thể dùng phiếu giảm giá để trừ trực tiếp sao?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_04','V368','运维员',4,'超时产生的额外费用不支持优惠券抵扣的。','chāo shí chǎn shēng de é wài fèi yòng bù zhī chí yōu huì quàn dǐ kòu de。','Phí phát sinh do trễ giờ thì không áp dụng phiếu giảm giá được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_05','V368','阮明',5,'原来是这样，那我直接微信扫码支付就行？','yuán lái shì zhè yàng， nà wǒ zhí jiē wēi xìn sǎo mǎ zhī fù jiù xíng？','Thì ra là vậy, vậy em quét mã QR bằng WeChat thanh toán luôn là được phải không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_06','V368','运维员',6,'对，站点二维码扫码就能结清所有费用。','duì， zhàn diǎn èr wéi mǎ sǎo mǎ jiù néng jié qīng suǒ yǒu fèi yòng。','Đúng rồi, quét mã QR ở trạm là thanh toán hết mọi khoản luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_07','V368','阮明',7,'好，我马上付款，下次一定看好还车时限。','hǎo， wǒ mǎ shàng fù kuǎn， xià cì yí dìng kàn hǎo hái chē shí xiàn。','Dạ được, em thanh toán ngay đây, lần sau nhất định sẽ để ý giờ trả xe.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT369','S126','Báo mất hộ chiếu với cảnh sát',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V369','SIT369','P1','suon_se','chinh_thuc',NULL,'外籍人士丢失护照必须先到派出所开具遗失证明，再前往出入境大厅或大使馆补办证件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_01','V369','阮明',1,'警官您好……我的护照，今天弄丢了。','jǐng guān nín hǎo…… wǒ de hù zhào， jīn tiān nòng diū le。','Chào công an... hộ chiếu của tôi, hôm nay bị mất rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_02','V369','民警',2,'先别着急，说一下丢失的大致时间和地点吧。','xiān bié zháo jí， shuō yī xià diū shī de dà zhì shí jiān hé dì diǎn ba。','Anh/chị bình tĩnh đã, cho tôi biết thời gian và địa điểm mất đại khái nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_03','V369','阮明',3,'下午三点左右，我逛文具店结账之后就找不到了呢。','xià wǔ sān diǎn zuǒ yòu， wǒ guàng wén jù diàn jié zhàng zhī hòu jiù zhǎo bú dào le ne。','Khoảng ba giờ chiều, tôi mua đồ ở tiệm văn phòng phẩm xong thanh toán thì không thấy đâu nữa.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_04','V369','民警',4,'我做一份遗失报案记录，你填写个人基础信息。','wǒ zuò yī fèn yí shī bào àn jì lù， nǐ tián xiě gè rén jī chǔ xìn xī。','Tôi sẽ lập biên bản trình báo mất giấy tờ, anh/chị điền thông tin cá nhân cơ bản giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_05','V369','阮明',5,'做完笔录，我拿着回执就能去办临时证件吗？','zuò wán bǐ lù， wǒ ná zhe huí zhí jiù néng qù bàn lín shí zhèng jiàn ma？','Làm biên bản xong, tôi cầm giấy biên nhận là có thể đi làm giấy tờ tạm thời được chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_06','V369','民警',6,'是的，报案回执是补办证件必需的材料。','shì de， bào àn huí zhí shì bǔ bàn zhèng jiàn bì xū de cái liào。','Đúng vậy, giấy biên nhận trình báo là giấy tờ bắt buộc để làm lại hộ chiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_07','V369','阮明',7,'辛苦警官帮忙登记，这件事给你们添麻烦了。','xīn kǔ jǐng guān bāng máng dēng jì， zhè jiàn shì gěi nǐ men tiān má fán le。','Cảm ơn công an đã giúp lập hồ sơ, việc này làm phiền các anh chị rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT370','S126','Báo mất ví tiền nơi công cộng',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V370','SIT370','P1','twist','ban_chinh_thuc',NULL,'商场、餐厅等公共场所设有失物招领处，捡到私人物品大多会统一送至前台保管。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_01','V370','阮明',1,'你好，我刚刚在三楼餐厅弄丢了黑色钱包，可以广播寻物吗？','nǐ hǎo， wǒ gāng gāng zài sān lóu cān tīng nòng diū le hēi sè qián bāo， kě yǐ guǎng bō xún wù ma？','Chào chị, em vừa làm mất chiếc ví màu đen ở nhà hàng tầng 3, có thể phát loa tìm giúp em không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_02','V370','客服',2,'没问题，我立刻播放寻物广播，麻烦描述钱包特征哦。','méi wèn tí， wǒ lì kè bō fàng xún wù guǎng bō， má fán miáo shù qián bāo tè zhēng ó。','Không vấn đề gì, chị phát loa tìm đồ ngay đây, em mô tả đặc điểm chiếc ví giúp chị nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03','V370','阮明',3,'里面有现金、银行卡和学生证，对我很重要。','lǐ miàn yǒu xiàn jīn、 yín háng kǎ hé xué shēng zhèng， duì wǒ hěn zhòng yào。','Trong đó có tiền mặt, thẻ ngân hàng và thẻ sinh viên, quan trọng với em lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03B','V370','阮明',4,'不会已经被人拿走了吧……','bú huì yǐ jīng bèi rén ná zǒu le ba……','Không lẽ đã bị ai lấy mất rồi...','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_04','V370','客服',5,'刚刚保洁捡到一个钱包送到前台，我拿给你核对嘛。','gāng gāng bǎo jié jiǎn dào yí gè qián bāo sòng dào qián tái， wǒ ná gěi nǐ hé duì ma。','Vừa nãy nhân viên vệ sinh nhặt được một chiếc ví đem đến quầy lễ tân, chị đưa em xem có phải không nhé.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_05','V370','阮明',6,'真的吗？里面有一张越南留学生专属校园卡对吧？','zhēn de ma？ lǐ miàn yǒu yī zhāng yuè nán liú xué shēng zhuān shǔ xiào yuán kǎ duì ba？','Thật ạ? Trong đó có tấm thẻ sinh viên du học Việt Nam riêng đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_06','V370','客服',7,'没错，就是这一个，你确认物品齐全再拿走。','méi cuò， jiù shì zhè yí gè， nǐ què rèn wù pǐn qí quán zài ná zǒu。','Đúng rồi, chính là cái này, em kiểm tra lại đủ đồ rồi hẵng lấy về nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_07','V370','阮明',8,'太幸运了，非常感谢你们帮忙保管。','tài xìng yùn le， fēi cháng gǎn xiè nǐ men bāng máng bǎo guǎn。','May quá, cảm ơn mọi người nhiều vì đã giúp giữ đồ cho em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT371','S126','Báo mất điện thoại, xin khóa SIM từ xa',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V371','SIT371','P1','suon_se','chinh_thuc',NULL,'手机丢失后可致电运营商紧急挂失SIM卡，补办卡片可保留原有手机号，不会更换号码。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_01','V371','阮明',1,'您好……我手机丢了，麻烦马上帮我锁卡。','nín hǎo…… wǒ shǒu jī diū le， má fán mǎ shàng bāng wǒ suǒ kǎ。','Chào chị... điện thoại của tôi mất rồi, phiền chị khóa sim giúp tôi ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_02','V371','客服',2,'请提供手机号、实名登记姓名以及护照号吧。','qǐng tí gōng shǒu jī hào、 shí míng dēng jì xìng míng yǐ jí hù zhào hào ba。','Anh/chị cho tôi số điện thoại, tên đăng ký chính chủ và số hộ chiếu nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_03','V371','阮明',3,'信息我全部记下来了，现在报给你核对。','xìn xī wǒ quán bù jì xià lái le， xiàn zài bào gěi nǐ hé duì。','Tôi ghi hết thông tin ra rồi, giờ đọc để chị kiểm tra lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_04','V371','客服',4,'已经完成挂失锁卡，别人无法使用你的号码呢。','yǐ jīng wán chéng guà shī suǒ kǎ， bié rén wú fǎ shǐ yòng nǐ de hào mǎ ne。','Đã khóa sim xong rồi, người khác không thể dùng số của anh/chị được nữa đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_05','V371','阮明',5,'挂失之后补办新卡，原来的号码能保留吗？','guà shī zhī hòu bǔ bàn xīn kǎ， yuán lái de hào mǎ néng bǎo liú ma？','Sau khi khóa sim mà làm lại sim mới, số cũ có giữ lại được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_06','V371','客服',6,'可以，携带证件去线下营业厅就能补办同号卡。','kě yǐ， xié dài zhèng jiàn qù xiàn xià yíng yè tīng jiù néng bǔ bàn tóng hào kǎ。','Được chứ, anh/chị mang giấy tờ ra quầy giao dịch trực tiếp là làm lại sim cùng số ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_07','V371','阮明',7,'太感谢了，这样资金和账号都安全了。','tài gǎn xiè le， zhè yàng zī jīn hé zhàng hào dōu ān quán le。','Cảm ơn chị nhiều, vậy là tiền bạc và tài khoản đều an toàn rồi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好，这里有人摔倒摔伤，麻烦派救护车过来啊！','nín hǎo， zhè lǐ yǒu rén shuāi dǎo shuāi shāng， má fán pài jiù hù chē guò lái a！','Alo, ở đây có người bị té ngã bị thương, làm ơn cử xe cấp cứu đến gấp giúp với ạ!','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'别慌张，告诉我准确的详细地址和伤者情况吧。','bié huāng zhāng， gào sù wǒ zhǔn què de xiáng xì dì zhǐ hé shāng zhě qíng kuàng ba。','Anh/chị đừng hoảng, cho tôi biết địa chỉ chi tiết chính xác và tình trạng người bị thương nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'大学南门小吃街，伤者腿部出血，暂时无法站立呢。','dà xué nán mén xiǎo chī jiē， shāng zhě tuǐ bù chū xiě， zàn shí wú fǎ zhàn lì ne。','Ở phố ăn vặt cổng nam trường đại học, người bị thương chảy máu ở chân, tạm thời không đứng dậy được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'不要随意移动伤者，我们十分钟内抵达现场。','bú yào suí yì yí dòng shāng zhě， wǒ men shí fēn zhōng nèi dǐ dá xiàn chǎng。','Đừng tự ý di chuyển người bị thương, chúng tôi sẽ có mặt trong vòng mười phút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'我会留在路口等候医护人员，方便你们找到位置。','wǒ huì liú zài lù kǒu děng hòu yī hù rén yuán， fāng biàn nǐ men zhǎo dào wèi zhì。','Tôi sẽ đứng chờ ở ngã tư để đón nhân viên y tế, cho tiện tìm vị trí ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'保持电话畅通，有变化随时和我们沟通。','bǎo chí diàn huà chàng tōng， yǒu biàn huà suí shí hé wǒ men gōu tōng。','Giữ điện thoại thông suốt nhé, có gì thay đổi cứ liên hệ ngay với chúng tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'好，我在这儿等，辛苦了。','hǎo， wǒ zài zhè ér děng， xīn kǔ le。','Dạ, tôi đứng đây chờ, cảm ơn mọi người.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖，国内宿舍厨房明令禁止无人看管明火。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，公共厨房锅里起火了，我已经关掉燃气。','sù guǎn lǎo shī， gōng gòng chú fáng guō lǐ qǐ huǒ le， wǒ yǐ jīng guān diào rán qì。','Cô quản lý ơi, bếp chung bị cháy trong nồi rồi, em tắt gas rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01B','V373','宿管老师',2,'什么？！','shén me？！','Cái gì cơ?!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',3,'别靠近，有没有用水直接浇灭火源嘛？','bié kào jìn， yǒu méi yǒu yòng shuǐ zhí jiē jiāo miè huǒ yuán ma？','Đừng lại gần, em có dùng nước để dập lửa trực tiếp không vậy?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',4,'我记得不能浇水，拿锅盖盖住把火熄灭了。','wǒ jì de bù néng jiāo shuǐ， ná guō gài gài zhù bǎ huǒ xī miè le。','Em nhớ là không được dội nước, em lấy nắp nồi đậy lại là tắt lửa rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',5,'还好你处理得当，现在我带灭火器过去检查。','hái hǎo nǐ chǔ lǐ dé dàng， xiàn zài wǒ dài miè huǒ qì guò qù jiǎn chá。','May mà em xử lý đúng cách, giờ cô mang bình chữa cháy qua kiểm tra nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',6,'墙面轻微熏黑，没有蔓延到其他厨具对吧？','qiáng miàn qīng wēi xūn hēi， méi yǒu màn yán dào qí tā chú jù duì ba？','Tường chỉ bị ám khói nhẹ thôi, không lan sang dụng cụ bếp khác đúng không cô?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',7,'问题不大，后续厨房使用必须有人全程看管。','wèn tí bù dà， hòu xù chú fáng shǐ yòng bì xū yǒu rén quán chéng kān guǎn。','Không có gì đáng lo, nhưng từ giờ dùng bếp phải có người trông coi suốt thời gian nấu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',8,'我之后做饭一定留意，不会再出现这种情况。','wǒ zhī hòu zuò fàn yí dìng liú yì， bú huì zài chū xiàn zhè zhǒng qíng kuàng。','Dạ em sẽ để ý kỹ mỗi lần nấu ăn, không để xảy ra chuyện như vậy nữa ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好……路口两车剐蹭了，没有人受伤。','nín hǎo…… lù kǒu liǎng chē guǎ cèng le， méi yǒu rén shòu shāng。','Alo... ở ngã tư hai xe quẹt nhau rồi, không ai bị thương ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'双方车辆有没有挪到路边，保护好现场照片吧。','shuāng fāng chē liàng yǒu méi yǒu nuó dào lù biān， bǎo hù hǎo xiàn chǎng zhào piān ba。','Hai bên xe đã đưa vào lề đường chưa, nhớ chụp lại ảnh hiện trường cho kỹ nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'我们已经停在非机动车道，拍好了多角度现场照片呢。','wǒ men yǐ jīng tíng zài fēi jī dòng chē dào， pāi hǎo le duō jiǎo dù xiàn chǎng zhào piān ne。','Chúng tôi đã dừng xe ở làn xe thô sơ rồi, chụp ảnh hiện trường nhiều góc rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','接线员',4,'轻微剐蹭可线上快速定责，不用交警现场出警。','qīng wēi guǎ cèng kě xiàn shàng kuài sù dìng zé， bù yòng jiāo jǐng xiàn chǎng chū jǐng。','Va quẹt nhẹ thì có thể xác định trách nhiệm nhanh qua mạng, không cần cảnh sát đến hiện trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'线上处理需要上传什么证件，护照可以使用吗？','xiàn shàng chǔ lǐ xū yào shàng chuán shén me zhèng jiàn， hù zhào kě yǐ shǐ yòng ma？','Xử lý qua mạng cần tải lên giấy tờ gì ạ, dùng hộ chiếu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','接线员',6,'行驶证、驾驶证、护照拍照上传系统即可。','xíng shǐ zhèng、 jià shǐ zhèng、 hù zhào pāi zhào shàng chuán xì tǒng jí kě。','Chụp ảnh giấy đăng ký xe, bằng lái và hộ chiếu tải lên hệ thống là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'了解流程了，我马上和对方车主线上提交材料。','liǎo jiě liú chéng le， wǒ mǎ shàng hé duì fāng chē zhǔ xiàn shàng tí jiāo cái liào。','Tôi hiểu quy trình rồi, tôi sẽ cùng chủ xe kia nộp hồ sơ qua mạng ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我被网络骗子诱导转账，资金已经转出了。','nín hǎo， wǒ bèi wǎng luò piàn zi yòu dǎo zhuǎn zhàng， zī jīn yǐ jīng zhuǎn chū le。','Chào chị, tôi bị kẻ lừa đảo trên mạng dụ dỗ chuyển tiền, tiền đã chuyển đi mất rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01B','V375','反诈客服',2,'多少钱？！','duō shǎo qián？！','Bao nhiêu tiền cơ?!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',3,'立刻提供对方收款账号、转账时间和金额哈。','lì kè tí gōng duì fāng shōu kuǎn zhàng hào、 zhuǎn zhàng shí jiān hé jīn é hā。','Anh/chị cung cấp ngay số tài khoản nhận tiền của đối phương, thời gian và số tiền chuyển nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',4,'我刚转完就察觉不对劲，想要撤回转账却失败嘛。','wǒ gāng zhuǎn wán jiù chá jué bú duì jìn， xiǎng yào chè huí zhuǎn zhàng què shī bài ma。','Tôi vừa chuyển xong là phát hiện có gì không ổn, muốn hủy giao dịch mà không được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',5,'资金已进入对方账户，无法自主撤回，我紧急冻结账户。','zī jīn yǐ jìn rù duì fāng zhàng hù， wú fǎ zì zhǔ chè huí， wǒ jǐn jí dòng jié zhàng hù。','Tiền đã vào tài khoản đối phương rồi nên không thể tự hủy được, tôi sẽ khẩn cấp phong tỏa tài khoản đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',6,'冻结之后，我的钱还有机会追回吗？','dòng jié zhī hòu， wǒ de qián hái yǒu jī huì zhuī huí ma？','Sau khi phong tỏa, tiền của tôi còn cơ hội lấy lại được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',7,'会尽力拦截，后续需要你到派出所做报案笔录。','huì jìn lì lán jié， hòu xù xū yào nǐ dào pài chū suǒ zuò bào àn bǐ lù。','Chúng tôi sẽ cố gắng hết sức để chặn lại, sau đó anh/chị cần đến đồn công an làm biên bản trình báo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',8,'好，我记下地址，马上前往辖区派出所登记。','hǎo， wǒ jì xià dì zhǐ， mǎ shàng qián wǎng xiá qū pài chū suǒ dēng jì。','Dạ, tôi ghi lại địa chỉ rồi, sẽ đến đồn công an khu vực trình báo ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为损坏则需自行支付配件与工时费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'物业您好，我的房间门锁坏掉，钥匙插进去转不动。','wù yè nín hǎo， wǒ de fáng jiān mén suǒ huài diào， yào shi chā jìn qù zhuǎn bù dòng。','Chào bên quản lý, khóa cửa phòng em bị hỏng, cắm chìa vào là không xoay được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'你先在楼下门禁处等候，我带上工具十分钟到哦。','nǐ xiān zài lóu xià mén jìn chù děng hòu， wǒ dài shàng gōng jù shí fēn zhōng dào ó。','Em cứ chờ ở khu cửa an ninh dưới lầu, tôi mang dụng cụ lên trong mười phút nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'锁芯卡死了……备用钥匙也不行。','suǒ xīn kǎ sǐ le…… bèi yòng yào shi yě bù xíng。','Ruột khóa kẹt cứng rồi... chìa dự phòng cũng không được.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'大概率锁芯内部零件断裂，需要直接更换整套锁。','dà gài lǜ suǒ xīn nèi bù líng jiàn duàn liè， xū yào zhí jiē gēng huàn zhěng tào suǒ。','Khả năng cao là linh kiện bên trong ruột khóa bị gãy rồi, cần thay nguyên bộ khóa mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'更换门锁的费用是我自行承担吗？','gēng huàn mén suǒ de fèi yòng shì wǒ zì xíng chéng dān ma？','Chi phí thay khóa cửa là em tự chịu đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'自然损坏由物业免费维修，人为损坏才需要自费。','zì rán sǔn huài yóu wù yè miǎn fèi wéi xiū， rén wéi sǔn huài cái xū yào zì fèi。','Hư hỏng tự nhiên thì bên quản lý sửa miễn phí, chỉ khi hư do con người thì mới phải tự trả tiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'好，我在楼下等你，麻烦尽快过来。','hǎo， wǒ zài lóu xià děng nǐ， má fán jǐn kuài guò lái。','Dạ vâng, em chờ dưới lầu nhé, phiền anh qua sớm giúp em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，我护照遗失，想申请临时出入境通行证明。','nín hǎo， wǒ hù zhào yí shī， xiǎng shēn qǐng lín shí chū rù jìng tōng xíng zhèng míng。','Chào chị, tôi bị mất hộ chiếu, tôi muốn xin cấp giấy thông hành tạm thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'请携带派出所开具的遗失报案回执和证件照片吧。','qǐng xié dài pài chū suǒ kāi jù de yí shī bào àn huí zhí hé zhèng jiàn zhào piān ba。','Anh vui lòng mang theo biên nhận trình báo mất giấy tờ của công an và ảnh thẻ nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'我只带了回执，没提前准备一寸白底证件照嘛。','wǒ zhǐ dài le huí zhí， méi tí qián zhǔn bèi yī cùn bái dǐ zhèng jiàn zhào ma。','Tôi chỉ mang theo biên nhận thôi, chưa chuẩn bị trước ảnh thẻ nền trắng cỡ 1 inch.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03B','V377','工作人员',4,'啊，这样啊……','a， zhè yàng a……','À, vậy à...','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',5,'大厅自助拍照机可以现场拍摄，二十元一套。','dà tīng zì zhù pāi zhào jī kě yǐ xiàn chǎng pāi shè， èr shí yuán yī tào。','Ở sảnh có máy chụp ảnh tự động, chụp tại chỗ luôn, giá hai mươi tệ một bộ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',6,'拍完照片当天能拿到临时证件吗？','pāi wán zhào piān dàng tiān néng ná dào lín shí zhèng jiàn ma？','Chụp ảnh xong thì trong ngày tôi có thể nhận được giấy tờ tạm thời không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',7,'材料齐全当场办结，临时证明有效期三十天。','cái liào qí quán dāng chǎng bàn jié， lín shí zhèng míng yǒu xiào qī sān shí tiān。','Hồ sơ đầy đủ thì xử lý xong ngay tại chỗ, giấy chứng nhận tạm thời có hiệu lực ba mươi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',8,'那我先去拍照，拍完回来提交全部材料。','nà wǒ xiān qù pāi zhào， pāi wán huí lái tí jiāo quán bù cái liào。','Vậy tôi đi chụp ảnh trước, chụp xong quay lại nộp đủ hồ sơ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好……我是越南留学生，出车祸了，很严重。','nín hǎo…… wǒ shì yuè nán liú xué shēng， chū chē huò le， hěn yán zhòng。','Chào anh/chị... tôi là du học sinh Việt Nam, gặp tai nạn xe rồi, nặng lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'请冷静，告知你的姓名、学校、事故详细地点呢。','qǐng lěng jìng， gào zhī nǐ de xìng míng、 xué xiào、 shì gù xiáng xì dì diǎn ne。','Bạn bình tĩnh nhé, cho tôi biết họ tên, trường học và địa điểm xảy ra tai nạn cụ thể.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我现在在市中心主干道，交警和救护车已经抵达现场。','wǒ xiàn zài zài shì zhōng xīn zhǔ gàn dào， jiāo jǐng hé jiù hù chē yǐ jīng dǐ dá xiàn chǎng。','Tôi đang ở trục đường chính trung tâm thành phố, cảnh sát giao thông và xe cứu thương đã có mặt rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'我们会同步联系当地警方跟进，后续协助处理手续。','wǒ men huì tóng bù lián xì dāng dì jǐng fāng gēn jìn， hòu xù xié zhù chǔ lǐ shǒu xù。','Chúng tôi sẽ liên hệ đồng bộ với công an địa phương để theo dõi, hỗ trợ xử lý thủ tục tiếp theo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'后续补办证件、对接家属都能寻求大使馆帮助吧？','hòu xù bǔ bàn zhèng jiàn、 duì jiē jiā shǔ dōu néng xún qiú dà shǐ guǎn bāng zhù ba？','Về sau việc làm lại giấy tờ, liên hệ với người thân, tôi đều có thể nhờ đại sứ quán giúp đỡ chứ ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'是的，所有境外公民突发意外，使馆都会提供协助。','shì de， suǒ yǒu jìng wài gōng mín tū fā yì wài， shǐ guǎn dōu huì tí gōng xié zhù。','Đúng vậy, mọi công dân ở nước ngoài gặp sự cố bất ngờ đều sẽ được sứ quán hỗ trợ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'太感谢你们，有需要我再致电汇报情况。','tài gǎn xiè nǐ men， yǒu xū yào wǒ zài zhì diàn huì bào qíng kuàng。','Cảm ơn mọi người rất nhiều, có gì cần tôi sẽ gọi lại báo cáo tình hình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê ơi, mình muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian mà không biết trình bày sao nữa.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','CV chia làm ba phần thông tin cơ bản, khả năng ngôn ngữ, kinh nghiệm thực tế là được á.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm visa và giấy phép làm thêm hợp pháp không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Nhất định phải ghi đó, nhiều chỗ tuyển dụng chưa rõ quy định làm thêm của du học sinh đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Mình viết xong một bản nháp rồi, mà phần kinh nghiệm thực tế viết sơ sài quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho mình, mình giúp bạn sửa lại và bổ sung chi tiết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn bạn nhiều lắm, sửa xong là mình nộp hồ sơ luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào quản lý, tôi là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Hoa cho trẻ em bán thời gian.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, bạn giới thiệu sơ qua trình độ ngôn ngữ và thời gian rảnh của mình nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Tôi giao tiếp tiếng Hoa hàng ngày khá trôi chảy, tối các ngày trong tuần và cả ngày cuối tuần đều rảnh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Bạn có kinh nghiệm tiếp xúc với trẻ nhỏ không, có giỏi tương tác trong lớp học không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây tôi từng dẫn dắt các em nhỏ tuổi trong hoạt động trường học, tôi rất thích giao tiếp với trẻ con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Nhìn chung điều kiện phù hợp với yêu cầu công việc, trong ba ngày sẽ thông báo kết quả nhận việc cho bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Cảm ơn quản lý đã cho tôi cơ hội phỏng vấn, tôi sẽ kiên nhẫn chờ thông báo.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào chị, hợp đồng lao động tạm thời này tôi đã xem kỹ rồi, có một chỗ muốn xác nhận lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Bạn thấy vướng ở điều khoản nào thì cứ nói thẳng ra nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi ngày hai mươi hàng tháng trả lương, nhưng chưa nêu rõ mức phụ cấp làm thêm giờ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Chi tiết lương làm thêm giờ có ở trang phụ lục của hợp đồng, tôi đưa cho bạn kiểm tra lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký điều khoản bổ sung, mỗi bên giữ một bản hợp đồng đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng vậy, một bản lưu tại cửa hàng, một bản do bạn tự giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi đã rõ hết các điều khoản rồi, giờ tôi ký xác nhận luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，下周三我有汉语期末考，当天没法过来上班。','diàn zhǎng nín hǎo， xià zhōu sān wǒ yǒu hàn yǔ qī mò kǎo， dàng tiān méi fǎ guò lái shàng bān。','Chào cửa hàng trưởng, thứ Tư tuần sau tôi có kỳ thi cuối kỳ tiếng Hoa, hôm đó không thể đến làm được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'可以理解，学习优先，你提前说一声方便我调整排班吧。','kě yǐ lǐ jiě， xué xí yōu xiān， nǐ tí qián shuō yī shēng fāng biàn wǒ tiáo zhěng pái bān ba。','Hiểu mà, việc học ưu tiên trước, bạn báo sớm vậy để tôi tiện sắp xếp lại ca làm.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'考试全天进行，一整天都无法到岗，实在抱歉呢。','kǎo shì quán tiān jìn xíng， yī zhěng tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Kỳ thi diễn ra cả ngày, cả ngày hôm đó tôi không thể đến được, thực sự xin lỗi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'我安排其他同事顶替你的班次，不用有心理负担。','wǒ ān pái qí tā tóng shì dǐng tì nǐ de bān cì， bù yòng yǒu xīn lǐ fù dān。','Tôi sẽ sắp xếp đồng nghiệp khác trực thay ca cho bạn, đừng lo lắng gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'考完试我可以多上两天班，补上缺失的工时。','kǎo wán shì wǒ kě yǐ duō shàng liǎng tiān bān， bǔ shàng quē shī de gōng shí。','Thi xong tôi có thể làm thêm hai ngày để bù lại giờ công bị thiếu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'不用刻意补，后续正常出勤就满足月度工时要求。','bù yòng kè yì bǔ， hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù gōng shí yāo qiú。','Không cần cố tình bù đâu, sau đó bạn đi làm bình thường là đủ giờ công trong tháng rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'多谢店长体谅，我会提前完成手头工作交接。','duō xiè diàn zhǎng tǐ liàng， wǒ huì tí qián wán chéng shǒu tóu gōng zuò jiāo jiē。','Cảm ơn cửa hàng trưởng đã thông cảm, tôi sẽ bàn giao công việc trước cho gọn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào chị, tôi muốn xác nhận mức lương theo giờ của công việc bán thời gian này và cách thức trả lương.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Hai mươi hai tệ một giờ, ngày hai mươi hàng tháng chuyển khoản thẳng vào thẻ ngân hàng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ bảo hiểm xã hội hay các loại phí thủ tục nào khác không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không phải đóng bảo hiểm xã hội, lương thực nhận không bị trừ gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_05','V383','阮明',5,'只能绑定国内银行卡接收工资对吧？','zhǐ néng bǎng dìng guó nèi yín háng kǎ jiē shōu gōng zī duì ba？','Chỉ có thể liên kết thẻ ngân hàng trong nước để nhận lương thôi đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_06','V383','人事专员',6,'是的，境外银行卡无法对接公司财务系统。','shì de， jìng wài yín háng kǎ wú fǎ duì jiē gōng sī cái wù xì tǒng。','Đúng vậy, thẻ ngân hàng nước ngoài không kết nối được với hệ thống tài chính của công ty.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_07','V383','阮明',7,'明白了，我尽快办理专用工资卡。','míng bái le， wǒ jǐn kuài bàn lǐ zhuān yòng gōng zī kǎ。','Tôi hiểu rồi, tôi sẽ làm thẻ lương chuyên dụng sớm nhất có thể.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT384','S127','Hỏi về việc đóng thuế thu nhập làm thêm',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V384','SIT384','P1','twist','chinh_thuc',NULL,'国内劳务报酬设有免税额度，用人单位统一代扣个税，完税证明可用于留学生签证续办。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_01','V384','阮明',1,'您好，留学生兼职获得的收入，需要申报个人所得税吗？','nín hǎo， liú xué shēng jiān zhí huò dé de shōu rù， xū yào shēn bào gè rén suǒ dé shuì ma？','Chào chị, thu nhập du học sinh làm thêm kiếm được có phải khai thuế thu nhập cá nhân không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_02','V384','财务',2,'月度收入超过八百元，超出部分需要缴纳劳务个税哈。','yuè dù shōu rù chāo guò bā bǎi yuán， chāo chū bù fèn xū yào jiǎo nà láo wù gè shuì hā。','Thu nhập hàng tháng vượt quá tám trăm tệ thì phần vượt phải nộp thuế thu nhập lao động nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_03','V384','阮明',3,'个税会直接从当月工资里扣除，还是我自行申报嘛？','gè shuì huì zhí jiē cóng dàng yuè gōng zī lǐ kòu chú， hái shì wǒ zì xíng shēn bào ma？','Thuế thu nhập cá nhân sẽ bị trừ thẳng vào lương tháng đó, hay tôi phải tự khai vậy ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_04','V384','财务',4,'公司统一代扣代缴，工资条会标注扣税明细。','gōng sī tǒng yí dài kòu dài jiǎo， gōng zī tiáo huì biāo zhù kòu shuì míng xì。','Công ty khấu trừ và nộp thay thống nhất, phiếu lương sẽ ghi rõ chi tiết phần thuế bị trừ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_05','V384','阮明',5,'年末可以打印全年纳税记录用作签证材料吗？','nián mò kě yǐ dǎ yìn quán nián nà shuì jì lù yòng zuò qiān zhèng cái liào ma？','Cuối năm tôi có thể in bảng ghi thuế đã nộp cả năm để làm hồ sơ visa không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_06','V384','财务',6,'可以，年末我统一打印完整纳税单据交给你。','kě yǐ， nián mò wǒ tǒng yī dǎ yìn wán zhěng nà shuì dān jù jiāo gěi nǐ。','Được chứ, cuối năm tôi sẽ in đầy đủ chứng từ nộp thuế đưa cho bạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_07','V384','阮明',7,'好，相关规则我记下来，感谢细致讲解。','hǎo， xiāng guān guī zé wǒ jì xià lái， gǎn xiè xì zhì jiǎng jiě。','Vâng, quy định liên quan tôi ghi nhớ rồi, cảm ơn chị đã giải thích tỉ mỉ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT385','S128','Mở tài khoản ngân hàng riêng để nhận lương',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V385','SIT385','P1','suon_se','chinh_thuc',NULL,'外籍留学生凭护照、在校证明可办理学生储蓄卡，多数银行学生账户免除年费与小额管理费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_01','V385','阮明',1,'您好，我是在校留学生，想开一张储蓄卡专门接收兼职工资。','nín hǎo， wǒ shì zài xiào liú xué shēng， xiǎng kāi yī zhāng chǔ xù kǎ zhuān mén jiē shōu jiān zhí gōng zī。','Chào chị, tôi là du học sinh đang theo học, tôi muốn mở một thẻ tiết kiệm riêng để nhận lương làm thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_02','V385','柜员',2,'请出示你的护照、在校学生证，填写开户申请单吧。','qǐng chū shì nǐ de hù zhào、 zài xiào xué shēng zhèng， tián xiě kāi hù shēn qǐng dān ba。','Bạn vui lòng xuất trình hộ chiếu, thẻ sinh viên và điền đơn xin mở tài khoản nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_03','V385','阮明',3,'这张卡只用来收工资，平时不存放大额资金可以吗？','zhè zhāng kǎ zhǐ yòng lái shōu gōng zī， píng shí bù cún fàng dà é zī jīn kě yǐ ma？','Thẻ này chỉ dùng để nhận lương, bình thường không giữ số tiền lớn có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_04','V385','柜员',4,'完全没问题，普通一类储蓄卡支持企业对公转账呢。','wán quán méi wèn tí， pǔ tōng yī lèi chǔ xù kǎ zhī chí qǐ yè duì gōng zhuàn zhàng ne。','Hoàn toàn không vấn đề gì, thẻ tiết kiệm loại một thông thường vẫn hỗ trợ chuyển khoản từ doanh nghiệp mà.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_05','V385','阮明',5,'开户有没有年费、短信通知这类额外收费项目？','kāi hù yǒu méi yǒu nián fèi、 duǎn xìn tōng zhī zhè lèi é wài shōu fèi xiàng mù？','Mở tài khoản có phí thường niên hay phí thông báo tin nhắn gì thêm không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_06','V385','柜员',6,'学生账户免年费，免费开通资金变动短信提醒。','xué shēng zhàng hù miǎn nián fèi， miǎn fèi kāi tōng zī jīn biàn dòng duǎn xìn tí xǐng。','Tài khoản sinh viên được miễn phí thường niên, đăng ký nhắn tin báo biến động số dư cũng miễn phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_07','V385','阮明',7,'好，我现在填写单据办理开户手续。','hǎo， wǒ xiàn zài tián xiě dān jù bàn lǐ kāi hù shǒu xù。','Vâng, giờ tôi điền giấy tờ để làm thủ tục mở tài khoản.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT386','S127','Xin nghỉ việc trước thời hạn hợp đồng',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V386','SIT386','P1','twist','ban_chinh_thuc',NULL,'国内临时劳务用工规范要求员工提前三十天申请离职，企业可根据实际情况适度放宽期限。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_01','V386','阮明',1,'店长，我下学期课程增加，想申请提前半个月离职。','diàn zhǎng， wǒ xià xué qī kè chéng zēng jiā， xiǎng shēn qǐng tí qián bàn gè yuè lí zhí。','Cửa hàng trưởng ơi, học kỳ sau tôi tăng số môn học, tôi muốn xin nghỉ việc sớm nửa tháng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_02','V386','店长',2,'离职需要提前三十天书面提交申请，半个月不符合规定嘛。','lí zhí xū yào tí qián sān shí tiān shū miàn tí jiāo shēn qǐng， bàn gè yuè bù fú hé guī dìng ma。','Nghỉ việc phải nộp đơn bằng văn bản trước ba mươi ngày, nửa tháng thì không đúng quy định đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_03','V386','阮明',3,'课程安排实在冲突，没有多余时间兼顾兼职工作。','kè chéng ān pái shí zài chōng tū， méi yǒu duō yú shí jiān jiān gù jiān zhí gōng zuò。','Lịch học của tôi thực sự bị trùng, không còn thời gian dư để lo công việc làm thêm nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_04','V386','店长',4,'我理解你的难处，最多协调缩短到二十天离职周期。','wǒ lǐ jiě nǐ de nán chǔ， zuì duō xié tiáo suō duǎn dào èr shí tiān lí zhí zhōu qī。','Tôi hiểu khó khăn của bạn, tối đa tôi có thể thu xếp rút ngắn xuống hai mươi ngày trước khi nghỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_05','V386','阮明',5,'二十天我可以接受，这段时间我做好工作交接。','èr shí tiān wǒ kě yǐ jiē shòu， zhè duàn shí jiān wǒ zuò hǎo gōng zuò jiāo jiē。','Hai mươi ngày thì tôi chấp nhận được, khoảng thời gian đó tôi sẽ bàn giao công việc cho tốt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_06','V386','店长',6,'没问题，今天填写离职申请表交给人事存档。','méi wèn tí， jīn tiān tián xiě lí zhí shēn qǐng biǎo jiāo gěi rén shì cún dàng。','Được, hôm nay điền đơn xin nghỉ việc rồi nộp cho nhân sự lưu hồ sơ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_07','V386','阮明',7,'麻烦店长帮忙审批，这段时间辛苦大家照顾我。','má fán diàn zhǎng bāng máng shěn pī， zhè duàn shí jiān xīn kǔ dà jiā zhào gù wǒ。','Phiền cửa hàng trưởng giúp duyệt đơn, thời gian này mong mọi người chiếu cố giúp tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT387','S127','Hỏi quy định giờ làm tối đa cho sinh viên quốc tế',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V387','SIT387','P1','suon_se','chinh_thuc',NULL,'中国法律明确规定外籍留学生务工时长，超时务工将影响签证续签，学校会定期核查兼职情况。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_01','V387','阮明',1,'老师您好，我想咨询留学生校内、校外兼职时长限制。','lǎo shī nín hǎo， wǒ xiǎng zī xún liú xué shēng xiào nèi、 xiào wài jiān zhí shí cháng xiàn zhì。','Chào cô, em muốn hỏi về quy định giới hạn thời gian làm thêm trong và ngoài trường dành cho sinh viên quốc tế ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_02','V387','国际处老师',2,'学期内每周打工总时长不能超过二十小时哦。','xué qī nèi měi zhōu dǎ gōng zǒng shí cháng bù néng chāo guò èr shí xiǎo shí ó。','Trong học kỳ, tổng thời gian làm thêm mỗi tuần không được vượt quá hai mươi tiếng.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_03','V387','阮明',3,'寒暑假期间，时长限制会适当放宽一些吗？','hán shǔ jià qī jiān， shí cháng xiàn zhì huì shì dàng fàng kuān yī xiē ma？','Vậy trong kỳ nghỉ hè, nghỉ đông thì giới hạn đó có được nới lỏng hơn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_04','V387','国际处老师',4,'假期每周最多四十小时，超出属于违规务工呢。','jià qī měi zhōu zuì duō sì shí xiǎo shí， chāo chū shǔ yú wéi guī wù gōng ne。','Vào kỳ nghỉ, tối đa là bốn mươi tiếng một tuần, vượt quá là vi phạm quy định làm thêm đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_05','V387','阮明',5,'超时打工会不会影响我的签证续办审核？','chāo shí dǎ gōng huì bú huì yǐng xiǎng wǒ de qiān zhèng xù bàn shěn hé？','Nếu làm thêm quá giờ thì có ảnh hưởng đến việc xét gia hạn visa của em không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_06','V387','国际处老师',6,'会有影响，出入境管理局会核查务工时长记录。','huì yǒu yǐng xiǎng， chū rù jìng guǎn lǐ jú huì hé chá wù gōng shí cháng jì lù。','Có ảnh hưởng chứ, cục quản lý xuất nhập cảnh sẽ kiểm tra hồ sơ thời gian làm thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_07','V387','阮明',7,'我清楚规定了，一定会严格控制上班时长。','wǒ qīng chǔ guī dìng le， yí dìng huì yán gé kòng zhì shàng bān shí cháng。','Em hiểu rõ quy định rồi ạ, em nhất định sẽ kiểm soát chặt thời gian làm việc của mình.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT388','S127','Trao đổi ca làm việc với đồng nghiệp',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V388','SIT388','P1','twist','tuy_y',NULL,'兼职员工私下换班必须告知主管登记，避免岗位无人值守，产生运营问题。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_01','V388','阮明',1,'小秦，我周四下午有汉语测验，能和你互换班次吗？','xiǎo qín， wǒ zhōu sì xià wǔ yǒu hàn yǔ cè yàn， néng hé nǐ hù huàn bān cì ma？','Tiểu Tần ơi, chiều thứ Năm này tớ có bài kiểm tra tiếng Trung, cậu đổi ca với tớ được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_02','V388','小秦',2,'我周四全天有社团活动，那天也没办法上班嘛。','wǒ zhōu sì quán tiān yǒu shè tuán huó dòng， nà tiān yě méi bàn fǎ shàng bān ma。','Thứ Năm cả ngày tớ có hoạt động câu lạc bộ rồi, hôm đó tớ cũng không đi làm được đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_03','V388','阮明',3,'原来是这样，那周五的班次你方便和我调换不？','yuán lái shì zhè yàng， nà zhōu wǔ de bān cì nǐ fāng biàn hé wǒ diào huàn bù？','Ra vậy à, thế ca thứ Sáu cậu có tiện đổi với tớ không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_04','V388','小秦',4,'周五我空闲，我们调换之后跟店长报备一下就行。','zhōu wǔ wǒ kòng xián， wǒ men diào huàn zhī hòu gēn diàn zhǎng bào bèi yī xià jiù xíng。','Thứ Sáu tớ rảnh, đổi xong tụi mình báo lại cho quản lý một tiếng là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_05','V388','阮明',5,'太好了，调换班次需要填写纸质调换申请单吗？','tài hǎo le， diào huàn bān cì xū yào tián xiě zhǐ zhì diào huàn shēn qǐng dān ma？','Tuyệt quá, đổi ca thì có cần điền đơn xin đổi ca bản giấy không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_06','V388','小秦',6,'不用，微信跟店长说一声登记备案就可以。','bù yòng， wēi xìn gēn diàn zhǎng shuō yī shēng dēng jì bèi àn jiù kě yǐ。','Không cần đâu, chỉ cần nhắn Wechat báo quản lý ghi nhận lại là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_07','V388','阮明',7,'太谢谢你，解决了我的难题。','tài xiè xiè nǐ， jiě jué le wǒ de nán tí。','Cảm ơn cậu nhiều nha, giúp tớ gỡ được rắc rối luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT389','S127','Báo cáo sự cố trong ca làm với quản lý',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V389','SIT389','P1','suon_se','ban_chinh_thuc',NULL,'服务行业工作中出现客户突发状况，员工第一时间上报主管并留存记录，是标准工作流程。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_01','V389','阮明',1,'主管，刚刚上课出现突发情况，我来跟您汇报一下。','zhǔ guǎn， gāng gāng shàng kè chū xiàn tū fā qíng kuàng， wǒ lái gēn nín huì bào yī xià。','Quản lý ơi, vừa nãy trong lúc dạy có chuyện đột xuất, tôi báo cáo lại một chút ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_02','V389','主管',2,'别着急，慢慢说，课堂上发生什么意外了吧？','bié zháo jí， màn màn shuō， kè táng shàng fā shēng shén me yì wài le ba？','Đừng gấp, cứ từ từ nói, trong lớp xảy ra chuyện gì vậy?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_03','V389','阮明',3,'一名小朋友身体不舒服，家长临时赶来把孩子接走了呢。','yī míng xiǎo péng yǒu shēn tǐ bù shū fú， jiā zhǎng lín shí gǎn lái bǎ hái zi jiē zǒu le ne。','Có một em nhỏ không khỏe trong người, phụ huynh vội đến đón con về ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_04','V389','主管',4,'孩子有没有出现发烧、呕吐这类严重不适症状？','hái zi yǒu méi yǒu chū xiàn fā shāo、 ǒu tù zhè lèi yán zhòng bù shì zhèng zhuàng？','Bé có bị sốt hay nôn ói, kiểu triệu chứng nghiêm trọng nào không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_05','V389','阮明',5,'只是轻微头晕，休息片刻就好转，家长已经带离校区。','zhǐ shì qīng wēi tóu yūn， xiū xī piàn kè jiù hǎo zhuǎn， jiā zhǎng yǐ jīng dài lí xiào qū。','Chỉ hơi chóng mặt thôi ạ, nghỉ một lát là đỡ, phụ huynh đã đưa bé rời khỏi trường rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_06','V389','主管',6,'记录好学生信息，后续跟进询问孩子身体状况。','jì lù hào xué shēng xìn xī， hòu xù gēn jìn xún wèn hái zi shēn tǐ zhuàng kuàng。','Ghi lại đầy đủ thông tin học sinh, sau đó theo dõi hỏi thăm tình hình sức khỏe của bé nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_07','V389','阮明',7,'好，我马上整理情况记录，同步发给您查看。','hǎo， wǒ mǎ shàng zhěng lǐ qíng kuàng jì lù， tóng bù fā gěi nín chá kàn。','Vâng ạ, tôi sẽ tổng hợp lại tình hình và gửi cho quản lý xem ngay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT390','S127','Xin thư giới thiệu từ nơi thực tập',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V390','SIT390','P1','twist','chinh_thuc',NULL,'企业开具实习推荐信加盖公章需行政部门审核，私人手写无公章的推荐信不具备官方证明效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_01','V390','阮明',1,'领导您好，我的实习周期即将结束，想申请一份实习推荐信。','lǐng dǎo nín hǎo， wǒ de shí xí zhōu qī jí jiāng jié shù， xiǎng shēn qǐng yī fèn shí xí tuī jiàn xìn。','Chào anh/chị, kỳ thực tập của em sắp kết thúc rồi, em muốn xin một thư giới thiệu thực tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_02','V390','负责人',2,'可以，推荐信用于升学还是后续求职使用呢？','kě yǐ， tuī jiàn xìn yòng yú shēng xué hái shì hòu xù qiú zhí shǐ yòng ne？','Được thôi, thư giới thiệu dùng để học lên hay để xin việc sau này vậy?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_03','V390','阮明',3,'用于境外深造申请，需要加盖公司官方公章对吧？','yòng yú jìng wài shēn zào shēn qǐng， xū yào jiā gài gōng sī guān fāng gōng zhāng duì ba？','Dùng để nộp hồ sơ du học nước ngoài ạ, cần đóng dấu chính thức của công ty đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_04','V390','负责人',4,'推荐信内容我可以撰写，但公章需要行政部门统一审批嘛。','tuī jiàn xìn nèi róng wǒ kě yǐ zhuàn xiě， dàn gōng zhāng xū yào xíng zhèng bù mén tǒng yī shěn pī ma。','Nội dung thư thì mình có thể soạn, nhưng con dấu cần bộ phận hành chính duyệt thống nhất.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_05','V390','阮明',5,'审批流程大概需要几天，我下周就要提交申请材料。','shěn pī liú chéng dà gài xū yào jǐ tiān， wǒ xià zhōu jiù yào tí jiāo shēn qǐng cái liào。','Quy trình duyệt mất khoảng mấy ngày ạ, tuần sau em phải nộp hồ sơ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_06','V390','负责人',6,'三天内完成审批盖章，到时候我通知你来领取。','sān tiān nèi wán chéng shěn pī gài zhāng， dào shí hòu wǒ tōng zhī nǐ lái lǐng qǔ。','Trong ba ngày là xong khâu duyệt và đóng dấu, lúc đó tôi báo em đến nhận nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_07','V390','阮明',7,'麻烦领导费心帮忙，非常感谢。','má fán lǐng dǎo fèi xīn bāng máng， fēi cháng gǎn xiè。','Phiền anh/chị giúp đỡ em, em cảm ơn nhiều lắm ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT391','S129','Xin cấp bảng điểm chính thức',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V391','SIT391','P1','twist','ban_chinh_thuc',NULL,'留学生用于出境、升学的成绩单必须由学校教务盖章，电子版文件不具备官方效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_01','V391','阮明',1,'老师您好，我毕业需要正式成绩单，想申请打印几份。','lǎo shī nín hǎo， wǒ bì yè xū yào zhèng shì chéng jì dān， xiǎng shēn qǐng dǎ yìn jǐ fèn。','Chào cô, em sắp tốt nghiệp cần bảng điểm chính thức, em muốn xin in mấy bản ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_02','V391','教务老师',2,'没问题，填好这份申请表，带上你的护照原件哦。','méi wèn tí， tián hǎo zhè fèn shēn qǐng biǎo， dài shàng nǐ de hù zhào yuán jiàn ó。','Được, điền vào đơn này rồi mang theo hộ chiếu bản gốc nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_03','V391','阮明',3,'申请表我已经填完了，但是护照昨天拿去办签证了嘛。','shēn qǐng biǎo wǒ yǐ jīng tián wán le， dàn shì hù zhào zuó tiān ná qù bàn qiān zhèng le ma。','Đơn em điền xong rồi ạ, nhưng hộ chiếu hôm qua em mang đi làm visa mất rồi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_04','V391','教务老师',4,'没有证件不能办理，你改天带护照再来登记吧。','méi yǒu zhèng jiàn bù néng bàn lǐ， nǐ gǎi tiān dài hù zhào zài lái dēng jì ba。','Không có giấy tờ thì không làm được đâu, em mang hộ chiếu qua đăng ký lại hôm khác nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_05','V391','阮明',5,'那我明天一早把护照带过来，当天就能拿到成绩单吗？','nà wǒ míng tiān yī zǎo bǎ hù zhào dài guò lái， dàng tiān jiù néng ná dào chéng jì dān ma？','Vậy sáng mai em mang hộ chiếu qua sớm, hôm đó có lấy được bảng điểm luôn không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_06','V391','教务老师',6,'纸质成绩单当场打印盖章，不用额外等候。','zhǐ zhì chéng jì dān dāng chǎng dǎ yìn gài zhāng， bù yòng é wài děng hòu。','Bảng điểm giấy sẽ in và đóng dấu ngay tại chỗ, không cần chờ thêm đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_07','V391','阮明',7,'好，辛苦老师，我明天准时过来办理。','hǎo， xīn kǔ lǎo shī， wǒ míng tiān zhǔn shí guò lái bàn lǐ。','Vâng ạ, cảm ơn cô, mai em qua đúng giờ để làm thủ tục.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT392','S129','Xin cấp bằng tốt nghiệp và công chứng',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V392','SIT392','P1','suon_se','chinh_thuc',NULL,'外国留学生回国使用国内学历证件，必须办理涉外公证，境外机构才认可学历效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_01','V392','阮明',1,'您好，我课程全部修完，来领取毕业证并申请校内公证。','nín hǎo， wǒ kè chéng quán bù xiū wán， lái lǐng qǔ bì yè zhèng bìng shēn qǐng xiào nèi gōng zhèng。','Chào anh/chị, em đã học xong hết các môn rồi, em đến nhận bằng tốt nghiệp và xin công chứng trong trường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_02','V392','工作人员',2,'先核对你的全部考勤和缴费记录，没有欠费才能办理呢。','xiān hé duì nǐ de quán bù kǎo qín hé jiǎo fèi jì lù， méi yǒu qiàn fèi cái néng bàn lǐ ne。','Trước tiên kiểm tra lại toàn bộ điểm danh và các khoản đóng phí của em, không nợ gì mới làm được nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_03','V392','阮明',3,'学费、住宿费我都按时交清，没有任何欠费记录。','xué fèi、 zhù sù fèi wǒ dōu àn shí jiāo qīng， méi yǒu rèn hé qiàn fèi jì lù。','Học phí, phí ký túc xá em đều đóng đúng hạn hết rồi, không có khoản nào nợ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_04','V392','工作人员',4,'毕业证当场发放，公证文件三个工作日后可取。','bì yè zhèng dāng chǎng fā fàng， gōng zhèng wén jiàn sān gè gōng zuò rì hòu kě qǔ。','Bằng tốt nghiệp phát ngay tại chỗ, còn giấy công chứng thì ba ngày làm việc sau lấy được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_05','V392','阮明',5,'公证文件可以多打印两份，方便我带回越南使用吧？','gōng zhèng wén jiàn kě yǐ duō dǎ yìn liǎng fèn， fāng biàn wǒ dài huí yuè nán shǐ yòng ba？','Giấy công chứng em xin in thêm hai bản nữa được không ạ, để tiện mang về Việt Nam dùng?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_06','V392','工作人员',6,'没问题，每份公证只收取基础工本费。','méi wèn tí， měi fèn gōng zhèng zhǐ shōu qǔ jī chǔ gōng běn fèi。','Được chứ, mỗi bản công chứng chỉ thu phí công cơ bản thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_07','V392','阮明',7,'麻烦您帮忙办理，这份材料对我后续深造很重要。','má fán nín bāng máng bàn lǐ， zhè fèn cái liào duì wǒ hòu xù shēn zào hěn zhòng yào。','Phiền anh/chị giúp em làm giấy tờ, tài liệu này rất quan trọng cho việc học tiếp của em sau này.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT393','S130','Làm thủ tục trả phòng ký túc xá',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V393','SIT393','P1','twist','ban_chinh_thuc',NULL,'高校宿舍退房会逐一清点室内设施，人为造成大面积破损，学校会从住宿押金中扣除维修费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_01','V393','阮明',1,'阿姨，我今天来办宿舍退房，麻烦检查一下房间。','ā yí， wǒ jīn tiān lái bàn sù shè tuì fáng， má fán jiǎn chá yī xià fáng jiān。','Cô ơi, hôm nay con đến làm thủ tục trả phòng ký túc xá, phiền cô kiểm tra phòng giúp con ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_02','V393','宿管阿姨',2,'我看看桌椅、墙面和电器，破损会扣押金哈。','wǒ kàn kàn zhuō yǐ、 qiáng miàn hé diàn qì， pò sǔn huì kòu yā jīn hā。','Để cô xem bàn ghế, tường và đồ điện, hư hỏng gì là trừ tiền cọc đó nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_03','V393','阮明',3,'我平时很爱惜房间，只有书桌边角有一点小划痕嘛。','wǒ píng shí hěn ài xī fáng jiān， zhǐ yǒu shū zhuō biān jiǎo yǒu yì diǎn xiǎo huà hén ma。','Con vẫn luôn giữ gìn phòng cẩn thận lắm ạ, chỉ có góc bàn học bị trầy nhẹ một chút thôi.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_04','V393','宿管阿姨',4,'轻微划痕不影响，不需要扣除押金。','qīng wēi huà hén bù yǐng xiǎng， bù xū yào kòu chú yā jīn。','Trầy nhẹ thì không sao, không cần trừ tiền cọc đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_05','V393','阮明',5,'那我的行李可以暂时放在楼道等同学帮忙搬运吗？','nà wǒ de xíng lǐ kě yǐ zàn shí fàng zài lóu dào děng tóng xué bāng máng bān yùn ma？','Vậy hành lý của con để tạm ở hành lang chờ bạn đến phụ khiêng có được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_06','V393','宿管阿姨',6,'短时间放置没问题，不要堵塞消防通道就行。','duǎn shí jiān fàng zhì méi wèn tí， bú yào dǔ sè xiāo fáng tōng dào jiù xíng。','Để tạm một lát thì không sao, chỉ cần đừng chắn lối thoát hiểm là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_07','V393','阮明',7,'太感谢阿姨通融，我收拾完立刻离开宿舍楼。','tài gǎn xiè ā yí tōng róng， wǒ shōu shí wán lì kè lí kāi sù shè lóu。','Con cảm ơn cô đã thông cảm nhiều lắm, con dọn xong là rời khỏi tòa nhà ký túc xá ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT394','S130','Thanh lý hợp đồng thuê nhà ngoài',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V394','SIT394','P1','suon_se','ban_chinh_thuc',NULL,'提前退租需和房东当面清点房屋物品，确认无损坏、无欠费后，房东才会全额返还租房押金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_01','V394','阮明',1,'房东您好，我马上毕业回国，想提前终止租房合同。','fáng dōng nín hǎo， wǒ mǎ shàng bì yè huí guó， xiǎng tí qián zhōng zhǐ zū fáng hé tóng。','Chào chủ nhà, em sắp tốt nghiệp về nước rồi, em muốn xin chấm dứt hợp đồng thuê nhà sớm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_02','V394','房东',2,'可以，我们按合同约定清点家具，结清水电杂费吧。','kě yǐ， wǒ men àn hé tóng yuē dìng qīng diǎn jiā jù， jié qīng shuǐ diàn zá fèi ba。','Được thôi, mình kiểm kê đồ đạc theo hợp đồng đã thỏa thuận, rồi thanh toán hết tiền điện nước nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_03','V394','阮明',3,'所有家具完好无损，水电费我已经全部缴清了呢。','suǒ yǒu jiā jù wán hǎo wú sǔn， shuǐ diàn fèi wǒ yǐ jīng quán bù jiǎo qīng le ne。','Đồ đạc còn nguyên vẹn hết ạ, tiền điện nước em cũng đã đóng đầy đủ rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_04','V394','房东',4,'墙面没有污渍、家电能正常使用，我全额退还押金。','qiáng miàn méi yǒu wū zì、 jiā diàn néng zhèng cháng shǐ yòng， wǒ quán é tuì huán yā jīn。','Tường không có vết bẩn, đồ điện dùng bình thường, vậy tôi trả lại toàn bộ tiền cọc cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_05','V394','阮明',5,'押金可以直接转账到我的银行卡里对吗？','yā jīn kě yǐ zhí jiē zhuǎn zhàng dào wǒ de yín háng kǎ lǐ duì ma？','Tiền cọc có thể chuyển thẳng vào thẻ ngân hàng của em được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_06','V394','房东',6,'没问题，验收完房屋当天就给你转账。','méi wèn tí， yàn shōu wán fáng wū dàng tiān jiù gěi nǐ zhuǎn zhàng。','Không vấn đề gì, kiểm tra nhà xong hôm đó là chuyển khoản cho em luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_07','V394','阮明',7,'辛苦您抽空过来验房，麻烦您多费心。','xīn kǔ nín chōu kòng guò lái yàn fáng， má fán nín duō fèi xīn。','Cảm ơn chú/cô đã dành thời gian đến kiểm tra nhà, phiền chú/cô nhiều rồi ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT395','S119','Đóng tài khoản ngân hàng trước khi về nước',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V395','SIT395','P1','twist','chinh_thuc',NULL,'外籍人员长期离境建议注销国内闲置银行卡，避免长期休眠账户产生管理风险。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_01','V395','阮明',1,'您好，我即将回国，想要注销这张留学生储蓄卡。','nín hǎo， wǒ jí jiāng huí guó， xiǎng yào zhù xiāo zhè zhāng liú xué shēng chǔ xù kǎ。','Chào anh/chị, em sắp về nước rồi, em muốn hủy thẻ tiết kiệm dành cho du học sinh này ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_02','V395','柜员',2,'先把卡里余额全部取出，再填写销户申请单哦。','xiān bǎ kǎ lǐ yú é quán bù qǔ chū， zài tián xiě xiāo hù shēn qǐng dān ó。','Trước tiên rút hết số dư trong thẻ ra, rồi điền đơn xin hủy tài khoản nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_03','V395','阮明',3,'我刚刚查询，账户还有十几块零钱没法线上转出嘛。','wǒ gāng gāng chá xún， zhàng hù hái yǒu shí jǐ kuài líng qián méi fǎ xiàn shàng zhuǎn chū ma。','Em vừa kiểm tra thì tài khoản còn hơn chục đồng lẻ không chuyển online được ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_04','V395','柜员',4,'小额现金柜台可以直接取出，不影响销户流程。','xiǎo é xiàn jīn guì tái kě yǐ zhí jiē qǔ chū， bù yǐng xiǎng xiāo hù liú chéng。','Khoản tiền lẻ nhỏ đó có thể rút trực tiếp tại quầy, không ảnh hưởng đến việc hủy tài khoản đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_05','V395','阮明',5,'销户完成后，银行会开具销户证明给我吗？','xiāo hù wán chéng hòu， yín háng huì kāi jù xiāo hù zhèng míng gěi wǒ ma？','Sau khi hủy xong, ngân hàng có cấp giấy xác nhận hủy tài khoản cho em không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_06','V395','柜员',6,'可以，纸质销户回执会加盖公章交给你留存。','kě yǐ， zhǐ zhì xiāo hù huí zhí huì jiā gài gōng zhāng jiāo gěi nǐ liú cún。','Có chứ, biên nhận hủy tài khoản bản giấy sẽ được đóng dấu và giao cho em giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_07','V395','阮明',7,'好，我现在办理取现，再完成销户手续。','hǎo， wǒ xiàn zài bàn lǐ qǔ xiàn， zài wán chéng xiāo hù shǒu xù。','Vâng ạ, giờ em làm thủ tục rút tiền mặt, rồi hoàn tất việc hủy tài khoản luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT396','S131','Hủy SIM điện thoại trước khi về nước',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V396','SIT396','P1','suon_se','ban_chinh_thuc',NULL,'留学生离境前务必注销手机卡，若长期欠费停机，会影响本人后续再次办理国内通信业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_01','V396','阮明',1,'你好，我毕业要回国，打算注销名下这张手机电话卡。','nǐ hǎo， wǒ bì yè yào huí guó， dǎ suàn zhù xiāo míng xià zhè zhāng shǒu jī diàn huà kǎ。','Chào anh/chị, em tốt nghiệp phải về nước rồi, em định hủy sim điện thoại đứng tên em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_02','V396','客服',2,'出示办卡时的护照，我先查询套餐是否有未结清费用呢。','chū shì bàn kǎ shí de hù zhào， wǒ xiān chá xún tào cān shì fǒu yǒu wèi jié qīng fèi yòng ne。','Cho tôi xem hộ chiếu lúc em đăng ký sim, tôi kiểm tra xem gói cước có khoản nào chưa thanh toán không nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_03','V396','阮明',3,'上个月话费已经缴完，没有欠费、没有合约捆绑。','shàng gè yuè huà fèi yǐ jīng jiǎo wán， méi yǒu qiàn fèi、 méi yǒu hé yuē kǔn bǎng。','Cước tháng trước em đóng hết rồi ạ, không nợ gì, cũng không ràng buộc hợp đồng gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_04','V396','客服',4,'那现在就能当场注销，卡里剩余话费可以现金退还。','nà xiàn zài jiù néng dāng chǎng zhù xiāo， kǎ lǐ shèng yú huà fèi kě yǐ xiàn jīn tuì huán。','Vậy giờ hủy được ngay tại chỗ, số tiền cước còn dư trong thẻ có thể hoàn lại bằng tiền mặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_05','V396','阮明',5,'注销之后，会不会收到后续短信或者扣费通知吧？','zhù xiāo zhī hòu， huì bú huì shōu dào hòu xù duǎn xìn huò zhě kòu fèi tōng zhī ba？','Sau khi hủy rồi, em có bị nhận tin nhắn hay thông báo trừ tiền gì nữa không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_06','V396','客服',6,'不会，销户后号码直接回收，和你不再有关联。','bú huì， xiāo hù hòu hào mǎ zhí jiē huí shōu， hé nǐ bù zài yǒu guān lián。','Không đâu, sau khi hủy thì số điện thoại được thu hồi luôn, không còn liên quan gì đến em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_07','V396','阮明',7,'那就麻烦你帮我办理注销业务了。','nà jiù má fán nǐ bāng wǒ bàn lǐ zhù xiāo yè wù le。','Vậy phiền anh/chị giúp em làm thủ tục hủy sim luôn ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT397','S119','Xin hoàn lại tiền đặt cọc phòng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V397','SIT397','P1','twist','ban_chinh_thuc',NULL,'学校各类押金退款均留存电子档案，票据丢失可凭本人有效证件核对记录办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_01','V397','阮明',1,'老师您好，我毕业离校，申请退还宿舍住宿押金。','lǎo shī nín hǎo， wǒ bì yè lí xiào， shēn qǐng tuì huán sù shè zhù sù yā jīn。','Chào thầy/cô, em đã tốt nghiệp và rời trường, em muốn xin hoàn lại tiền đặt cọc ký túc xá ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_02','V397','财务老师',2,'带好退房回执和缴费票据，我登记后走退款流程哈。','dài hǎo tuì fáng huí zhí hé jiǎo fèi piào jù， wǒ dēng jì hòu zǒu tuì kuǎn liú chéng hā。','Em mang theo biên nhận trả phòng và hóa đơn đóng tiền nhé, để tôi đăng ký rồi làm thủ tục hoàn tiền cho.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_03','V397','阮明',3,'退房回执我带来了，但是押金票据不小心弄丢了嘛。','tuì fáng huí zhí wǒ dài lái le， dàn shì yā jīn piào jù bù xiǎo xīn nòng diū le ma。','Biên nhận trả phòng thì em mang theo rồi, nhưng hóa đơn tiền cọc em lỡ làm mất mất rồi ạ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_04','V397','财务老师',4,'没关系，系统有缴费记录，凭护照也能核对退款。','méi guān xì， xì tǒng yǒu jiǎo fèi jì lù， píng hù zhào yě néng hé duì tuì kuǎn。','Không sao, hệ thống có lưu lại thông tin đóng tiền, dùng hộ chiếu cũng có thể đối chiếu để hoàn tiền được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_05','V397','阮明',5,'押金是原路退回银行卡，还是现场领取现金？','yā jīn shì yuán lù tuì huí yín háng kǎ， hái shì xiàn chǎng lǐng qǔ xiàn jīn？','Vậy tiền cọc sẽ được chuyển thẳng về thẻ ngân hàng, hay là em nhận tiền mặt trực tiếp ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_06','V397','财务老师',6,'统一银行卡转账，三个工作日内到账。','tǒng yī yín háng kǎ zhuǎn zhàng， sān gè gōng zuò rì nèi dào zhàng。','Chuyển khoản qua thẻ ngân hàng hết, khoảng ba ngày làm việc là tiền về tới nơi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_07','V397','阮明',7,'太感谢老师帮忙核对，省去我不少麻烦。','tài gǎn xiè lǎo shī bāng máng hé duì， shěng qù wǒ bù shǎo má fán。','Em cảm ơn thầy/cô nhiều lắm ạ, nhờ thầy/cô kiểm tra giúp mà em đỡ mất công nhiều.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT398','S132','Làm thủ tục ra sân bay về nước',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V398','SIT398','P1','suon_se','ban_chinh_thuc',NULL,'国内国际航班充电宝只能随身携带，严禁放入托运行李，超规行李需要额外支付运费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_01','V398','阮明',1,'您好，我乘坐飞往越南的航班，办理行李托运和值机。','nín hǎo， wǒ chéng zuò fēi wǎng yuè nán de háng bān， bàn lǐ xíng lǐ tuō yùn hé zhí jī。','Chào anh/chị, tôi bay chuyến về Việt Nam, tôi muốn làm thủ tục ký gửi hành lý và check-in ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_02','V398','工作人员',2,'出示你的护照和电子机票，行李不要超重哦。','chū shì nǐ de hù zhào hé diàn zi jī piào， xíng lǐ bú yào chāo zhòng ó。','Anh/chị cho tôi xem hộ chiếu với vé điện tử nhé, hành lý đừng để quá cân đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_03','V398','阮明',3,'两件行李箱总重量二十公斤，符合免费托运标准呢。','liǎng jiàn xíng lǐ xiāng zǒng zhòng liàng èr shí gōng jīn， fú hé miǎn fèi tuō yùn biāo zhǔn ne。','Hai vali của tôi tổng cộng nặng hai mươi ký, vừa đúng mức ký gửi miễn phí đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_04','V398','工作人员',4,'行李贴好标签，登机口在二楼，提前一小时等候登机。','xíng lǐ tiē hǎo biāo qiān， dēng jī kǒu zài èr lóu， tí qián yī xiǎo shí děng hòu dēng jī。','Hành lý đã dán nhãn xong rồi, cổng lên máy bay ở tầng hai, anh/chị ra sớm một tiếng để chờ lên máy bay nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_05','V398','阮明',5,'随身包里有电子产品，过安检需要单独拿出来对吧？','suí shēn bāo lǐ yǒu diàn zi chǎn pǐn， guò ān jiǎn xū yào dān dú ná chū lái duì ba？','Trong túi xách tay của tôi có đồ điện tử, qua an ninh phải lấy riêng ra đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_06','V398','工作人员',6,'没错，电脑、充电宝都要单独过机检查。','méi cuò， diàn nǎo、 chōng diàn bǎo dōu yào dān dú guò jī jiǎn chá。','Đúng vậy, laptop với sạc dự phòng đều phải lấy ra soi riêng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_07','V398','阮明',7,'清楚流程了，辛苦你指引我办理。','qīng chǔ liú chéng le， xīn kǔ nǐ zhǐ yǐn wǒ bàn lǐ。','Tôi hiểu quy trình rồi, cảm ơn anh/chị đã hướng dẫn tận tình cho tôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT399','S129','Xin giấy xác nhận đã hoàn thành khóa học',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V399','SIT399','P1','suon_se','ban_chinh_thuc',NULL,'海外院校会要求留学生提供课程完成证明，以此核实学生完整完成在校学习。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_01','V399','阮明',1,'老师，我回国升学需要课程完成证明，麻烦帮忙开具。','lǎo shī， wǒ huí guó shēng xué xū yào kè chéng wán chéng zhèng míng， má fán bāng máng kāi jù。','Thầy/cô ơi, em về nước học tiếp lên nên cần giấy xác nhận hoàn thành khóa học, phiền thầy/cô cấp giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_02','V399','教务老师',2,'所有课程、论文全部合格，才能出具这份官方证明吧。','suǒ yǒu kè chéng、 lùn wén quán bù hé gé， cái néng chū jù zhè fèn guān fāng zhèng míng ba。','Phải hoàn thành hết các môn học và bảo vệ luận văn đạt yêu cầu thì mới cấp được giấy xác nhận chính thức này nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_03','V399','阮明',3,'我的全部课程考核通过，论文也顺利答辩完成了呢。','wǒ de quán bù kè chéng kǎo hé tōng guò， lùn wén yě shùn lì dá biàn wán chéng le ne。','Em đã hoàn thành hết tất cả các môn học, luận văn cũng đã bảo vệ xong xuôi rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_04','V399','教务老师',4,'我现在打印两份，加盖学院公章交给你带走。','wǒ xiàn zài dǎ yìn liǎng fèn， jiā gài xué yuàn gōng zhāng jiāo gěi nǐ dài zǒu。','Vậy để tôi in luôn hai bản, đóng dấu của khoa rồi đưa em mang về.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_05','V399','阮明',5,'证明上面会标注我的在校学习时长和专业信息吗？','zhèng míng shàng miàn huì biāo zhù wǒ de zài xiào xué xí shí cháng hé zhuān yè xìn xī ma？','Giấy xác nhận có ghi rõ thời gian em học ở trường và thông tin chuyên ngành không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_06','V399','教务老师',6,'全部信息完整标注，国外院校完全认可。','quán bù xìn xī wán zhěng biāo zhù， guó wài yuàn xiào wán quán rèn kě。','Đầy đủ hết mọi thông tin, các trường nước ngoài đều công nhận giấy này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_07','V399','阮明',7,'太感谢老师，这份证明对我的深造至关重要。','tài gǎn xiè lǎo shī， zhè fèn zhèng míng duì wǒ de shēn zào zhì guān zhòng yào。','Em cảm ơn thầy/cô nhiều lắm, giấy xác nhận này rất quan trọng với việc học tiếp của em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT400','S133','Nói lời chia tay và cảm ơn thầy cô, bạn bè',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V400','SIT400','P1','suon_se','ban_chinh_thuc',NULL,'学生毕业离校前主动和老师当面道别是尊师礼仪，中国人习惯祝福对方前路顺遂、常保持联络。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_01','V400','阮明',1,'李老师，我下周就要回国了，今天特地来和您道别。','lǐ lǎo shī， wǒ xià zhōu jiù yào huí guó le， jīn tiān tè dì lái hé nín dào bié。','Thầy Lý ơi, tuần sau em về nước rồi, hôm nay em đến để chào tạm biệt thầy ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_02','V400','李老师',2,'时间过得真快，这两年你的汉语进步特别明显啊。','shí jiān guò dé zhēn kuài， zhè liǎng nián nǐ de hàn yǔ jìn bù tè bié míng xiǎn a。','Thời gian trôi nhanh thật đấy, hai năm qua tiếng Trung của em tiến bộ rõ rệt lắm.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_03','V400','阮明',3,'多亏您一直耐心辅导我，我心里特别感激呢。','duō kuī nín yì zhí nài xīn fǔ dǎo wǒ， wǒ xīn lǐ tè bié gǎn jī ne。','Nhờ thầy kiên nhẫn kèm cặp em suốt thời gian qua, em cảm kích lắm ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_04','V400','李老师',4,'以后回国也要坚持练习汉语，有空常联系吧。','yǐ hòu huí guó yě yào jiān chí liàn xí hàn yǔ， yǒu kòng cháng lián xì ba。','Về nước rồi cũng phải chăm chỉ luyện tiếng Trung nhé, rảnh thì thường xuyên liên lạc với thầy đó.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_05','V400','阮明',5,'我回国会经常给您发消息，也会记得和同学们保持联络。','wǒ huí guó huì jīng cháng gěi nín fā xiāo xī， yě huì jì de hé tóng xué men bǎo chí lián luò。','Em về nước sẽ thường xuyên nhắn tin cho thầy, và cũng sẽ nhớ giữ liên lạc với các bạn cùng lớp nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_06','V400','李老师',6,'一路平安，祝你回国之后一切顺利。','yí lù píng ān， zhù nǐ huí guó zhī hòu yī qiè shùn lì。','Chúc em thượng lộ bình an, mong mọi việc của em sau khi về nước đều suôn sẻ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_07','V400','阮明',7,'谢谢老师两年的照顾，我永远不会忘记这段时光。','xiè xiè lǎo shī liǎng nián de zhào gù， wǒ yǒng yuǎn bú huì wàng jì zhè duàn shí guāng。','Em cảm ơn thầy đã chăm sóc em suốt hai năm qua, em sẽ không bao giờ quên khoảng thời gian này.',NULL);
